-- Catalog presence is not enablement. A separately reviewed change is required
-- after isolated runtime, concurrency and recovery acceptance.
create function app.operational_event_finance_proposals_enabled_v1()returns boolean
language sql immutable set search_path=''as $$select false$$;

create table app.operational_event_finance_operations_v1(
 actor_id uuid not null references app.profiles(id),
 operation_id uuid not null,
 tournament_id uuid not null,
 event_id uuid not null,
 request_payload jsonb not null,
 request_hash text not null check(request_hash~'^[a-f0-9]{64}$'),
 created_at timestamptz not null default clock_timestamp(),
 primary key(actor_id,operation_id),
 unique(actor_id,operation_id,tournament_id,event_id),
 foreign key(event_id,tournament_id)references app.events(id,tournament_id),
 check(request_hash=encode(extensions.digest(convert_to(jsonb_build_array(
  'operational-event-finance-proposal-v1',actor_id,tournament_id,event_id,
  operation_id,request_payload
 )::text,'utf8'),'sha256'),'hex'))
);

create table app.operational_event_finance_revisions_v1(
 id uuid primary key default extensions.gen_random_uuid(),
 tournament_id uuid not null,event_id uuid not null,
 version integer not null check(version between 1 and 2147483647),
 prior_revision_id uuid,
 actor_id uuid not null,operation_id uuid not null,
 binding_id uuid not null,activation_id uuid not null,
 setup_event_version_id uuid not null,settings_snapshot_id uuid not null,
 context_review_id uuid not null,native_allocation_revision_id uuid not null,
 qualification_result_version_id uuid,
 source_digest text not null check(source_digest~'^[a-f0-9]{64}$'),
 basis_digest text not null check(basis_digest~'^[a-f0-9]{64}$'),
 source_capture jsonb not null,basis jsonb not null,editor jsonb not null,
 reason text not null,
 proposal_only boolean not null default true check(proposal_only),
 money_moved boolean not null default false check(not money_moved),
 finalization_authorized boolean not null default false check(not finalization_authorized),
 payout_authorized boolean not null default false check(not payout_authorized),
 created_at timestamptz not null default clock_timestamp(),
 unique(tournament_id,event_id,version),
 unique(id,tournament_id,event_id),
 unique(actor_id,operation_id),
 foreign key(event_id,tournament_id)references app.events(id,tournament_id),
 foreign key(prior_revision_id,tournament_id,event_id)
  references app.operational_event_finance_revisions_v1(id,tournament_id,event_id),
 foreign key(actor_id,operation_id,tournament_id,event_id)
  references app.operational_event_finance_operations_v1(actor_id,operation_id,tournament_id,event_id),
 foreign key(binding_id)references app.event_settings_operational_bindings_v1(id),
 foreign key(activation_id)references app.tournament_setup_activations(id),
 foreign key(setup_event_version_id)references app.tournament_setup_event_versions(id),
 foreign key(settings_snapshot_id)references app.event_settings_snapshots_v3(id),
 foreign key(context_review_id)references app.event_rule_context_reviews_v1(id),
 foreign key(native_allocation_revision_id,tournament_id)
  references app.native_ledger_allocation_revisions_v1(id,tournament_id),
 foreign key(qualification_result_version_id,tournament_id,event_id)
  references app.qualification_result_versions(id,tournament_id,event_id),
 check(reason=app.custom_payout_classification_text_v2(reason)
  and app.event_settings_js_text_length_v3(reason)between 1 and 2000)
);

create table app.operational_event_finance_outcomes_v1(
 actor_id uuid not null,operation_id uuid not null,
 tournament_id uuid not null,event_id uuid not null,
 result jsonb not null,created_at timestamptz not null default clock_timestamp(),
 primary key(actor_id,operation_id),
 foreign key(actor_id,operation_id,tournament_id,event_id)
  references app.operational_event_finance_operations_v1(actor_id,operation_id,tournament_id,event_id)
);

do $$declare n text;begin
 foreach n in array array[
  'operational_event_finance_operations_v1',
  'operational_event_finance_revisions_v1',
  'operational_event_finance_outcomes_v1'
 ]loop
  execute format('alter table app.%I owner to postgres',n);
  execute format('alter table app.%I enable row level security',n);
  execute format('alter table app.%I force row level security',n);
  execute format('revoke all on table app.%I from public,anon,authenticated,service_role',n);
  execute format('create trigger %I before update or delete on app.%I for each row execute function app.reject_immutable_history()',n||'_immutable',n);
 end loop;
end$$;

create index operational_event_finance_revisions_head_v1
 on app.operational_event_finance_revisions_v1(tournament_id,event_id,version desc);

-- The native source reader is statement-consistent only. Proposal reads and
-- writes take its complete SHARE/NOWAIT reservation and additionally freeze
-- operational bindings, allocation heads and qualification heads.
create function app.lock_operational_event_finance_sources_v1()returns void
language plpgsql security definer set search_path=''as $$
begin
 perform app.lock_native_ledger_sources_v1();
 perform app.lock_event_settings_playoff_sources_v1();
 lock table app.event_settings_operational_bindings_v1,
  app.event_settings_snapshots_v3,app.event_rule_context_reviews_v1,
  app.native_ledger_allocation_operations_v1,
  app.native_ledger_allocation_outcomes_v1,
  app.native_ledger_allocation_revisions_v1,
  app.qualification_result_versions in share mode nowait;
end$$;

-- Actor is explicit only for private composition. Every caller must separately
-- establish auth.uid/current role; this helper repeats the current role check.
create function app.operational_event_finance_source_v1(
 tid uuid,eid uuid,actor uuid
)returns jsonb
language plpgsql security definer set search_path=''as $$
declare
 t app.tournaments%rowtype;e app.events%rowtype;
 b app.event_settings_operational_bindings_v1%rowtype;
 activation app.tournament_setup_activations%rowtype;
 setup_event app.tournament_setup_event_versions%rowtype;
 settings_snapshot app.event_settings_snapshots_v3%rowtype;
 review app.event_rule_context_reviews_v1%rowtype;
 allocation app.native_ledger_allocation_revisions_v1%rowtype;
 qualification app.qualification_result_versions%rowtype;
 current_native jsonb;current_facts jsonb;event_sources jsonb;
 raw_capture jsonb;source_value jsonb;coverage jsonb;workspace jsonb;basis jsonb;
 source_digest text;basis_digest text;settings_value jsonb;source_ref jsonb;
 history_value jsonb;line_value jsonb;part jsonb;source_row jsonb;
 active_count integer;paid_count integer;entry_fee numeric;gross numeric:=0;
 benefit numeric:=0;expense numeric:=0;regular_parts integer:=0;
 paid_semantics boolean:=true;line_ids text[]:='{}';line_id text;md text;
 seen_sources text[]:='{}';seen_buckets text[];source_id text;
 qualification_value jsonb:=null;event_source_count integer;
begin
 if current_setting('transaction_isolation')<>'read committed'then
  return jsonb_build_object('status','retry_exact','code','isolation_not_supported');
 end if;
 if tid is null or eid is null or actor is null then
  return jsonb_build_object('status','blocked','code','invalid_request');
 end if;
 perform 1 from app.tournaments where id=tid for share nowait;
 if not found then return jsonb_build_object('status','blocked','code','tournament_unavailable');end if;
 perform 1 from app.tournament_roles
  where tournament_id=tid and profile_id=actor and role in('director','co_director')
  order by role for key share nowait;
 if not found then return jsonb_build_object('status','blocked','code','not_director');end if;
 perform app.lock_operational_event_finance_sources_v1();
 select*into t from app.tournaments where id=tid;
 select*into e from app.events where id=eid and tournament_id=tid and operational_state='active';
 if e.id is null or e.event_type not in('main','consolation')or e.format<>'standard_singles'then
  return jsonb_build_object('status','blocked','code','unsupported_event_scope');
 end if;
 select*into b from app.event_settings_operational_bindings_v1
  where tournament_id=tid and event_id=eid;
 if b.id is null then return jsonb_build_object('status','blocked','code','operational_binding_required');end if;
 select*into activation from app.tournament_setup_activations
  where id=b.activation_id and tournament_id=tid and event_id=eid
   and setup_event_version_id=b.setup_event_version_id;
 select*into setup_event from app.tournament_setup_event_versions
  where id=b.setup_event_version_id and tournament_id=tid
   and event_kind=e.event_type and format_code='standard_singles'and style_code='Standard';
 select*into settings_snapshot from app.event_settings_snapshots_v3
  where id=b.settings_snapshot_id and tournament_id=tid;
 select*into review from app.event_rule_context_reviews_v1
  where id=b.review_id and tournament_id=tid
   and setup_event_version_id=b.setup_event_version_id
   and settings_snapshot_id=b.settings_snapshot_id;
 if activation.id is null or setup_event.id is null or settings_snapshot.id is null
  or review.id is null or review.draft is distinct from b.draft
  or review.context is distinct from b.context
  or not exists(
   select 1 from jsonb_array_elements(settings_snapshot.effective_settings)x
   where x->>'eventClientRowId'=setup_event.client_row_id::text
    and x->>'mode'='configured'and x->'draft'=b.draft
  )then return jsonb_build_object('status','blocked','code','binding_or_settings_changed');
 end if;
 if not app.valid_event_parameters_raw_v3(b.draft)then
  return jsonb_build_object('status','blocked','code','settings_invalid');
 end if;
 current_native:=app.get_native_event_ledger_sources_v1(tid);
 if current_native->>'status'='retry_exact'then return current_native;end if;
 if current_native->>'status'is distinct from'sources_available'
  or current_native->>'tournamentId'is distinct from tid::text then
  return jsonb_build_object('status','blocked','code','native_source_unavailable');
 end if;
 current_facts:=current_native->'facts';
 if current_facts->'existingOptionalAllocationEvidence'is distinct from'false'::jsonb then
  return jsonb_build_object('status','blocked','code','optional_pool_bridge_required');
 end if;
 select*into allocation from app.native_ledger_allocation_revisions_v1
  where tournament_id=tid order by version desc limit 1;
 if allocation.id is null or allocation.source_digest is distinct from current_native->>'sourceDigest'
  or allocation.snapshot->>'kind'is distinct from'event-ledger-snapshot-v1'
  or allocation.snapshot->>'mode'is distinct from'documented_actual'
  or allocation.snapshot->'complete'is distinct from'true'::jsonb
  or allocation.snapshot->>'tournamentId'is distinct from tid::text
  or allocation.snapshot->>'sourceDigest'is distinct from allocation.source_digest
  or not(allocation.snapshot->'eventIds'?eid::text)then
  return jsonb_build_object('status','blocked','code','current_native_allocation_required');
 end if;
 entry_fee:=setup_event.entry_fee_cents;
 if entry_fee is null or entry_fee<0 then
  return jsonb_build_object('status','blocked','code','entry_fee_unavailable');
 end if;
 select count(*)into active_count from app.event_participants p
  where p.tournament_id=tid and p.event_id=eid and p.status in('registered','checked_in');

 -- Preserve each physical source amount while filtering allocation parts to
 -- this operational event. No Q/Side/income source is synthesized.
 select coalesce(jsonb_agg(jsonb_build_object(
  'sourceId',s->>'sourceId','physicalEvidenceId',s->>'physicalEvidenceId',
  'kind',s->>'kind','amountMinor',(s->>'amountMinor')::numeric,
  'state',s->>'state','allocations',filtered.parts
 )order by s->>'sourceId'),'[]'::jsonb)into event_sources
 from jsonb_array_elements(allocation.snapshot->'sources')s
 cross join lateral(
  select coalesce(jsonb_agg(p order by p->>'bucket'),'[]'::jsonb)parts
  from jsonb_array_elements(s->'allocations')p where p->>'eventId'=eid::text
 )filtered
 where jsonb_array_length(filtered.parts)>0;
 event_source_count:=jsonb_array_length(event_sources);
 if event_source_count>10000 then return jsonb_build_object('status','blocked','code','technical_resource_bound');end if;

 history_value:='[]'::jsonb;
 for source_row in select value from jsonb_array_elements(event_sources)order by value->>'sourceId'loop
  source_id:=source_row->>'sourceId';seen_buckets:='{}';
  if coalesce(source_row->>'sourceId','')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
   or coalesce(source_row->>'physicalEvidenceId','')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
   or source_row->>'physicalEvidenceId'is distinct from source_id
   or source_row->>'state'is distinct from'active'
   or source_row->>'kind'not in('entry_receipt','expense')
   or jsonb_typeof(source_row->'amountMinor')is distinct from'number'
   or(source_row->>'amountMinor')!~'^[1-9][0-9]*$'
   or(source_row->>'amountMinor')::numeric>9007199254740991
   or source_id=any(seen_sources)then
   return jsonb_build_object('status','blocked','code','invalid_allocation_source');
  end if;
  seen_sources:=array_append(seen_sources,source_id);
  for part in select value from jsonb_array_elements(source_row->'allocations')order by value->>'bucket'loop
   if jsonb_typeof(part)is distinct from'object'
    or(select count(*)from jsonb_object_keys(part))<>5
    or not(part?&array['eventId','bucket','poolId','amountMinor','classificationReviewed'])
    or part->>'eventId'is distinct from eid::text
    or part->'poolId'is distinct from'null'::jsonb
    or part->'classificationReviewed'is distinct from'true'::jsonb
    or part->>'bucket'not in('regular_entry','player_benefit','operating_expense')
    or jsonb_typeof(part->'amountMinor')is distinct from'number'
    or(part->>'amountMinor')!~'^[1-9][0-9]*$'
    or(part->>'amountMinor')::numeric>9007199254740991
    or(source_row->>'kind'='entry_receipt'and part->>'bucket'<>'regular_entry')
    or(source_row->>'kind'='expense'and part->>'bucket'='regular_entry')
    or(part->>'bucket')=any(seen_buckets)then
    return jsonb_build_object('status','blocked','code','unsupported_or_unreviewed_allocation');
   end if;
   seen_buckets:=array_append(seen_buckets,part->>'bucket');
   if part->>'bucket'='regular_entry'then
    gross:=gross+(part->>'amountMinor')::numeric;regular_parts:=regular_parts+1;
    if(part->>'amountMinor')::numeric<>entry_fee
     or not exists(select 1 from jsonb_array_elements(current_facts->'receiptEvents')r
      where r->>'sourceId'=source_row->>'sourceId'
       and r->'eligibleEventIds'?eid::text
       and(r->>'amountMinor')::numeric>=(part->>'amountMinor')::numeric)then
     paid_semantics:=false;
    end if;
   else
    if part->>'bucket'='player_benefit'then benefit:=benefit+(part->>'amountMinor')::numeric;
    else expense:=expense+(part->>'amountMinor')::numeric;end if;
    md:=encode(extensions.digest(convert_to(
     'operational-finance-basis-line-v1|'||tid::text||'|'||eid::text||'|'||
     allocation.id::text||'|'||(source_row->>'sourceId')||'|'||(part->>'bucket'),'utf8'
    ),'md5'),'hex');
    line_id:=substring(md,1,8)||'-'||substring(md,9,4)||'-'||substring(md,13,4)||'-'||substring(md,17,4)||'-'||substring(md,21,12);
    if line_id=any(line_ids)then return jsonb_build_object('status','blocked','code','basis_identity_collision');end if;
    line_ids:=array_append(line_ids,line_id);
    line_value:=jsonb_build_object(
     'label',case part->>'bucket'when'player_benefit'then'Allocated Player Benefit'else'Allocated Operating Expense'end,
     'line',jsonb_build_object(
      'recordId',line_id,'lineId',line_id,'priorRecordId',null,
      'source',null,'mode','estimate',
      'category',part->>'bucket','amountMinor',(part->>'amountMinor')::numeric,
      'voided',false,'reason','Recorded allocation basis'
     )
    );
    history_value:=history_value||jsonb_build_array(line_value);
   end if;
  end loop;
 end loop;
 if gross>9007199254740991 or benefit>9007199254740991 or expense>9007199254740991
  or benefit+expense>9007199254740991 then
  return jsonb_build_object('status','blocked','code','unsafe_finance_total');
 end if;
 if paid_semantics then
  select count(distinct r->>'rosterEntryId')into paid_count
  from jsonb_array_elements(current_facts->'receiptEvents')r
  where exists(select 1 from jsonb_array_elements(event_sources)s
   cross join lateral jsonb_array_elements(s->'allocations')p
   where s->>'sourceId'=r->>'sourceId'and p->>'bucket'='regular_entry');
  if paid_count<>regular_parts then paid_semantics:=false;paid_count:=null;end if;
 else paid_count:=null;end if;
 select*into qualification from app.qualification_result_versions
  where tournament_id=tid and event_id=eid order by version desc limit 1;
 if qualification.id is not null then
  if app.qualification_resolution_snapshot_current_v1(qualification.id)is distinct from true
   then return jsonb_build_object('status','blocked','code','qualification_source_changed');end if;
  if qualification.participant_count<1
   or qualification.qualifier_count<>(qualification.participant_count+3)/4 then
   return jsonb_build_object('status','blocked','code','qualification_source_invalid');
  end if;
  qualification_value:=jsonb_build_object(
   'resultVersionId',qualification.id,'version',qualification.version,
   'participantCount',qualification.participant_count,
   'qualifierCount',qualification.qualifier_count
  );
 end if;
 coverage:=jsonb_build_object(
  'additionalIncome','unavailable',
  'optionalPools','isolated_regular_allocation',
  'recordedFundAvailable',false
 );
 raw_capture:=jsonb_build_object(
  'binding',jsonb_build_object('bindingId',b.id,'activationId',b.activation_id,
   'setupEventVersionId',b.setup_event_version_id,
   'settingsSnapshotId',b.settings_snapshot_id,'reviewId',b.review_id),
  'event',jsonb_build_object('tournamentName',t.name,'eventName',e.name,
   'eventKind',e.event_type,'format',e.format,'operationalState',e.operational_state,
  'startLabel',coalesce(to_char(t.planned_start_date,'FMMonth FMDD, YYYY'),'Date unavailable')),
  'settings',jsonb_build_object('draft',b.draft,'context',b.context),
  'allocation',jsonb_build_object('revisionId',allocation.id,'version',allocation.version,
   'sourceDigest',allocation.source_digest,
   'createdAt',to_char(allocation.created_at at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
   'eventSources',event_sources),
  'counts',jsonb_build_object('activeParticipants',active_count,
   'paidEligibleEntries',paid_count),
  'qualification',qualification_value,'coverage',coverage
 );
 source_digest:=encode(extensions.digest(convert_to(jsonb_build_array(
  'operational-event-finance-source-v1',tid,eid,raw_capture
 )::text,'utf8'),'sha256'),'hex');
 source_ref:=jsonb_build_object('tournamentId',tid,'eventId',eid,
  'sourceVersion',allocation.version,'sourceDigest',source_digest);
 -- Insert the now-known shared source into every deterministic basis line.
 select coalesce(jsonb_agg(jsonb_set(x.value,'{line,source}',source_ref,true)order by x.n),'[]'::jsonb)
  into history_value from jsonb_array_elements(history_value)with ordinality x(value,n);
 settings_value:=case b.draft->>'payoutMode'
  when'graduated'then jsonb_build_object('method','graduated_all_qualifiers','factor',b.draft->>'incrementFactorText')
  when'top'then jsonb_build_object('method','custom_top_paid','paidPlaces',(b.draft->>'topText')::integer,'factor',b.draft->>'incrementFactorText')
  when'one-in'then jsonb_build_object('method','custom_paid_ratio','ratio',(b.draft->>'oneInText')::integer,'factor',b.draft->>'incrementFactorText')
  else null end;
 if settings_value is null or coalesce(b.draft->>'incrementFactorText','')!~'^(0|[1-9][0-9]*)(\.[0-9]{1,6})?$'
  or(b.draft->>'incrementFactorText')::numeric<1
  or(b.draft->>'incrementFactorText')::numeric>1000 then
  return jsonb_build_object('status','blocked','code','payout_settings_unavailable');
 end if;
 workspace:=jsonb_build_object(
  'complete',true,'source',source_ref,'mode','estimate',
  'tournamentName',t.name,'eventName',e.name,'eventKind',e.event_type,
  'startLabel',coalesce(to_char(t.planned_start_date,'FMMonth FMDD, YYYY'),'Date unavailable'),
  'entryCount',active_count,'paidEntryCount',paid_count,
  'qualifierCount',case when qualification.id is null then null else qualification.qualifier_count end,
  'grossEntryMinor',gross,'history',history_value,'settings',settings_value,
  'payoutSource',jsonb_build_object('tournamentId',tid,'eventId',eid,
   'settingsSnapshotId',b.settings_snapshot_id,'ledgerDigest',source_digest,
   'resultsDigest',source_digest),
  'savedAt',to_char(allocation.created_at at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
  'overrideHistory','[]'::jsonb
 );
 basis:=jsonb_build_object('kind','operational-finance-estimate-basis-v1',
  'sourceDigest',source_digest,'coverage',coverage,'workspace',workspace);
 basis_digest:=encode(extensions.digest(convert_to(jsonb_build_array(
  'operational-finance-estimate-basis-v1',basis
 )::text,'utf8'),'sha256'),'hex');
 source_value:=jsonb_build_object(
  'status','source_available','kind','operational-event-finance-source-v1',
  'actorId',actor,'tournamentId',tid,'eventId',eid,
  'sourceDigest',source_digest,'raw',raw_capture,'basis',basis,
  'basisDigest',basis_digest,'proposalOnly',true,'moneyMoved',false,
  'finalizationAuthorized',false,'payoutAuthorized',false
 );
 return source_value;
exception when lock_not_available then return jsonb_build_object('status','retry_exact','code','source_busy');
 when invalid_text_representation or numeric_value_out_of_range then
  return jsonb_build_object('status','blocked','code','source_shape_invalid');
end$$;

create function app.get_operational_event_finance_source_v1(tid uuid,eid uuid)returns jsonb
language plpgsql security definer set search_path=''as $$
declare a uuid:=auth.uid();begin
 if a is null then return jsonb_build_object('status','blocked','code','authentication_required');end if;
 return app.operational_event_finance_source_v1(tid,eid,a);
end$$;

-- Structural mirror of the existing V1 editor. It validates the authoritative
-- basis, append-only histories, zero/incomplete forms and whole-band/$5 rules.
-- It intentionally does not duplicate factor-based award calculation.
create function app.valid_operational_event_finance_editor_v1(
 editor jsonb,basis jsonb,prior_editor jsonb default null
)returns boolean
language plpgsql immutable set search_path=''as $$
declare w jsonb;history jsonb;overrides jsonb;r jsonb;line jsonb;old jsonb;
 latest jsonb:='{}'::jsonb;records text[]:='{}';k text;oldcat text;cat text;
 base_count integer;old_count integer;override_latest jsonb:='{}'::jsonb;
 first_place integer;last_place integer;qualifiers integer;award_places integer;fund numeric;gross numeric;
 override_ids text[]:='{}';
 benefit numeric:=0;expense numeric:=0;income numeric:=0;plan jsonb;plan_history jsonb;
 plan_latest jsonb:='{}'::jsonb;plan_benefit numeric:=0;plan_expense numeric:=0;
 plan_income numeric:=0;plan_fund numeric;override_total numeric:=0;
begin
 if jsonb_typeof(editor)is distinct from'object'
  or(select count(*)from jsonb_object_keys(editor))<>8
  or not(editor?&array['basis','history','overrideHistory','overrideInput','overridePlan','lineForm','bandForm','message'])
  or editor->'basis'is distinct from basis->'workspace'
  or jsonb_typeof(editor->'history')is distinct from'array'
  or jsonb_typeof(editor->'overrideHistory')is distinct from'array'
  or jsonb_typeof(editor->'message')is distinct from'string'
  or app.event_settings_js_text_length_v3(editor->>'message')>4000
  or jsonb_array_length(editor->'history')>10000
  or jsonb_array_length(editor->'overrideHistory')>10000
  or octet_length(editor::text)>4000000 then return false;end if;
 w:=basis->'workspace';history:=editor->'history';overrides:=editor->'overrideHistory';
 if jsonb_typeof(w)is distinct from'object'
  or jsonb_typeof(w->'mode')is distinct from'string'
  or w->>'mode'is distinct from'estimate'
  or w->'complete'is distinct from'true'::jsonb
  or jsonb_typeof(w->'history')is distinct from'array'
  or jsonb_typeof(w->'overrideHistory')is distinct from'array'
  or jsonb_array_length(w->'overrideHistory')<>0 then return false;end if;
 base_count:=jsonb_array_length(w->'history');
 if jsonb_array_length(history)<base_count
  or exists(select 1 from jsonb_array_elements(w->'history')with ordinality x(value,n)
   where value is distinct from history->((n-1)::integer))then return false;end if;
 if prior_editor is not null then
  if jsonb_typeof(prior_editor)is distinct from'object'or prior_editor->'basis'is distinct from w then return false;end if;
  old_count:=jsonb_array_length(prior_editor->'history');
  if jsonb_array_length(history)<old_count
   or exists(select 1 from jsonb_array_elements(prior_editor->'history')with ordinality x(value,n)
    where value is distinct from history->((n-1)::integer))then return false;end if;
  old_count:=jsonb_array_length(prior_editor->'overrideHistory');
  if jsonb_array_length(overrides)<old_count
   or exists(select 1 from jsonb_array_elements(prior_editor->'overrideHistory')with ordinality x(value,n)
    where value is distinct from overrides->((n-1)::integer))then return false;end if;
 end if;
 for r in select value from jsonb_array_elements(history)loop
  if jsonb_typeof(r)is distinct from'object'or(select count(*)from jsonb_object_keys(r))<>2
   or not(r?&array['label','line'])or jsonb_typeof(r->'label')is distinct from'string'
   or r->>'label'<>app.custom_payout_classification_text_v2(r->>'label')
   or app.event_settings_js_text_length_v3(r->>'label')not between 1 and 200 then return false;end if;
  line:=r->'line';
  if jsonb_typeof(line)is distinct from'object'or(select count(*)from jsonb_object_keys(line))<>9
   or not(line?&array['recordId','lineId','priorRecordId','source','mode','category','amountMinor','voided','reason'])
   or coalesce(line->>'recordId','')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
   or coalesce(line->>'lineId','')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
   or not(line->'priorRecordId'='null'::jsonb or(jsonb_typeof(line->'priorRecordId')='string'and line->>'priorRecordId'~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'))
    or line->'source'is distinct from w->'source'
    or jsonb_typeof(line->'mode')is distinct from'string'
    or line->>'mode'is distinct from'estimate'
    or jsonb_typeof(line->'category')is distinct from'string'
    or coalesce(line->>'category','')not in('player_benefit','operating_expense','unrestricted_income')
   or jsonb_typeof(line->'amountMinor')is distinct from'number'
   or(line->>'amountMinor')!~'^(0|[1-9][0-9]*)$'
   or(line->>'amountMinor')::numeric>9007199254740991
   or jsonb_typeof(line->'voided')is distinct from'boolean'
   or jsonb_typeof(line->'reason')is distinct from'string'
   or length(app.custom_payout_classification_text_v2(line->>'reason'))=0
    or line->>'reason'is distinct from app.custom_payout_classification_text_v2(line->>'reason')
   or app.event_settings_js_text_length_v3(line->>'reason')>2000 then return false;end if;
  k:=line->>'lineId';old:=latest->k;cat:=line->>'category';
  if line->>'recordId'=any(records)
   or(old is null and line->'priorRecordId'<>'null'::jsonb)
   or(old is not null and line->'priorRecordId'is distinct from old->'recordId')
   or((old is not null or(line->>'voided')::boolean)
      and length(app.custom_payout_classification_text_v2(line->>'reason'))=0)
   or((line->>'voided')::boolean and(line->>'amountMinor')::numeric<>0)then return false;end if;
  if old is not null then oldcat:=old->>'category';if oldcat<>cat then return false;end if;end if;
  records:=array_append(records,line->>'recordId');latest:=jsonb_set(latest,array[k],line,true);
 end loop;
 for line in select value from jsonb_each(latest)loop
  if not(line->>'voided')::boolean then
   if line->>'category'='player_benefit'then benefit:=benefit+(line->>'amountMinor')::numeric;
   elsif line->>'category'='operating_expense'then expense:=expense+(line->>'amountMinor')::numeric;
   else income:=income+(line->>'amountMinor')::numeric;end if;
  end if;
 end loop;
 gross:=(w->>'grossEntryMinor')::numeric;fund:=gross-benefit-expense+income;
 if gross<0 or fund<0 or greatest(benefit,expense,income,fund)>9007199254740991 then return false;end if;
 qualifiers:=case when w->'qualifierCount'='null'::jsonb then null else(w->>'qualifierCount')::integer end;
 award_places:=case when qualifiers is null then null
  when w#>>'{settings,method}'='custom_top_paid'then least(qualifiers,(w#>>'{settings,paidPlaces}')::integer)
  else qualifiers end;

 -- Incomplete forms are retained as strings, but their object/identity shape is exact.
 if editor->'lineForm'<>'null'::jsonb then
  line:=editor->'lineForm';
  if jsonb_typeof(line)is distinct from'object'or(select count(*)from jsonb_object_keys(line))<>5
   or not(line?&array['category','lineId','label','amount','reason'])
    or jsonb_typeof(line->'category')is distinct from'string'
    or coalesce(line->>'category','')not in('player_benefit','operating_expense','unrestricted_income')
   or not(line->'lineId'='null'::jsonb or(jsonb_typeof(line->'lineId')='string'and line->>'lineId'~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'))
   or jsonb_typeof(line->'label')is distinct from'string'or app.event_settings_js_text_length_v3(line->>'label')>200
   or jsonb_typeof(line->'amount')is distinct from'string'or app.event_settings_js_text_length_v3(line->>'amount')>20
    or jsonb_typeof(line->'reason')is distinct from'string'or app.event_settings_js_text_length_v3(line->>'reason')>2000 then return false;end if;
   if line->'lineId'<>'null'::jsonb then
    old:=latest->(line->>'lineId');
    if old is null or(old->>'voided')::boolean
     or old->>'category'is distinct from line->>'category'
     or coalesce(old->>'category','')not in('player_benefit','operating_expense','unrestricted_income')then return false;end if;
   end if;
 end if;
 if editor->'bandForm'<>'null'::jsonb then
  line:=editor->'bandForm';
  if jsonb_typeof(line)is distinct from'object'or(select count(*)from jsonb_object_keys(line))<>4
   or not(line?&array['firstPlace','lastPlace','amount','reason'])
   or jsonb_typeof(line->'firstPlace')is distinct from'number'or(line->>'firstPlace')!~'^(0|[1-9][0-9]*)$'
   or jsonb_typeof(line->'lastPlace')is distinct from'number'or(line->>'lastPlace')!~'^(0|[1-9][0-9]*)$'
   or jsonb_typeof(line->'amount')is distinct from'string'or app.event_settings_js_text_length_v3(line->>'amount')>20
    or jsonb_typeof(line->'reason')is distinct from'string'or app.event_settings_js_text_length_v3(line->>'reason')>2000
    or qualifiers is null or qualifiers<1
    or(line->>'firstPlace')::integer<1
    or(line->>'lastPlace')::integer<(line->>'firstPlace')::integer
    or(line->>'lastPlace')::integer>award_places
    or not((line->>'firstPlace')::integer=1 and(line->>'lastPlace')::integer=1)
      and not((line->>'firstPlace')::integer=2 and(line->>'lastPlace')::integer=2)
      and not((line->>'firstPlace')::integer>=3
       and(line->>'firstPlace')::integer=(case when(line->>'firstPlace')::integer=3 then 3 else(((line->>'firstPlace')::integer+1)/2)*2-1 end)
       and(((line->>'firstPlace')::integer-1)&((line->>'firstPlace')::integer-2))=0
       and(line->>'lastPlace')::integer=least(award_places,((line->>'firstPlace')::integer-1)*2))then return false;end if;
 end if;
 if jsonb_array_length(overrides)=0 then
  if editor->'overrideInput'<>'null'::jsonb or editor->'overridePlan'<>'null'::jsonb then return false;end if;
 else
  if qualifiers is null or qualifiers<1 or w#>>'{settings,method}'='custom_paid_ratio'then return false;end if;
   if jsonb_typeof(editor->'overrideInput')is distinct from'object'
   or(select count(*)from jsonb_object_keys(editor->'overrideInput'))<>3
   or editor#>'{overrideInput,qualifierCount}'is distinct from to_jsonb(qualifiers)
   or editor#>'{overrideInput,settings}'is distinct from w->'settings'
   or jsonb_typeof(editor->'overridePlan')is distinct from'string'
   or app.event_settings_js_text_length_v3(editor->>'overridePlan')>4000000 then return false;end if;
  begin plan:=(editor->>'overridePlan')::jsonb;exception when others then return false;end;
   if jsonb_typeof(plan)is distinct from'object'or(select count(*)from jsonb_object_keys(plan))<>2
    or plan->'basis'is distinct from w or jsonb_typeof(plan->'history')is distinct from'array'
    or jsonb_array_length(plan->'history')>jsonb_array_length(history)
    or exists(select 1 from jsonb_array_elements(plan->'history')with ordinality x(value,n)
     where value is distinct from history->((n-1)::integer))then return false;end if;
   plan_history:=plan->'history';
   if not app.valid_operational_event_finance_editor_v1(jsonb_build_object(
    'basis',w,'history',plan_history,'overrideHistory','[]'::jsonb,
    'overrideInput',null,'overridePlan',null,'lineForm',null,'bandForm',null,'message',''
   ),basis,null)then return false;end if;
   for r in select value from jsonb_array_elements(plan_history)loop
    line:=r->'line';plan_latest:=jsonb_set(plan_latest,array[line->>'lineId'],line,true);
   end loop;
   for line in select value from jsonb_each(plan_latest)loop
    if not(line->>'voided')::boolean then
     if line->>'category'='player_benefit'then plan_benefit:=plan_benefit+(line->>'amountMinor')::numeric;
     elsif line->>'category'='operating_expense'then plan_expense:=plan_expense+(line->>'amountMinor')::numeric;
     else plan_income:=plan_income+(line->>'amountMinor')::numeric;end if;
    end if;
   end loop;
   plan_fund:=gross-plan_benefit-plan_expense+plan_income;
   if plan_fund<0 or plan_fund>9007199254740991
    or editor#>'{overrideInput,fundMinor}'is distinct from to_jsonb(plan_fund)then return false;end if;
 end if;
 for r in select value from jsonb_array_elements(overrides)loop
  if jsonb_typeof(r)is distinct from'object'or(select count(*)from jsonb_object_keys(r))<>7
   or not(r?&array['recordId','firstPlace','lastPlace','priorRecordId','perPersonMinor','voided','reason'])
   or coalesce(r->>'recordId','')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
   or jsonb_typeof(r->'firstPlace')is distinct from'number'or(r->>'firstPlace')!~'^[1-9][0-9]*$'
   or jsonb_typeof(r->'lastPlace')is distinct from'number'or(r->>'lastPlace')!~'^[1-9][0-9]*$'
   or(r->>'firstPlace')::numeric>2147483647 or(r->>'lastPlace')::numeric>2147483647
   or(r->>'firstPlace')::integer>(r->>'lastPlace')::integer
   or(r->>'lastPlace')::integer>award_places
   or not(r->'priorRecordId'='null'::jsonb or(jsonb_typeof(r->'priorRecordId')='string'and r->>'priorRecordId'~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'))
   or jsonb_typeof(r->'perPersonMinor')is distinct from'number'or(r->>'perPersonMinor')!~'^(0|[1-9][0-9]*)$'
   or(r->>'perPersonMinor')::numeric>9007199254740991
   or(r->>'perPersonMinor')::numeric%500<>0
   or jsonb_typeof(r->'voided')is distinct from'boolean'
   or jsonb_typeof(r->'reason')is distinct from'string'
   or length(app.custom_payout_classification_text_v2(r->>'reason'))=0
    or r->>'reason'is distinct from app.custom_payout_classification_text_v2(r->>'reason')
   or app.event_settings_js_text_length_v3(r->>'reason')>2000
   or r->>'recordId'=any(override_ids)then return false;end if;
  override_ids:=array_append(override_ids,r->>'recordId');
  first_place:=(r->>'firstPlace')::integer;last_place:=(r->>'lastPlace')::integer;k:=first_place||':'||last_place;
  -- Exact complete geometric cohort: 1, 2, 3-4, 5-8, ... truncated at qualifier count.
  if not(first_place=1 and last_place=1)
   and not(first_place=2 and last_place=2)
   and not(first_place>=3 and first_place=(case when first_place=3 then 3 else((first_place+1)/2)*2-1 end)
   and((first_place-1)&(first_place-2))=0
   and last_place=least(award_places,(first_place-1)*2))then return false;end if;
  old:=override_latest->k;
  if old is null and(r->'priorRecordId'<>'null'::jsonb or(r->>'voided')::boolean)then return false;end if;
  if old is not null and r->'priorRecordId'is distinct from old->'recordId'then return false;end if;
  override_latest:=jsonb_set(override_latest,array[k],r,true);
 end loop;
  for r in select value from jsonb_each(override_latest)loop
   if not(r->>'voided')::boolean then
    override_total:=override_total+((r->>'lastPlace')::integer-(r->>'firstPlace')::integer+1)*(r->>'perPersonMinor')::numeric;
   end if;
  end loop;
  if override_total>coalesce(plan_fund,fund)then return false;end if;
 return true;
exception when invalid_text_representation or numeric_value_out_of_range or division_by_zero then return false;
end$$;

create function app.finish_operational_event_finance_operation_v1(
 actor uuid,tid uuid,eid uuid,op uuid,result_value jsonb
)returns jsonb
language plpgsql security definer set search_path=''as $$
declare operation app.operational_event_finance_operations_v1%rowtype;result jsonb;begin
 select*into strict operation from app.operational_event_finance_operations_v1
  where actor_id=actor and operation_id=op and tournament_id=tid and event_id=eid;
 if result_value->>'status'not in('accepted','rejected')then raise exception'invalid_operational_finance_outcome';end if;
 result:=result_value||jsonb_build_object(
  'actorId',actor,'tournamentId',tid,'eventId',eid,'operationId',op,
  'request',operation.request_payload,'fullRequestHash',operation.request_hash,
  'proposalOnly',true,'moneyMoved',false,'finalizationAuthorized',false,
  'payoutAuthorized',false
 );
 insert into app.operational_event_finance_outcomes_v1(
  actor_id,operation_id,tournament_id,event_id,result
 )values(actor,op,tid,eid,result);
 return result;
end$$;

create function app.save_operational_event_finance_proposal_v1(
 tid uuid,eid uuid,request_value jsonb
)returns jsonb
language plpgsql security definer set search_path=''as $$
declare a uuid:=auth.uid();op uuid;request_hash text;
 prior app.operational_event_finance_operations_v1%rowtype;
 prior_result jsonb;head app.operational_event_finance_revisions_v1%rowtype;
 source_value jsonb;raw jsonb;basis jsonb;response jsonb;revision_id uuid;
 expected integer;reason_value text;qualification_id uuid;
begin
 if a is null then return jsonb_build_object('status','rejected','code','authentication_required');end if;
 if current_setting('transaction_isolation')<>'read committed'then return jsonb_build_object('status','retry_exact','code','isolation_not_supported');end if;
 if jsonb_typeof(request_value)is distinct from'object'
  or(select count(*)from jsonb_object_keys(request_value))<>7
  or not(request_value?&array['kind','operationId','expectedVersion','expectedSourceDigest','expectedBasisDigest','editor','reason'])
   or jsonb_typeof(request_value->'kind')is distinct from'string'
   or request_value->>'kind'is distinct from'operational-event-finance-proposal-v1'
   or jsonb_typeof(request_value->'operationId')is distinct from'string'
   or coalesce(request_value->>'operationId','')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
  or jsonb_typeof(request_value->'expectedVersion')is distinct from'number'
  or(request_value->>'expectedVersion')!~'^(0|[1-9][0-9]*)$'
   or(request_value->>'expectedVersion')::numeric>2147483646
  or coalesce(request_value->>'expectedSourceDigest','')!~'^[a-f0-9]{64}$'
  or coalesce(request_value->>'expectedBasisDigest','')!~'^[a-f0-9]{64}$'
  or jsonb_typeof(request_value->'editor')is distinct from'object'
  or jsonb_typeof(request_value->'reason')is distinct from'string'
  or request_value->>'reason'<>app.custom_payout_classification_text_v2(request_value->>'reason')
  or app.event_settings_js_text_length_v3(request_value->>'reason')not between 1 and 2000
  or octet_length(request_value::text)>4100000 then
  return jsonb_build_object('status','rejected','code','invalid_request');
 end if;
 op:=(request_value->>'operationId')::uuid;expected:=(request_value->>'expectedVersion')::integer;
 reason_value:=request_value->>'reason';
 if not pg_try_advisory_xact_lock(hashtextextended(a::text||':'||op::text,0))then return jsonb_build_object('status','retry_exact','code','operation_busy');end if;
 if not pg_try_advisory_xact_lock(hashtextextended('event-lifecycle:'||eid::text,0))then return jsonb_build_object('status','retry_exact','code','event_busy');end if;
 perform 1 from app.tournaments where id=tid for update nowait;
 if not found then return jsonb_build_object('status','rejected','code','tournament_unavailable');end if;
 perform 1 from app.tournament_roles where tournament_id=tid and profile_id=a and role in('director','co_director')order by role for key share nowait;
 if not found then return jsonb_build_object('status','rejected','code','not_director');end if;
 request_hash:=encode(extensions.digest(convert_to(jsonb_build_array(
  'operational-event-finance-proposal-v1',a,tid,eid,op,request_value
 )::text,'utf8'),'sha256'),'hex');
 select*into prior from app.operational_event_finance_operations_v1 where actor_id=a and operation_id=op;
 if found then
  if prior.tournament_id is distinct from tid or prior.event_id is distinct from eid
   or prior.request_hash is distinct from request_hash or prior.request_payload is distinct from request_value then
   return jsonb_build_object('status','rejected','code','idempotency_conflict');
  end if;
  select result into prior_result from app.operational_event_finance_outcomes_v1
   where actor_id=a and operation_id=op and tournament_id=tid and event_id=eid;
  if prior_result is null then return jsonb_build_object('status','retry_exact','code','operation_incomplete');end if;
  return prior_result||jsonb_build_object('historicalReceipt',true,'currentSourceVerified',false);
 end if;
 if app.operational_event_finance_proposals_enabled_v1()is distinct from true then
  return jsonb_build_object('status','rejected','code','feature_unavailable','proposalOnly',true,'moneyMoved',false,'finalizationAuthorized',false,'payoutAuthorized',false);
 end if;
 source_value:=app.operational_event_finance_source_v1(tid,eid,a);
 if source_value->>'status'='retry_exact'then return source_value;end if;
 if source_value->>'status'<>'source_available'then
  return jsonb_build_object('status','rejected','code',coalesce(source_value->>'code','source_unavailable'));
 end if;
 insert into app.operational_event_finance_operations_v1(
  actor_id,operation_id,tournament_id,event_id,request_payload,request_hash
 )values(a,op,tid,eid,request_value,request_hash);
 if source_value->>'sourceDigest'is distinct from request_value->>'expectedSourceDigest'
  or source_value->>'basisDigest'is distinct from request_value->>'expectedBasisDigest'then
  return app.finish_operational_event_finance_operation_v1(a,tid,eid,op,
   jsonb_build_object('status','rejected','code','source_changed'));
 end if;
 basis:=source_value->'basis';raw:=source_value->'raw';
 select*into head from app.operational_event_finance_revisions_v1
  where tournament_id=tid and event_id=eid order by version desc limit 1;
 if coalesce(head.version,0)<>expected then
  return app.finish_operational_event_finance_operation_v1(a,tid,eid,op,
   jsonb_build_object('status','rejected','code','stale_version'));
 end if;
 if head.id is not null and(head.source_digest is distinct from source_value->>'sourceDigest'
  or head.basis_digest is distinct from source_value->>'basisDigest')then
  return app.finish_operational_event_finance_operation_v1(a,tid,eid,op,
   jsonb_build_object('status','rejected','code','source_revision_changed_requires_review'));
 end if;
 if not app.valid_operational_event_finance_editor_v1(
  request_value->'editor',basis,head.editor
 )then
  return app.finish_operational_event_finance_operation_v1(a,tid,eid,op,
   jsonb_build_object('status','rejected','code','invalid_editor'));
 end if;
 qualification_id:=case when raw->'qualification'='null'::jsonb then null
  else(raw#>>'{qualification,resultVersionId}')::uuid end;
 insert into app.operational_event_finance_revisions_v1(
  tournament_id,event_id,version,prior_revision_id,actor_id,operation_id,
  binding_id,activation_id,setup_event_version_id,settings_snapshot_id,
  context_review_id,native_allocation_revision_id,qualification_result_version_id,
  source_digest,basis_digest,source_capture,basis,editor,reason
 )values(
  tid,eid,expected+1,head.id,a,op,
  (raw#>>'{binding,bindingId}')::uuid,(raw#>>'{binding,activationId}')::uuid,
  (raw#>>'{binding,setupEventVersionId}')::uuid,(raw#>>'{binding,settingsSnapshotId}')::uuid,
  (raw#>>'{binding,reviewId}')::uuid,(raw#>>'{allocation,revisionId}')::uuid,
  qualification_id,source_value->>'sourceDigest',source_value->>'basisDigest',
  raw,basis,request_value->'editor',reason_value
 )returning id into revision_id;
 response:=jsonb_build_object('status','accepted','code','operational_finance_proposal_saved',
  'revisionId',revision_id,'version',expected+1,'sourceDigest',source_value->>'sourceDigest',
  'basisDigest',source_value->>'basisDigest','historicalReceipt',false,
  'currentSourceVerified',true);
 return app.finish_operational_event_finance_operation_v1(a,tid,eid,op,response);
exception when lock_not_available then return jsonb_build_object('status','retry_exact','code','source_busy');
 when invalid_text_representation or numeric_value_out_of_range then
  return jsonb_build_object('status','rejected','code','invalid_request');
end$$;

create function app.reconcile_operational_event_finance_proposal_v1(
 tid uuid,eid uuid,op uuid
)returns jsonb
language plpgsql security definer set search_path=''as $$
declare a uuid:=auth.uid();operation app.operational_event_finance_operations_v1%rowtype;result jsonb;begin
 if a is null then return null;end if;
 if current_setting('transaction_isolation')<>'read committed'then return null;end if;
 perform 1 from app.tournaments where id=tid for share nowait;if not found then return null;end if;
 perform 1 from app.tournament_roles where tournament_id=tid and profile_id=a and role in('director','co_director')order by role for key share nowait;
 if not found then return null;end if;
 if not pg_try_advisory_xact_lock(hashtextextended(a::text||':'||op::text,0))then
  return jsonb_build_object('status','retry_exact','code','operation_busy');
 end if;
 select*into operation from app.operational_event_finance_operations_v1
  where actor_id=a and operation_id=op and tournament_id=tid and event_id=eid;
 if not found then return jsonb_build_object('status','unknown','actorId',a,'tournamentId',tid,'eventId',eid,'operationId',op);end if;
 select o.result into result from app.operational_event_finance_outcomes_v1 o
  where o.actor_id=a and o.operation_id=op and o.tournament_id=tid and o.event_id=eid;
 if result is null then return jsonb_build_object('status','retry_exact','code','operation_incomplete');end if;
 return result||jsonb_build_object('historicalReceipt',true,'currentSourceVerified',false);
exception when lock_not_available then return null;
end$$;

alter function app.operational_event_finance_proposals_enabled_v1()owner to postgres;
alter function app.lock_operational_event_finance_sources_v1()owner to postgres;
alter function app.operational_event_finance_source_v1(uuid,uuid,uuid)owner to postgres;
alter function app.get_operational_event_finance_source_v1(uuid,uuid)owner to postgres;
alter function app.valid_operational_event_finance_editor_v1(jsonb,jsonb,jsonb)owner to postgres;
alter function app.finish_operational_event_finance_operation_v1(uuid,uuid,uuid,uuid,jsonb)owner to postgres;
alter function app.save_operational_event_finance_proposal_v1(uuid,uuid,jsonb)owner to postgres;
alter function app.reconcile_operational_event_finance_proposal_v1(uuid,uuid,uuid)owner to postgres;

revoke all on function app.operational_event_finance_proposals_enabled_v1(),
 app.lock_operational_event_finance_sources_v1(),
 app.operational_event_finance_source_v1(uuid,uuid,uuid),
 app.get_operational_event_finance_source_v1(uuid,uuid),
 app.valid_operational_event_finance_editor_v1(jsonb,jsonb,jsonb),
 app.finish_operational_event_finance_operation_v1(uuid,uuid,uuid,uuid,jsonb),
 app.save_operational_event_finance_proposal_v1(uuid,uuid,jsonb),
 app.reconcile_operational_event_finance_proposal_v1(uuid,uuid,uuid)
 from public,anon,authenticated,service_role;


-- Frozen source playoff-series-matches-v1.sql

create table app.playoff_series_match_operations_v1(
 actor_id uuid not null references app.profiles(id),operation_id uuid not null,
 tournament_id uuid not null references app.tournaments(id),event_id uuid not null,
 request_payload jsonb not null,request_hash text not null,result jsonb not null,
 created_at timestamptz not null default clock_timestamp(),primary key(actor_id,operation_id),
 unique(actor_id,operation_id,tournament_id,event_id),
 foreign key(event_id,tournament_id)references app.events(id,tournament_id),
 check(request_hash=encode(extensions.digest(convert_to(jsonb_build_array('playoff-series-generation-v1',actor_id,tournament_id,event_id,operation_id,request_payload)::text,'utf8'),'sha256'),'hex'))
);
create table app.playoff_series_matches_v1(
 id uuid primary key default extensions.gen_random_uuid(),tournament_id uuid not null,event_id uuid not null,
 qualification_id uuid not null,slot integer not null check(slot between 1 and 4),
 unique(tournament_id,event_id,qualification_id,slot),unique(id,tournament_id,event_id),unique(id,tournament_id,event_id,qualification_id,slot),
 foreign key(qualification_id,tournament_id,event_id)references app.qualification_result_versions(id,tournament_id,event_id)
);
create table app.playoff_series_generations_v1(
 id uuid primary key default extensions.gen_random_uuid(),match_id uuid not null,tournament_id uuid not null,event_id uuid not null,
 version integer not null check(version>0),qualification_id uuid not null,playoff_start_id uuid not null,
 settings_binding_id uuid not null references app.event_settings_operational_bindings_v1(id),
 context_review_id uuid not null references app.event_rule_context_reviews_v1(id),
 source_digest text not null check(source_digest~'^[a-f0-9]{64}$'),source_capture jsonb not null,
 side_a_participant_id uuid not null,side_b_participant_id uuid not null,side_a_profile_id uuid not null,side_b_profile_id uuid not null,
 round_name text not null check(round_name in('regular','semifinal','final')),slot integer not null check(slot between 1 and 4),
 wins_required integer not null check(wins_required>0),maximum_games integer not null,
 prior_generation_id uuid,actor_id uuid not null,operation_id uuid not null,
 created_at timestamptz not null default clock_timestamp(),unique(match_id,version),unique(id,tournament_id,event_id),unique(id,match_id,tournament_id,event_id),
 foreign key(match_id,tournament_id,event_id,qualification_id,slot)references app.playoff_series_matches_v1(id,tournament_id,event_id,qualification_id,slot),
 foreign key(prior_generation_id,match_id,tournament_id,event_id)references app.playoff_series_generations_v1(id,match_id,tournament_id,event_id),
 foreign key(playoff_start_id,tournament_id,event_id)references app.event_settings_playoff_starts_v1(id,tournament_id,event_id),
 foreign key(qualification_id,tournament_id,event_id)references app.qualification_result_versions(id,tournament_id,event_id),
 foreign key(side_a_participant_id,side_a_profile_id,event_id,tournament_id)references app.event_participants(id,profile_id,event_id,tournament_id),
 foreign key(side_b_participant_id,side_b_profile_id,event_id,tournament_id)references app.event_participants(id,profile_id,event_id,tournament_id),
 foreign key(actor_id,operation_id,tournament_id,event_id)references app.playoff_series_match_operations_v1(actor_id,operation_id,tournament_id,event_id),
 check(side_a_participant_id<>side_b_participant_id and side_a_profile_id<>side_b_profile_id),
 check(maximum_games::bigint=wins_required::bigint*2-1)
);
create table app.playoff_series_results_v1(
 id uuid primary key default extensions.gen_random_uuid(),generation_id uuid not null unique,match_id uuid not null,
 tournament_id uuid not null,event_id uuid not null,version integer not null default 1 check(version=1),
 winner_participant_id uuid not null,loser_participant_id uuid not null,
 wins_a integer not null check(wins_a>=0),wins_b integer not null check(wins_b>=0),game_count integer not null check(game_count>0),
 source_digest text not null check(source_digest~'^[a-f0-9]{64}$'),games_digest text not null check(games_digest~'^[a-f0-9]{64}$'),
 completed_by_profile_id uuid not null references app.profiles(id),operation_id uuid not null,
 created_at timestamptz not null default clock_timestamp(),unique(id,generation_id),
 foreign key(generation_id,match_id,tournament_id,event_id)references app.playoff_series_generations_v1(id,match_id,tournament_id,event_id),
 foreign key(match_id,tournament_id,event_id)references app.playoff_series_matches_v1(id,tournament_id,event_id),
 foreign key(winner_participant_id,event_id,tournament_id)references app.event_participants(id,event_id,tournament_id),
 foreign key(loser_participant_id,event_id,tournament_id)references app.event_participants(id,event_id,tournament_id),
 check(winner_participant_id<>loser_participant_id and wins_a+wins_b=game_count)
);
do $$declare n text;begin
 foreach n in array array['playoff_series_match_operations_v1','playoff_series_matches_v1','playoff_series_generations_v1','playoff_series_results_v1']loop
  execute format('alter table app.%I owner to postgres',n);
  execute format('alter table app.%I enable row level security',n);execute format('alter table app.%I force row level security',n);
  execute format('revoke all on app.%I from public,anon,authenticated,service_role',n);
  execute format('create trigger %I before update or delete on app.%I for each row execute function app.reject_immutable_history()',n||'_immutable',n);
 end loop;
end$$;
create index playoff_series_generations_latest_v1 on app.playoff_series_generations_v1(match_id,version desc);
-- Forward helper calls are PL/pgSQL runtime dependencies. Slot dependencies
-- strictly decrease (4/5-qualifier scope), so they cannot form a bracket cycle.
create function app.playoff_series_current_result_v1(tid uuid,eid uuid,qid uuid,slot_no integer)returns jsonb
language plpgsql security definer set search_path=''as $$
declare src jsonb;g app.playoff_series_generations_v1%rowtype;r app.playoff_series_results_v1%rowtype;valid boolean;
begin
 src:=app.playoff_series_match_source_v1(tid,eid,qid,slot_no);
 if src->>'status'='retry_exact'then raise lock_not_available;end if;
 if src->>'status'is distinct from'source_available'or src->'currentGenerationId'='null'::jsonb then return null;end if;
 select*into g from app.playoff_series_generations_v1 where id=(src->>'currentGenerationId')::uuid and tournament_id=tid and event_id=eid;
 select*into r from app.playoff_series_results_v1 where generation_id=g.id and tournament_id=tid and event_id=eid;
 if r.id is null or r.match_id<>g.match_id or r.source_digest is distinct from src->>'sourceDigest'or g.source_digest is distinct from src->>'sourceDigest'
 or r.game_count>g.maximum_games or greatest(r.wins_a,r.wins_b)<>g.wins_required or least(r.wins_a,r.wins_b)>=g.wins_required
 or r.winner_participant_id is distinct from(case when r.wins_a=g.wins_required then g.side_a_participant_id else g.side_b_participant_id end)
 or r.loser_participant_id is distinct from(case when r.wins_a=g.wins_required then g.side_b_participant_id else g.side_a_participant_id end)then return null;end if;
 if to_regprocedure('app.playoff_series_completed_result_valid_v1(uuid)')is null then return null;end if;
 execute 'select app.playoff_series_completed_result_valid_v1($1)'into valid using r.id;
 if valid is distinct from true then return null;end if;
 return jsonb_build_object('matchId',g.match_id,'resultId',r.id,'version',r.version,'winnerId',r.winner_participant_id,'loserId',r.loser_participant_id);
end$$;

create function app.playoff_series_match_source_v1(tid uuid,eid uuid,qid uuid,slot_no integer)returns jsonb
language plpgsql security definer set search_path=''as $$
declare native jsonb;start_row app.event_settings_playoff_starts_v1%rowtype;b app.event_settings_operational_bindings_v1%rowtype;
 q app.qualification_result_versions%rowtype;m app.playoff_series_matches_v1%rowtype;g app.playoff_series_generations_v1%rowtype;
 ids uuid[];x uuid;y uuid;pa uuid;pb uuid;la uuid;lb uuid;prefa integer;prefb integer;
 parent_a jsonb;parent_b jsonb;parents jsonb;round_name text;format_value jsonb;capture_value jsonb;h text;
begin
 if current_setting('transaction_isolation')<>'read committed'then return jsonb_build_object('status','retry_exact','code','isolation_not_supported');end if;
 perform 1 from app.tournaments where id=tid for update nowait;
 if not found then return jsonb_build_object('status','blocked','code','tournament_unavailable');end if;
 native:=app.event_settings_playoff_source_v1(tid,eid);
 if native->>'status'='retry_exact'then return native;end if;
 if native->>'status'is distinct from'source_available'or native->>'qualificationId'is distinct from qid::text then return jsonb_build_object('status','blocked','code','qualification_source_changed');end if;
 if not app.event_settings_playoff_lifecycle_open_v1(tid,eid)then return jsonb_build_object('status','blocked','code','playoff_lifecycle_closed');end if;
 select*into start_row from app.event_settings_playoff_starts_v1 where tournament_id=tid and event_id=eid order by version desc limit 1;
 if start_row.id is null or start_row.qualification_id<>qid or start_row.source_digest is distinct from native->>'sourceDigest'then return jsonb_build_object('status','blocked','code','current_playoff_start_required');end if;
 select*into q from app.qualification_result_versions where id=qid and tournament_id=tid and event_id=eid;
 if q.qualifier_count not in(4,5)then return jsonb_build_object('status','blocked','code','unsupported_qualifier_count');end if;
 select array_agg(participant_id order by ranking_ordinal)into ids from app.qualification_result_rows where result_version_id=qid and qualification_status='qualified';
 if cardinality(ids)<>q.qualifier_count then return jsonb_build_object('status','blocked','code','qualification_rows_unavailable');end if;
 if q.qualifier_count=4 then
  if slot_no=1 then x:=ids[1];y:=ids[4];round_name:='semifinal';
  elsif slot_no=2 then x:=ids[2];y:=ids[3];round_name:='semifinal';
  elsif slot_no=3 then parent_a:=app.playoff_series_current_result_v1(tid,eid,qid,1);parent_b:=app.playoff_series_current_result_v1(tid,eid,qid,2);round_name:='final';
   if parent_a is null or parent_b is null then return jsonb_build_object('status','blocked','code','parent_series_incomplete');end if;x:=(parent_a->>'winnerId')::uuid;y:=(parent_b->>'winnerId')::uuid;
  else return jsonb_build_object('status','blocked','code','invalid_slot');end if;
 else
  if slot_no=1 then x:=ids[4];y:=ids[5];round_name:='regular';
  elsif slot_no=2 then parent_b:=app.playoff_series_current_result_v1(tid,eid,qid,1);round_name:='semifinal';
   if parent_b is null then return jsonb_build_object('status','blocked','code','parent_series_incomplete');end if;x:=ids[1];y:=(parent_b->>'winnerId')::uuid;
  elsif slot_no=3 then x:=ids[3];y:=ids[2];round_name:='semifinal';
  elsif slot_no=4 then parent_a:=app.playoff_series_current_result_v1(tid,eid,qid,2);parent_b:=app.playoff_series_current_result_v1(tid,eid,qid,3);round_name:='final';
   if parent_a is null or parent_b is null then return jsonb_build_object('status','blocked','code','parent_series_incomplete');end if;x:=(parent_a->>'winnerId')::uuid;y:=(parent_b->>'winnerId')::uuid;
  else return jsonb_build_object('status','blocked','code','invalid_slot');end if;
 end if;
 if x is null or y is null or x=y then return jsonb_build_object('status','blocked','code','invalid_slot_players');end if;
 -- Native roster preference/link ownership is required; no fallback by name,
 -- email, ACC number, account role or a posted digital-mode assertion.
 lock table app.roster_account_links in share mode nowait;
 select p.profile_id,l.id,r.scorecard_preference_version into pa,la,prefa from app.event_participants p
 join app.tournament_roster_entries r on r.id=p.roster_entry_id and r.tournament_id=p.tournament_id and r.scorecard_type='digital'
 join app.roster_account_links l on l.roster_entry_id=r.id and l.tournament_id=r.tournament_id and l.profile_id=p.profile_id
 where p.id=x and p.tournament_id=tid and p.event_id=eid and p.status='checked_in';
 select p.profile_id,l.id,r.scorecard_preference_version into pb,lb,prefb from app.event_participants p
 join app.tournament_roster_entries r on r.id=p.roster_entry_id and r.tournament_id=p.tournament_id and r.scorecard_type='digital'
 join app.roster_account_links l on l.roster_entry_id=r.id and l.tournament_id=r.tournament_id and l.profile_id=p.profile_id
 where p.id=y and p.tournament_id=tid and p.event_id=eid and p.status='checked_in';
 if pa is null or pb is null or pa=pb or la is null or lb is null then return jsonb_build_object('status','blocked','code','distinct_linked_digital_players_required');end if;
 select*into b from app.event_settings_operational_bindings_v1 where id=(native->>'settingsBindingId')::uuid and tournament_id=tid and event_id=eid;
 format_value:=app.resolve_event_series_format_v1(case when round_name='final'and b.draft->>'finalMode'='separate'then b.draft#>'{series,final}'else b.draft#>'{series,regular}'end);
 if format_value is null then return jsonb_build_object('status','blocked','code','series_format_unavailable');end if;
 -- Each verified game needs four accepted actions. The shared protocol's
 -- 10,000-action processing bound must represent the full best-of series.
 -- This is a technical bound, not an ACC rule; never shorten a chosen format.
 if(format_value->>'maximumGames')::bigint*4>10000 then return jsonb_build_object('status','blocked','code','series_game_resource_bound');end if;
 parents:=jsonb_build_array(case when parent_a is null then null else jsonb_build_object('matchId',parent_a->'matchId','resultId',parent_a->'resultId','version',parent_a->'version')end,case when parent_b is null then null else jsonb_build_object('matchId',parent_b->'matchId','resultId',parent_b->'resultId','version',parent_b->'version')end);
 capture_value:=jsonb_build_object('tournamentId',tid,'eventId',eid,'qualificationId',qid,'slot',slot_no,'playoffStartId',start_row.id,'gateDigest',native->>'sourceDigest','settingsBindingId',b.id,'reviewId',b.review_id,'activationId',b.activation_id,'round',round_name,'participants',jsonb_build_array(x,y),'profiles',jsonb_build_array(pa,pb),'rosterLinks',jsonb_build_array(la,lb),'preferences',jsonb_build_array(prefa,prefb),'format',format_value,'parentResultPins',parents);
 h:=encode(extensions.digest(convert_to(jsonb_build_array('playoff-series-match-source-v1',capture_value)::text,'utf8'),'sha256'),'hex');
 select*into m from app.playoff_series_matches_v1 where tournament_id=tid and event_id=eid and qualification_id=qid and slot=slot_no;
 select*into g from app.playoff_series_generations_v1 where match_id=m.id order by version desc limit 1;
 return jsonb_build_object('status','source_available','sourceDigest',h,'source',capture_value,'matchId',m.id,'currentGenerationId',g.id,'currentGenerationVersion',coalesce(g.version,0),'round',round_name,'participants',jsonb_build_array(x,y),'profiles',jsonb_build_array(pa,pb),'winsRequired',format_value->'winsRequired','maximumGames',format_value->'maximumGames','parentResultPins',parents,'settingsBindingId',b.id,'reviewId',b.review_id,'playoffStartId',start_row.id);
exception when lock_not_available then return jsonb_build_object('status','retry_exact','code','source_busy');end$$;
create function app.get_playoff_series_generation_operation_v1(tid uuid,eid uuid,op uuid)returns jsonb
language plpgsql security definer set search_path=''as $$
declare a uuid:=auth.uid();r app.playoff_series_match_operations_v1%rowtype;
begin
 if a is null then return jsonb_build_object('status','blocked','code','authentication_required');end if;
 if current_setting('transaction_isolation')<>'read committed'then return jsonb_build_object('status','retry_exact','code','isolation_not_supported');end if;
 perform 1 from app.tournaments where id=tid for share nowait;if not found then return jsonb_build_object('status','blocked','code','tournament_unavailable');end if;
 perform 1 from app.tournament_roles where tournament_id=tid and profile_id=a and role in('director','co_director')order by role for share nowait;if not found then return jsonb_build_object('status','blocked','code','not_director');end if;
 if not pg_try_advisory_xact_lock(hashtextextended(a::text||':'||op::text,0))then return jsonb_build_object('status','retry_exact','code','operation_busy');end if;
 select*into r from app.playoff_series_match_operations_v1 where actor_id=a and operation_id=op and tournament_id=tid and event_id=eid;
 if not found then return jsonb_build_object('status','unknown','actorId',a,'tournamentId',tid,'eventId',eid,'operationId',op);end if;
 return r.result||jsonb_build_object('historicalReceipt',true,'currentSourceVerified',false);
exception when lock_not_available then return jsonb_build_object('status','retry_exact','code','source_busy');end$$;

create function app.finish_playoff_series_generation_v1(tid uuid,eid uuid,op uuid,v jsonb,outcome jsonb)returns jsonb
language plpgsql security definer set search_path=''as $$
declare a uuid:=auth.uid();h text;response jsonb;
begin
 h:=encode(extensions.digest(convert_to(jsonb_build_array('playoff-series-generation-v1',a,tid,eid,op,v)::text,'utf8'),'sha256'),'hex');
 response:=outcome||jsonb_build_object('actorId',a,'tournamentId',tid,'eventId',eid,'operationId',op,'request',v,'verifiedGamesCreated',false,'moneyMoved',false);
 insert into app.playoff_series_match_operations_v1(actor_id,operation_id,tournament_id,event_id,request_payload,request_hash,result)values(a,op,tid,eid,v,h,response);return response;
end$$;

create function app.create_playoff_series_generation_v1(tid uuid,eid uuid,v jsonb)returns jsonb
language plpgsql security definer set search_path=''as $$
declare a uuid:=auth.uid();op uuid;h text;old app.playoff_series_match_operations_v1%rowtype;src jsonb;
 mid uuid;gid uuid;qid uuid;slot_no integer;head app.playoff_series_generations_v1%rowtype;response jsonb;has_work boolean;
begin
 if a is null then return jsonb_build_object('status','rejected','code','authentication_required');end if;
 if current_setting('transaction_isolation')<>'read committed'then return jsonb_build_object('status','retry_exact','code','isolation_not_supported');end if;
 if jsonb_typeof(v)is distinct from'object'or(select count(*)from jsonb_object_keys(v))<>6 or not(v?&array['kind','operationId','qualificationId','slot','expectedGenerationId','sourceDigest'])
 or v->>'kind'is distinct from'playoff-series-generation-v1'
 or jsonb_typeof(v->'operationId')is distinct from'string'or(v->>'operationId')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
 or jsonb_typeof(v->'qualificationId')is distinct from'string'or(v->>'qualificationId')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
 or not(v->'expectedGenerationId'='null'::jsonb or(jsonb_typeof(v->'expectedGenerationId')='string'and(v->>'expectedGenerationId')~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'))
 or jsonb_typeof(v->'sourceDigest')is distinct from'string'or(v->>'sourceDigest')!~'^[a-f0-9]{64}$'
 or jsonb_typeof(v->'slot')is distinct from'number'or(v->>'slot')!~'^[1-4]$'then return jsonb_build_object('status','rejected','code','invalid_request');end if;
 op:=(v->>'operationId')::uuid;qid:=(v->>'qualificationId')::uuid;slot_no:=(v->>'slot')::integer;
 if not pg_try_advisory_xact_lock(hashtextextended(a::text||':'||op::text,0))then return jsonb_build_object('status','retry_exact','code','operation_busy');end if;
 perform 1 from app.tournaments where id=tid for update nowait;if not found then return jsonb_build_object('status','rejected','code','tournament_unavailable');end if;
 perform 1 from app.tournament_roles where tournament_id=tid and profile_id=a and role in('director','co_director')order by role for share nowait;if not found then return jsonb_build_object('status','rejected','code','not_director');end if;
 h:=encode(extensions.digest(convert_to(jsonb_build_array('playoff-series-generation-v1',a,tid,eid,op,v)::text,'utf8'),'sha256'),'hex');
 select*into old from app.playoff_series_match_operations_v1 where actor_id=a and operation_id=op;
 if found then
  if old.tournament_id<>tid or old.event_id<>eid or old.request_hash<>h or old.request_payload<>v then return jsonb_build_object('status','rejected','code','operation_conflict');end if;
  return old.result||jsonb_build_object('historicalReceipt',true,'currentSourceVerified',false);
 end if;
 if not exists(select 1 from app.events where id=eid and tournament_id=tid)then return jsonb_build_object('status','rejected','code','event_unavailable');end if;
 src:=app.playoff_series_match_source_v1(tid,eid,qid,slot_no);if src->>'status'='retry_exact'then raise lock_not_available;end if;
 if src->>'status'is distinct from'source_available'or src->>'sourceDigest'is distinct from v->>'sourceDigest'then return app.finish_playoff_series_generation_v1(tid,eid,op,v,jsonb_build_object('status','rejected','code','match_source_changed'));end if;
 if exists(select 1 from app.playoff_series_results_v1 r join app.playoff_series_generations_v1 old_generation on old_generation.id=r.generation_id where old_generation.tournament_id=tid and old_generation.event_id=eid and old_generation.qualification_id<>qid)
 then return app.finish_playoff_series_generation_v1(tid,eid,op,v,jsonb_build_object('status','rejected','code','bracket_recovery_review_required'));end if;
 if to_regclass('app.playoff_series_game_actions_v1')is not null then
  execute 'select exists(select 1 from app.playoff_series_game_actions_v1 action join app.playoff_series_generations_v1 old_generation on old_generation.id=action.generation_id where old_generation.tournament_id=$1 and old_generation.event_id=$2 and old_generation.qualification_id<>$3)'into has_work using tid,eid,qid;
  if has_work then return app.finish_playoff_series_generation_v1(tid,eid,op,v,jsonb_build_object('status','rejected','code','bracket_recovery_review_required'));end if;
 end if;
 if coalesce(src->>'currentGenerationId','')<>coalesce(v->>'expectedGenerationId','')then return app.finish_playoff_series_generation_v1(tid,eid,op,v,jsonb_build_object('status','rejected','code','generation_changed'));end if;
 if src->>'currentGenerationId'is not null then
  select*into head from app.playoff_series_generations_v1 where id=(src->>'currentGenerationId')::uuid;
  if head.source_digest=src->>'sourceDigest'then return app.finish_playoff_series_generation_v1(tid,eid,op,v,jsonb_build_object('status','rejected','code','generation_already_current'));end if;
  if exists(select 1 from app.playoff_series_results_v1 where generation_id=head.id)then return app.finish_playoff_series_generation_v1(tid,eid,op,v,jsonb_build_object('status','rejected','code','generation_recovery_review_required'));end if;
  -- Do not clear or rebase a generation containing pending player work.
  if to_regclass('app.playoff_series_game_actions_v1')is not null then
   execute 'select exists(select 1 from app.playoff_series_game_actions_v1 where generation_id=$1)'into has_work using head.id;
   if has_work then return app.finish_playoff_series_generation_v1(tid,eid,op,v,jsonb_build_object('status','rejected','code','generation_recovery_review_required'));end if;
  end if;
 end if;
 mid:=(src->>'matchId')::uuid;
 if mid is null then mid:=extensions.gen_random_uuid();insert into app.playoff_series_matches_v1(id,tournament_id,event_id,qualification_id,slot)values(mid,tid,eid,qid,slot_no);end if;
 gid:=extensions.gen_random_uuid();response:=app.finish_playoff_series_generation_v1(tid,eid,op,v,jsonb_build_object('status','series_generation_created','matchId',mid,'generationId',gid,'matchVersion',coalesce(head.version,0)+1,'sourceDigest',src->>'sourceDigest'));
 insert into app.playoff_series_generations_v1(id,match_id,tournament_id,event_id,version,qualification_id,playoff_start_id,settings_binding_id,context_review_id,source_digest,source_capture,side_a_participant_id,side_b_participant_id,side_a_profile_id,side_b_profile_id,round_name,slot,wins_required,maximum_games,prior_generation_id,actor_id,operation_id)
 values(gid,mid,tid,eid,coalesce(head.version,0)+1,qid,(src->>'playoffStartId')::uuid,(src->>'settingsBindingId')::uuid,(src->>'reviewId')::uuid,src->>'sourceDigest',src->'source',(src#>>'{participants,0}')::uuid,(src#>>'{participants,1}')::uuid,(src#>>'{profiles,0}')::uuid,(src#>>'{profiles,1}')::uuid,src->>'round',slot_no,(src->>'winsRequired')::integer,(src->>'maximumGames')::integer,head.id,a,op);
 return response;
exception when lock_not_available then return jsonb_build_object('status','retry_exact','code','source_busy');end$$;
alter function app.playoff_series_current_result_v1(uuid,uuid,uuid,integer)owner to postgres;
alter function app.playoff_series_match_source_v1(uuid,uuid,uuid,integer)owner to postgres;
alter function app.finish_playoff_series_generation_v1(uuid,uuid,uuid,jsonb,jsonb)owner to postgres;
alter function app.create_playoff_series_generation_v1(uuid,uuid,jsonb)owner to postgres;
alter function app.get_playoff_series_generation_operation_v1(uuid,uuid,uuid)owner to postgres;
revoke all on function app.playoff_series_current_result_v1(uuid,uuid,uuid,integer),app.playoff_series_match_source_v1(uuid,uuid,uuid,integer),app.finish_playoff_series_generation_v1(uuid,uuid,uuid,jsonb,jsonb),app.create_playoff_series_generation_v1(uuid,uuid,jsonb),app.get_playoff_series_generation_operation_v1(uuid,uuid,uuid)from public,anon,authenticated,service_role;


-- Frozen source playoff-series-games-v1.sql


create table app.playoff_series_game_operations_v1(
 actor_id uuid not null references app.profiles(id),
 operation_id uuid not null,
 tournament_id uuid not null,
 event_id uuid not null,
 qualification_id uuid not null,
 slot integer not null check(slot between 1 and 4),
 generation_id uuid,
 request_payload jsonb not null,
 request_hash text not null check(request_hash~'^[a-f0-9]{64}$'),
 created_at timestamptz not null default clock_timestamp(),
 primary key(actor_id,operation_id),
 unique(actor_id,operation_id,tournament_id,event_id),
 foreign key(event_id,tournament_id) references app.events(id,tournament_id),
 foreign key(qualification_id,tournament_id,event_id)
  references app.qualification_result_versions(id,tournament_id,event_id),
 check(request_hash=encode(extensions.digest(convert_to(jsonb_build_array(
  'playoff-series-game-action-v1',actor_id,tournament_id,event_id,qualification_id,slot,operation_id,request_payload
 )::text,'utf8'),'sha256'),'hex'))
);

create table app.playoff_series_game_operation_outcomes_v1(
 actor_id uuid not null,
 operation_id uuid not null,
 tournament_id uuid not null,
 event_id uuid not null,
 result jsonb not null,
 created_at timestamptz not null default clock_timestamp(),
 primary key(actor_id,operation_id),
 foreign key(actor_id,operation_id,tournament_id,event_id)
  references app.playoff_series_game_operations_v1(actor_id,operation_id,tournament_id,event_id)
);

create table app.playoff_series_game_operation_conflicts_v1(
 id uuid primary key default extensions.gen_random_uuid(),
 actor_id uuid not null references app.profiles(id),
 operation_id uuid not null,
 tournament_id uuid not null,
 event_id uuid not null,
 qualification_id uuid not null,
 slot integer not null check(slot between 1 and 4),
 attempted_request jsonb not null,
 attempted_hash text not null check(attempted_hash~'^[a-f0-9]{64}$'),
 result jsonb not null,
 created_at timestamptz not null default clock_timestamp(),
 foreign key(actor_id,operation_id)
  references app.playoff_series_game_operations_v1(actor_id,operation_id)
);

create table app.playoff_series_games_v1(
 id uuid primary key,
 generation_id uuid not null,
 tournament_id uuid not null,
 event_id uuid not null,
 game_number integer not null check(game_number>0),
 source_digest text not null check(source_digest~'^[a-f0-9]{64}$'),
 created_at timestamptz not null default clock_timestamp(),
 unique(generation_id,game_number),
 unique(id,generation_id),
 foreign key(generation_id,tournament_id,event_id)
  references app.playoff_series_generations_v1(id,tournament_id,event_id)
);

-- Only accepted submit/confirm work appears here. Recovery must inspect this
-- table, not the terminal operation journal, so rejected requests do not block
-- generation replacement.
create table app.playoff_series_game_actions_v1(
 id uuid primary key default extensions.gen_random_uuid(),
 actor_id uuid not null,
 operation_id uuid not null,
 tournament_id uuid not null,
 event_id uuid not null,
 generation_id uuid not null,
 game_id uuid not null,
 game_version integer not null check(game_version>0),
 action_type text not null check(action_type in('submit','amend','confirm')),
 created_at timestamptz not null default clock_timestamp(),
 unique(actor_id,operation_id),
 unique(game_id,game_version),
 foreign key(actor_id,operation_id,tournament_id,event_id)
  references app.playoff_series_game_operations_v1(actor_id,operation_id,tournament_id,event_id),
 foreign key(game_id,generation_id) references app.playoff_series_games_v1(id,generation_id),
 foreign key(generation_id,tournament_id,event_id)
  references app.playoff_series_generations_v1(id,tournament_id,event_id)
);

create table app.playoff_series_game_submissions_v1(
 id uuid primary key,
 action_id uuid not null unique references app.playoff_series_game_actions_v1(id),
 game_id uuid not null,
 generation_id uuid not null,
 tournament_id uuid not null,
 event_id uuid not null,
 actor_profile_id uuid not null references app.profiles(id),
 participant_id uuid not null,
 winner_participant_id uuid not null,
 submitted_at timestamptz not null default clock_timestamp(),
 unique(id,game_id),
 unique(id,game_id,actor_profile_id),
 foreign key(game_id,generation_id) references app.playoff_series_games_v1(id,generation_id),
 foreign key(participant_id,actor_profile_id,event_id,tournament_id)
  references app.event_participants(id,profile_id,event_id,tournament_id),
 foreign key(winner_participant_id,event_id,tournament_id)
  references app.event_participants(id,event_id,tournament_id)
);

create table app.playoff_series_game_confirmations_v1(
 id uuid primary key default extensions.gen_random_uuid(),
 action_id uuid not null unique references app.playoff_series_game_actions_v1(id),
 game_id uuid not null,
 generation_id uuid not null,
 actor_profile_id uuid not null references app.profiles(id),
 submission_id uuid not null,
 confirmed_at timestamptz not null default clock_timestamp(),
 unique(game_id,actor_profile_id,submission_id),
 unique(id,game_id),
 unique(id,game_id,actor_profile_id),
 foreign key(game_id,generation_id) references app.playoff_series_games_v1(id,generation_id),
 foreign key(submission_id,game_id,actor_profile_id)
  references app.playoff_series_game_submissions_v1(id,game_id,actor_profile_id)
);

create table app.playoff_series_verified_games_v1(
 id uuid primary key default extensions.gen_random_uuid(),
 game_id uuid not null unique,
 generation_id uuid not null,
 tournament_id uuid not null,
 event_id uuid not null,
 game_number integer not null check(game_number>0),
 winner_participant_id uuid not null,
 loser_participant_id uuid not null,
 side_a_submission_id uuid not null,
 side_b_submission_id uuid not null,
 side_a_confirmation_id uuid not null,
 side_b_confirmation_id uuid not null,
 verified_by_action_id uuid not null unique references app.playoff_series_game_actions_v1(id),
 source_digest text not null check(source_digest~'^[a-f0-9]{64}$'),
 verified_at timestamptz not null default clock_timestamp(),
 unique(generation_id,game_number),
 unique(id,generation_id),
 foreign key(game_id,generation_id) references app.playoff_series_games_v1(id,generation_id),
 foreign key(generation_id,tournament_id,event_id)
  references app.playoff_series_generations_v1(id,tournament_id,event_id),
 foreign key(winner_participant_id,event_id,tournament_id)
  references app.event_participants(id,event_id,tournament_id),
 foreign key(loser_participant_id,event_id,tournament_id)
  references app.event_participants(id,event_id,tournament_id),
 foreign key(side_a_submission_id,game_id) references app.playoff_series_game_submissions_v1(id,game_id),
 foreign key(side_b_submission_id,game_id) references app.playoff_series_game_submissions_v1(id,game_id),
 foreign key(side_a_confirmation_id,game_id) references app.playoff_series_game_confirmations_v1(id,game_id),
 foreign key(side_b_confirmation_id,game_id) references app.playoff_series_game_confirmations_v1(id,game_id),
 check(winner_participant_id<>loser_participant_id),
 check(side_a_submission_id<>side_b_submission_id),
 check(side_a_confirmation_id<>side_b_confirmation_id)
);

do $$declare n text;begin
 foreach n in array array[
  'playoff_series_game_operations_v1','playoff_series_game_operation_outcomes_v1',
  'playoff_series_game_operation_conflicts_v1',
  'playoff_series_games_v1','playoff_series_game_actions_v1',
  'playoff_series_game_submissions_v1','playoff_series_game_confirmations_v1',
  'playoff_series_verified_games_v1'
 ]loop
  execute format('alter table app.%I owner to postgres',n);
  execute format('alter table app.%I enable row level security',n);
  execute format('alter table app.%I force row level security',n);
  execute format('revoke all on app.%I from public,anon,authenticated,service_role',n);
  execute format('create trigger %I before update or delete on app.%I for each row execute function app.reject_immutable_history()',n||'_immutable',n);
 end loop;
end$$;

create index playoff_series_game_actions_generation_v1
 on app.playoff_series_game_actions_v1(generation_id,created_at);
create index playoff_series_game_submissions_latest_v1
 on app.playoff_series_game_submissions_v1(game_id,actor_profile_id,submitted_at desc,id desc);
create index playoff_series_game_confirmations_latest_v1
 on app.playoff_series_game_confirmations_v1(game_id,actor_profile_id,confirmed_at desc,id desc);

create or replace function app.playoff_series_uuid_v1(v text)returns boolean
language sql immutable set search_path='' as $$
 select v is not null and v~*'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
$$;

create or replace function app.valid_playoff_series_game_request_v1(r jsonb)returns boolean
language plpgsql immutable set search_path='' as $$
begin
 if jsonb_typeof(r)is distinct from'object'or(select count(*)from jsonb_object_keys(r))<>17 then return false;end if;
 return r ?& array['operationId','action','gameId','gameNumber','expectedGameVersion','submissionId',
  'confirmationId','priorSubmissionId','winnerParticipantId','confirmedSubmissionId','generationId','generationVersion','sourceDigest',
  'settingsBindingId','reviewId','playoffStartId','parentResultPins']
 and app.playoff_series_uuid_v1(r->>'operationId')
 and r->>'action' in('submit','confirm')
 and app.playoff_series_uuid_v1(r->>'gameId')
 and jsonb_typeof(r->'gameNumber')='number' and (r->>'gameNumber')~'^[1-9][0-9]*$'
 and (r->>'gameNumber')::numeric<=10000
 and jsonb_typeof(r->'expectedGameVersion')='number' and (r->>'expectedGameVersion')~'^(0|[1-9][0-9]*)$'
 and (r->>'expectedGameVersion')::numeric<=2147483646
 and app.playoff_series_uuid_v1(r->>'generationId')
 and jsonb_typeof(r->'generationVersion')='number' and (r->>'generationVersion')~'^[1-9][0-9]*$'
 and (r->>'generationVersion')::numeric<=2147483647
 and (r->>'sourceDigest')~'^[a-f0-9]{64}$'
 and app.playoff_series_uuid_v1(r->>'settingsBindingId')
 and app.playoff_series_uuid_v1(r->>'reviewId')
 and app.playoff_series_uuid_v1(r->>'playoffStartId')
 and jsonb_typeof(r->'parentResultPins')='array'
 and case when r->>'action'='submit' then
  app.playoff_series_uuid_v1(r->>'submissionId')
  and r->'confirmationId'='null'::jsonb
  and (r->'priorSubmissionId'='null'::jsonb or app.playoff_series_uuid_v1(r->>'priorSubmissionId'))
  and app.playoff_series_uuid_v1(r->>'winnerParticipantId')
  and r->'confirmedSubmissionId'='null'::jsonb
 else
  r->'submissionId'='null'::jsonb
  and app.playoff_series_uuid_v1(r->>'confirmationId')
  and r->'priorSubmissionId'='null'::jsonb
  and r->'winnerParticipantId'='null'::jsonb
  and app.playoff_series_uuid_v1(r->>'confirmedSubmissionId')
 end
 ;
exception when invalid_text_representation or numeric_value_out_of_range then return false;
end
$$;

create or replace function app.playoff_series_game_request_hash_v1(
 p_actor_id uuid,p_tournament_id uuid,p_event_id uuid,p_qualification_id uuid,p_slot integer,p_request jsonb
)returns text language sql immutable set search_path='' as $$
 select encode(extensions.digest(convert_to(jsonb_build_array(
  'playoff-series-game-action-v1',p_actor_id,p_tournament_id,p_event_id,p_qualification_id,p_slot,
  (p_request->>'operationId')::uuid,p_request
 )::text,'utf8'),'sha256'),'hex')
$$;

create or replace function app.playoff_series_game_actor_valid_v1(
 p_tournament_id uuid,p_event_id uuid,p_generation_id uuid,p_actor_id uuid
)returns boolean language sql stable security definer set search_path='' as $$
 select exists(
  select 1 from app.playoff_series_generations_v1 g
  join app.event_participants p on p.id in(g.side_a_participant_id,g.side_b_participant_id)
   and p.event_id=g.event_id and p.tournament_id=g.tournament_id and p.profile_id=p_actor_id
  join app.roster_account_links l on l.tournament_id=g.tournament_id
   and l.roster_entry_id=p.roster_entry_id and l.profile_id=p_actor_id
  where g.id=p_generation_id and g.tournament_id=p_tournament_id and g.event_id=p_event_id
   and p.roster_entry_id is not null
 )
$$;

create or replace function app.playoff_series_games_digest_v1(p_generation_id uuid)returns text
language sql stable security definer set search_path='' as $$
 select encode(extensions.digest(convert_to(coalesce(jsonb_agg(jsonb_build_object(
  'gameId',v.game_id,'gameNumber',v.game_number,'winnerParticipantId',v.winner_participant_id,
  'sideASubmissionId',v.side_a_submission_id,'sideBSubmissionId',v.side_b_submission_id,
  'sideAConfirmationId',v.side_a_confirmation_id,'sideBConfirmationId',v.side_b_confirmation_id,
  'sourceDigest',v.source_digest
 )order by v.game_number),'[]'::jsonb)::text,'utf8'),'sha256'),'hex')
 from app.playoff_series_verified_games_v1 v where v.generation_id=p_generation_id
$$;

-- This validator intentionally reconstructs the completed series from exact
-- game evidence. It does not call the root current-result reader for this slot.
create or replace function app.playoff_series_completed_result_valid_v1(p_result_id uuid)returns boolean
language plpgsql volatile security definer set search_path='' as $$
declare r app.playoff_series_results_v1%rowtype;g app.playoff_series_generations_v1%rowtype;
 a_wins integer;b_wins integer;n integer;terminal_number integer;final_actor uuid;final_op uuid;
begin
 select * into r from app.playoff_series_results_v1 where id=p_result_id;
 if not found then return false;end if;
 select * into g from app.playoff_series_generations_v1 where id=r.generation_id;
 if not found or r.match_id is distinct from g.match_id or r.tournament_id is distinct from g.tournament_id
  or r.event_id is distinct from g.event_id or r.source_digest is distinct from g.source_digest
  or (select count(*) from app.playoff_series_game_actions_v1 where generation_id=g.id)>10000
  or exists(select 1 from app.playoff_series_game_actions_v1 action where action.generation_id=g.id and(
   action.actor_id not in(g.side_a_profile_id,g.side_b_profile_id)
   or (action.action_type in('submit','amend')and(
    (select count(*)from app.playoff_series_game_submissions_v1 s where s.action_id=action.id)<>1
    or exists(select 1 from app.playoff_series_game_confirmations_v1 c where c.action_id=action.id)))
   or (action.action_type='confirm'and(
    (select count(*)from app.playoff_series_game_confirmations_v1 c where c.action_id=action.id)<>1
    or exists(select 1 from app.playoff_series_game_submissions_v1 s where s.action_id=action.id)))
  ))
  or exists(select 1 from app.playoff_series_games_v1 game where game.generation_id=g.id and(
   not exists(select 1 from app.playoff_series_verified_games_v1 verified where verified.game_id=game.id)
   or (select count(*)from app.playoff_series_game_actions_v1 action where action.game_id=game.id)
      is distinct from(select max(action.game_version)::bigint from app.playoff_series_game_actions_v1 action where action.game_id=game.id)
   or (select action.game_version from app.playoff_series_verified_games_v1 verified
       join app.playoff_series_game_actions_v1 action on action.id=verified.verified_by_action_id
       where verified.game_id=game.id)
      is distinct from(select max(action.game_version)from app.playoff_series_game_actions_v1 action where action.game_id=game.id)
  ))
 then return false;end if;
 if exists(
  select 1 from app.playoff_series_verified_games_v1 v
  join app.playoff_series_games_v1 game on game.id=v.game_id and game.generation_id=v.generation_id
  join app.playoff_series_game_submissions_v1 sa on sa.id=v.side_a_submission_id
  join app.playoff_series_game_actions_v1 saa on saa.id=sa.action_id
  join app.playoff_series_game_submissions_v1 sb on sb.id=v.side_b_submission_id
  join app.playoff_series_game_actions_v1 sba on sba.id=sb.action_id
  join app.playoff_series_game_confirmations_v1 ca on ca.id=v.side_a_confirmation_id
  join app.playoff_series_game_actions_v1 caa on caa.id=ca.action_id
  join app.playoff_series_game_confirmations_v1 cb on cb.id=v.side_b_confirmation_id
  join app.playoff_series_game_actions_v1 cba on cba.id=cb.action_id
  join app.playoff_series_game_actions_v1 va on va.id=v.verified_by_action_id
  where v.generation_id=g.id and not(
   v.tournament_id=g.tournament_id and v.event_id=g.event_id and v.source_digest=g.source_digest
   and game.game_number=v.game_number and game.source_digest=g.source_digest
   and sa.game_id=v.game_id and sb.game_id=v.game_id and ca.game_id=v.game_id and cb.game_id=v.game_id
   and sa.actor_profile_id=g.side_a_profile_id and sb.actor_profile_id=g.side_b_profile_id
   and ca.actor_profile_id=g.side_a_profile_id and cb.actor_profile_id=g.side_b_profile_id
   and sa.participant_id=g.side_a_participant_id and sb.participant_id=g.side_b_participant_id
   and ca.submission_id=sa.id and cb.submission_id=sb.id
   and saa.game_id=v.game_id and sba.game_id=v.game_id and caa.game_id=v.game_id and cba.game_id=v.game_id
   and saa.generation_id=g.id and sba.generation_id=g.id and caa.generation_id=g.id and cba.generation_id=g.id
   and saa.actor_id=sa.actor_profile_id and sba.actor_id=sb.actor_profile_id
   and caa.actor_id=ca.actor_profile_id and cba.actor_id=cb.actor_profile_id
   and saa.action_type in('submit','amend') and sba.action_type in('submit','amend')
   and caa.action_type='confirm' and cba.action_type='confirm'
   and va.action_type='confirm' and va.id in(ca.action_id,cb.action_id)
   and va.game_id=v.game_id and va.generation_id=g.id
   and sa.winner_participant_id=sb.winner_participant_id
   and v.winner_participant_id=sa.winner_participant_id
   and v.loser_participant_id=case when v.winner_participant_id=g.side_a_participant_id
    then g.side_b_participant_id else g.side_a_participant_id end
   and v.winner_participant_id in(g.side_a_participant_id,g.side_b_participant_id)
   and not exists(select 1 from app.playoff_series_game_submissions_v1 newer
    join app.playoff_series_game_actions_v1 newer_action on newer_action.id=newer.action_id
    where newer.game_id=v.game_id and newer.actor_profile_id=sa.actor_profile_id
     and newer_action.game_version>saa.game_version)
   and not exists(select 1 from app.playoff_series_game_submissions_v1 newer
    join app.playoff_series_game_actions_v1 newer_action on newer_action.id=newer.action_id
    where newer.game_id=v.game_id and newer.actor_profile_id=sb.actor_profile_id
     and newer_action.game_version>sba.game_version)
  )
 )then return false;end if;
 select count(*)::integer,
  count(*)filter(where winner_participant_id=g.side_a_participant_id)::integer,
  count(*)filter(where winner_participant_id=g.side_b_participant_id)::integer,
  max(game_number)::integer
 into n,a_wins,b_wins,terminal_number
 from app.playoff_series_verified_games_v1 where generation_id=g.id;
 if n<>r.game_count or (select count(*)from app.playoff_series_games_v1 where generation_id=g.id)<>n
  or terminal_number<>n or n>g.maximum_games
  or exists(select 1 from generate_series(1,n)s(i) where not exists(
   select 1 from app.playoff_series_verified_games_v1 v where v.generation_id=g.id and v.game_number=s.i))
  or r.wins_a<>a_wins or r.wins_b<>b_wins
  or greatest(a_wins,b_wins)<>g.wins_required or least(a_wins,b_wins)>=g.wins_required
  or r.winner_participant_id is distinct from(case when a_wins=g.wins_required then g.side_a_participant_id else g.side_b_participant_id end)
  or r.loser_participant_id is distinct from(case when a_wins=g.wins_required then g.side_b_participant_id else g.side_a_participant_id end)
  or r.games_digest is distinct from app.playoff_series_games_digest_v1(g.id)
  or exists(select 1 from app.playoff_series_verified_games_v1 cutoff
   where cutoff.generation_id=g.id and cutoff.game_number<n
    and ((select count(*) from app.playoff_series_verified_games_v1 prior
          where prior.generation_id=g.id and prior.game_number<=cutoff.game_number
           and prior.winner_participant_id=g.side_a_participant_id)>=g.wins_required
      or (select count(*) from app.playoff_series_verified_games_v1 prior
          where prior.generation_id=g.id and prior.game_number<=cutoff.game_number
           and prior.winner_participant_id=g.side_b_participant_id)>=g.wins_required))
 then return false;end if;
 select a.actor_id,a.operation_id into final_actor,final_op
 from app.playoff_series_verified_games_v1 v join app.playoff_series_game_actions_v1 a on a.id=v.verified_by_action_id
 where v.generation_id=g.id and v.game_number=n;
 return final_actor=r.completed_by_profile_id and final_op=r.operation_id;
end$$;

create or replace function app.require_playoff_series_completed_result_v1()returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if not app.playoff_series_completed_result_valid_v1(new.id)then
  raise exception using errcode='P0001',message='playoff_series_game_evidence_required';
 end if;
 return null;
end$$;
create constraint trigger playoff_series_results_game_evidence_v1
 after insert on app.playoff_series_results_v1 deferrable initially immediate
 for each row execute function app.require_playoff_series_completed_result_v1();

create or replace function app.finish_playoff_series_game_operation_v1(
 p_actor_id uuid,p_operation_id uuid,p_tournament_id uuid,p_event_id uuid,p_result jsonb
)returns jsonb language plpgsql security definer set search_path='' as $$
declare operation app.playoff_series_game_operations_v1%rowtype;response jsonb;
begin
 if auth.uid() is distinct from p_actor_id then
  raise exception using errcode='P0001',message='playoff_series_game_actor_mismatch';
 end if;
 select * into operation from app.playoff_series_game_operations_v1
  where actor_id=p_actor_id and operation_id=p_operation_id
   and tournament_id=p_tournament_id and event_id=p_event_id;
 if not found then raise exception using errcode='P0001',message='playoff_series_game_operation_missing';end if;
 response:=p_result||jsonb_build_object(
  'actorId',operation.actor_id,'tournamentId',operation.tournament_id,'eventId',operation.event_id,
  'qualificationId',operation.qualification_id,'slot',operation.slot,'operationId',operation.operation_id,
  'request',operation.request_payload
 );
 insert into app.playoff_series_game_operation_outcomes_v1(actor_id,operation_id,tournament_id,event_id,result)
 values(p_actor_id,p_operation_id,p_tournament_id,p_event_id,response);
 return response;
end$$;

create or replace function app.submit_playoff_series_game_action_v1(
 p_tournament_id uuid,p_event_id uuid,p_qualification_id uuid,p_slot integer,p_request jsonb
)returns jsonb language plpgsql security definer set search_path='' as $$
declare a uuid:=auth.uid();op uuid;h text;prior app.playoff_series_game_operations_v1%rowtype;
 response jsonb;prior_result jsonb;src jsonb;g app.playoff_series_generations_v1%rowtype;game app.playoff_series_games_v1%rowtype;
 requested_game_id uuid;requested_generation_id uuid;requested_submission_id uuid;requested_confirmation_id uuid;winner_id uuid;confirmed_id uuid;
 game_no integer;expected integer;current_version integer;actor_participant uuid;other_participant uuid;
 actor_is_a boolean;action_kind text;saved_action_id uuid;latest_submission app.playoff_series_game_submissions_v1%rowtype;
 sa app.playoff_series_game_submissions_v1%rowtype;sb app.playoff_series_game_submissions_v1%rowtype;
 ca app.playoff_series_game_confirmations_v1%rowtype;cb app.playoff_series_game_confirmations_v1%rowtype;
 verified_id uuid;a_wins integer;b_wins integer;games_count integer;result_id uuid;
begin
 if a is null or not app.valid_playoff_series_game_request_v1(p_request)then
  return jsonb_build_object('status','rejected','code','invalid_request');
 end if;
 if current_setting('transaction_isolation')<>'read committed'then
  return jsonb_build_object('status','retry_exact','code','isolation_not_supported');
 end if;
 op:=(p_request->>'operationId')::uuid;requested_generation_id:=(p_request->>'generationId')::uuid;
 if not pg_try_advisory_xact_lock(hashtextextended('playoff-series-game-op:'||a::text||':'||op::text,0))then
  return jsonb_build_object('status','retry_exact','code','operation_busy');
 end if;
 select * into prior from app.playoff_series_game_operations_v1 where actor_id=a and operation_id=op;
 if found then select result into prior_result from app.playoff_series_game_operation_outcomes_v1
  where actor_id=a and operation_id=op;end if;
 h:=app.playoff_series_game_request_hash_v1(a,p_tournament_id,p_event_id,p_qualification_id,p_slot,p_request);
 if found then
  if prior.tournament_id=p_tournament_id and prior.event_id=p_event_id
   and prior.qualification_id=p_qualification_id and prior.slot=p_slot and prior.request_hash=h
   and prior.request_payload=p_request and prior_result is not null then
   return prior_result||jsonb_build_object('historicalReceipt',true,'currentSourceVerified',false);
  end if;
  response:=jsonb_build_object('status','rejected','code','idempotency_conflict');
  if prior.tournament_id=p_tournament_id and prior.event_id=p_event_id
   and prior.qualification_id=p_qualification_id and prior.slot=p_slot then
   response:=response||jsonb_build_object(
    'actorId',a,'tournamentId',p_tournament_id,'eventId',p_event_id,
    'qualificationId',p_qualification_id,'slot',p_slot,'operationId',op,'request',p_request
   );
   insert into app.playoff_series_game_operation_conflicts_v1(actor_id,operation_id,tournament_id,event_id,
    qualification_id,slot,attempted_request,attempted_hash,result)
   values(a,op,p_tournament_id,p_event_id,p_qualification_id,p_slot,p_request,h,response);
  end if;
  return response;
 end if;
 if to_regprocedure('app.event_settings_operational_activation_enabled_v1()') is null
  or not app.event_settings_operational_activation_enabled_v1()then
  return jsonb_build_object('status','rejected','code','operational_activation_unavailable','operationAttempted',false);
 end if;
 perform 1 from app.tournaments where id=p_tournament_id for update nowait;
 if not found then return jsonb_build_object('status','rejected','code','source_unavailable','operationAttempted',false);end if;
 select * into g from app.playoff_series_generations_v1 where id=requested_generation_id
  and tournament_id=p_tournament_id and event_id=p_event_id and qualification_id=p_qualification_id and slot=p_slot
  for update nowait;
 if not found or not app.playoff_series_game_actor_valid_v1(p_tournament_id,p_event_id,requested_generation_id,a)then
  return jsonb_build_object('status','rejected','code','player_identity_required','operationAttempted',false);
 end if;
 insert into app.playoff_series_game_operations_v1(actor_id,operation_id,tournament_id,event_id,qualification_id,slot,
  generation_id,request_payload,request_hash)
 values(a,op,p_tournament_id,p_event_id,p_qualification_id,p_slot,requested_generation_id,p_request,h);
 src:=app.playoff_series_match_source_v1(p_tournament_id,p_event_id,p_qualification_id,p_slot);
 if src->>'status'='retry_exact'then raise lock_not_available;end if;
 if src->>'status'<>'source_available' then return app.finish_playoff_series_game_operation_v1(a,op,p_tournament_id,p_event_id,
  jsonb_build_object('status','rejected','code','source_unavailable'));end if;
 if g.tournament_id is distinct from p_tournament_id or g.event_id is distinct from p_event_id
  or g.qualification_id is distinct from p_qualification_id or g.slot is distinct from p_slot
  or (p_request->>'generationVersion')::integer is distinct from g.version
  or src->>'currentGenerationId' is distinct from g.id::text
  or (src->>'currentGenerationVersion')::integer is distinct from g.version
  or src->>'sourceDigest' is distinct from g.source_digest or p_request->>'sourceDigest' is distinct from g.source_digest
  or (p_request->>'settingsBindingId')::uuid is distinct from g.settings_binding_id
  or (p_request->>'reviewId')::uuid is distinct from g.context_review_id
  or (p_request->>'playoffStartId')::uuid is distinct from g.playoff_start_id
  or p_request->'parentResultPins' is distinct from src->'parentResultPins'
  or g.source_capture is distinct from src->'source'
 then return app.finish_playoff_series_game_operation_v1(a,op,p_tournament_id,p_event_id,
  jsonb_build_object('status','rejected','code','stale_source'));end if;
 if not app.playoff_series_game_actor_valid_v1(p_tournament_id,p_event_id,g.id,a)then
  return app.finish_playoff_series_game_operation_v1(a,op,p_tournament_id,p_event_id,
   jsonb_build_object('status','rejected','code','player_identity_required'));end if;
 if (select count(*) from app.playoff_series_game_actions_v1 accepted_action where accepted_action.generation_id=g.id)>=10000 then
  return app.finish_playoff_series_game_operation_v1(a,op,p_tournament_id,p_event_id,
   jsonb_build_object('status','rejected','code','series_action_limit_reached'));end if;
 actor_is_a:=a=g.side_a_profile_id;
 actor_participant:=case when actor_is_a then g.side_a_participant_id else g.side_b_participant_id end;
 other_participant:=case when actor_is_a then g.side_b_participant_id else g.side_a_participant_id end;
 requested_game_id:=(p_request->>'gameId')::uuid;game_no:=(p_request->>'gameNumber')::integer;
 expected:=(p_request->>'expectedGameVersion')::integer;
 if game_no>g.maximum_games or exists(select 1 from app.playoff_series_results_v1 result where result.generation_id=g.id)
  or exists(select 1 from app.playoff_series_verified_games_v1 verified where verified.generation_id=g.id group by verified.generation_id
   having count(*)filter(where verified.winner_participant_id=g.side_a_participant_id)>=g.wins_required
       or count(*)filter(where verified.winner_participant_id=g.side_b_participant_id)>=g.wins_required)
  or (select count(*) from app.playoff_series_verified_games_v1 verified where verified.generation_id=g.id and verified.game_number<game_no)<>game_no-1
  or exists(select 1 from app.playoff_series_verified_games_v1 verified where verified.generation_id=g.id and verified.game_number>game_no)
 then return app.finish_playoff_series_game_operation_v1(a,op,p_tournament_id,p_event_id,
  jsonb_build_object('status','rejected','code','game_sequence_closed'));end if;
 select * into game from app.playoff_series_games_v1 candidate where candidate.generation_id=g.id and candidate.game_number=game_no;
 if not found then
  if p_request->>'action'<>'submit' then return app.finish_playoff_series_game_operation_v1(a,op,p_tournament_id,p_event_id,
   jsonb_build_object('status','rejected','code','game_not_started'));end if;
  if expected<>0 then return app.finish_playoff_series_game_operation_v1(a,op,p_tournament_id,p_event_id,
   jsonb_build_object('status','rejected','code','stale_game_version'));end if;
  if exists(select 1 from app.playoff_series_games_v1 where id=requested_game_id)then
   return app.finish_playoff_series_game_operation_v1(a,op,p_tournament_id,p_event_id,
    jsonb_build_object('status','rejected','code','game_identity_conflict'));end if;
  requested_submission_id:=(p_request->>'submissionId')::uuid;
  if p_request->'priorSubmissionId'<>'null'::jsonb then
   return app.finish_playoff_series_game_operation_v1(a,op,p_tournament_id,p_event_id,
    jsonb_build_object('status','rejected','code','latest_own_submission_required'));end if;
  if exists(select 1 from app.playoff_series_game_submissions_v1 where id=requested_submission_id)then
   return app.finish_playoff_series_game_operation_v1(a,op,p_tournament_id,p_event_id,
    jsonb_build_object('status','rejected','code','submission_identity_conflict'));end if;
  winner_id:=(p_request->>'winnerParticipantId')::uuid;
  if winner_id not in(g.side_a_participant_id,g.side_b_participant_id)then
   return app.finish_playoff_series_game_operation_v1(a,op,p_tournament_id,p_event_id,
    jsonb_build_object('status','rejected','code','invalid_winner'));end if;
  insert into app.playoff_series_games_v1(id,generation_id,tournament_id,event_id,game_number,source_digest)
  values(requested_game_id,g.id,p_tournament_id,p_event_id,game_no,g.source_digest) returning * into game;
 elsif game.id<>requested_game_id then return app.finish_playoff_series_game_operation_v1(a,op,p_tournament_id,p_event_id,
  jsonb_build_object('status','rejected','code','game_identity_conflict'));
 end if;
 if exists(select 1 from app.playoff_series_verified_games_v1 verified where verified.game_id=game.id)then
  return app.finish_playoff_series_game_operation_v1(a,op,p_tournament_id,p_event_id,
   jsonb_build_object('status','rejected','code','game_already_verified'));end if;
 select coalesce(max(accepted_action.game_version),0) into current_version from app.playoff_series_game_actions_v1 accepted_action where accepted_action.game_id=game.id;
 if current_version<>expected then return app.finish_playoff_series_game_operation_v1(a,op,p_tournament_id,p_event_id,
  jsonb_build_object('status','rejected','code','stale_game_version'));end if;
 if p_request->>'action'='submit' then
  requested_submission_id:=(p_request->>'submissionId')::uuid;
  winner_id:=(p_request->>'winnerParticipantId')::uuid;
  if winner_id not in(g.side_a_participant_id,g.side_b_participant_id)then
   return app.finish_playoff_series_game_operation_v1(a,op,p_tournament_id,p_event_id,
    jsonb_build_object('status','rejected','code','invalid_winner'));end if;
  if exists(select 1 from app.playoff_series_game_submissions_v1 where id=requested_submission_id)then
   return app.finish_playoff_series_game_operation_v1(a,op,p_tournament_id,p_event_id,
    jsonb_build_object('status','rejected','code','submission_identity_conflict'));end if;
  select s.* into latest_submission from app.playoff_series_game_submissions_v1 s
   join app.playoff_series_game_actions_v1 latest_action on latest_action.id=s.action_id
   where s.game_id=game.id and s.actor_profile_id=a order by latest_action.game_version desc limit 1;
  if (latest_submission.id is null and p_request->'priorSubmissionId'<>'null'::jsonb)
   or (latest_submission.id is not null and p_request->>'priorSubmissionId' is distinct from latest_submission.id::text)
  then return app.finish_playoff_series_game_operation_v1(a,op,p_tournament_id,p_event_id,
   jsonb_build_object('status','rejected','code','latest_own_submission_required'));end if;
  action_kind:=case when found then 'amend' else 'submit' end;
  insert into app.playoff_series_game_actions_v1(actor_id,operation_id,tournament_id,event_id,generation_id,game_id,game_version,action_type)
  values(a,op,p_tournament_id,p_event_id,g.id,game.id,current_version+1,action_kind) returning id into saved_action_id;
  insert into app.playoff_series_game_submissions_v1(id,action_id,game_id,generation_id,tournament_id,event_id,
   actor_profile_id,participant_id,winner_participant_id)
  values(requested_submission_id,saved_action_id,game.id,g.id,p_tournament_id,p_event_id,a,actor_participant,winner_id);
 else
  action_kind:='confirm';requested_confirmation_id:=(p_request->>'confirmationId')::uuid;
  confirmed_id:=(p_request->>'confirmedSubmissionId')::uuid;
  select s.* into latest_submission from app.playoff_series_game_submissions_v1 s
   join app.playoff_series_game_actions_v1 latest_action on latest_action.id=s.action_id
   where s.game_id=game.id and s.actor_profile_id=a order by latest_action.game_version desc limit 1;
  if not found or latest_submission.id<>confirmed_id then
   return app.finish_playoff_series_game_operation_v1(a,op,p_tournament_id,p_event_id,
    jsonb_build_object('status','rejected','code','latest_own_submission_required'));end if;
  if exists(select 1 from app.playoff_series_game_confirmations_v1 confirmation
   where confirmation.game_id=game.id and confirmation.actor_profile_id=a and confirmation.submission_id=confirmed_id)then
   return app.finish_playoff_series_game_operation_v1(a,op,p_tournament_id,p_event_id,
    jsonb_build_object('status','rejected','code','already_confirmed'));end if;
  if exists(select 1 from app.playoff_series_game_confirmations_v1 confirmation where confirmation.id=requested_confirmation_id)then
   return app.finish_playoff_series_game_operation_v1(a,op,p_tournament_id,p_event_id,
    jsonb_build_object('status','rejected','code','confirmation_identity_conflict'));end if;
  insert into app.playoff_series_game_actions_v1(actor_id,operation_id,tournament_id,event_id,generation_id,game_id,game_version,action_type)
  values(a,op,p_tournament_id,p_event_id,g.id,game.id,current_version+1,'confirm') returning id into saved_action_id;
  insert into app.playoff_series_game_confirmations_v1(id,action_id,game_id,generation_id,actor_profile_id,submission_id)
  values(requested_confirmation_id,saved_action_id,game.id,g.id,a,confirmed_id);
 end if;
 -- Only the latest submission from each identity and a confirmation of that
 -- exact row can authorize verification. An amendment therefore invalidates
 -- the amending player's older confirmation without mutating history.
 select s.* into sa from app.playoff_series_game_submissions_v1 s
  join app.playoff_series_game_actions_v1 action on action.id=s.action_id where s.game_id=game.id
  and s.actor_profile_id=g.side_a_profile_id order by action.game_version desc limit 1;
 select s.* into sb from app.playoff_series_game_submissions_v1 s
  join app.playoff_series_game_actions_v1 action on action.id=s.action_id where s.game_id=game.id
  and s.actor_profile_id=g.side_b_profile_id order by action.game_version desc limit 1;
 if sa.id is not null and sb.id is not null and sa.winner_participant_id=sb.winner_participant_id then
  select confirmation.* into ca from app.playoff_series_game_confirmations_v1 confirmation where confirmation.game_id=game.id
   and confirmation.actor_profile_id=g.side_a_profile_id and confirmation.submission_id=sa.id order by confirmation.confirmed_at desc,confirmation.id desc limit 1;
  select confirmation.* into cb from app.playoff_series_game_confirmations_v1 confirmation where confirmation.game_id=game.id
   and confirmation.actor_profile_id=g.side_b_profile_id and confirmation.submission_id=sb.id order by confirmation.confirmed_at desc,confirmation.id desc limit 1;
  if ca.id is not null and cb.id is not null then
   insert into app.playoff_series_verified_games_v1(game_id,generation_id,tournament_id,event_id,game_number,
    winner_participant_id,loser_participant_id,side_a_submission_id,side_b_submission_id,
    side_a_confirmation_id,side_b_confirmation_id,verified_by_action_id,source_digest)
   values(game.id,g.id,p_tournament_id,p_event_id,game_no,sa.winner_participant_id,
    case when sa.winner_participant_id=g.side_a_participant_id then g.side_b_participant_id else g.side_a_participant_id end,
    sa.id,sb.id,ca.id,cb.id,saved_action_id,g.source_digest) returning id into verified_id;
  end if;
 end if;
 if verified_id is not null then
  select count(*)filter(where verified.winner_participant_id=g.side_a_participant_id)::integer,
   count(*)filter(where verified.winner_participant_id=g.side_b_participant_id)::integer,count(*)::integer
  into a_wins,b_wins,games_count from app.playoff_series_verified_games_v1 verified where verified.generation_id=g.id;
  if a_wins=g.wins_required or b_wins=g.wins_required then
   insert into app.playoff_series_results_v1(generation_id,match_id,tournament_id,event_id,winner_participant_id,
    loser_participant_id,wins_a,wins_b,game_count,source_digest,games_digest,completed_by_profile_id,operation_id)
   values(g.id,g.match_id,p_tournament_id,p_event_id,
    case when a_wins=g.wins_required then g.side_a_participant_id else g.side_b_participant_id end,
    case when a_wins=g.wins_required then g.side_b_participant_id else g.side_a_participant_id end,
    a_wins,b_wins,games_count,g.source_digest,app.playoff_series_games_digest_v1(g.id),a,op)
   returning id into result_id;
  end if;
 end if;
 response:=jsonb_build_object('status','playoff_series_game_action_saved_v1','eventId',p_event_id,
  'generationId',g.id,'gameId',game.id,'gameNumber',game_no,'gameVersion',current_version+1,
  'action',action_kind,'verifiedGameId',verified_id,'completedResultId',result_id);
 return app.finish_playoff_series_game_operation_v1(a,op,p_tournament_id,p_event_id,response);
exception when lock_not_available then
 return jsonb_build_object('status','retry_exact','code','source_busy');
end$$;

create or replace function app.get_playoff_series_game_action_reconciliation_v1(
 p_tournament_id uuid,p_operation_id uuid
)returns jsonb language plpgsql security definer set search_path='' as $$
declare a uuid:=auth.uid();o app.playoff_series_game_operations_v1%rowtype;r jsonb;
begin
 if a is null then return null;end if;
 select * into o from app.playoff_series_game_operations_v1 where actor_id=a and operation_id=p_operation_id;
 if not found or o.tournament_id<>p_tournament_id then return jsonb_build_object('authorized',true,'result',null);end if;
 select result into r from app.playoff_series_game_operation_outcomes_v1 where actor_id=a and operation_id=p_operation_id;
 return jsonb_build_object('authorized',true,'result',case when r is null then null else
  r||jsonb_build_object('historicalReceipt',true,'currentSourceVerified',false)end);
end$$;

do $$declare n text;begin
 foreach n in array array[
  'app.playoff_series_uuid_v1(text)','app.valid_playoff_series_game_request_v1(jsonb)',
  'app.playoff_series_game_request_hash_v1(uuid,uuid,uuid,uuid,integer,jsonb)',
  'app.playoff_series_game_actor_valid_v1(uuid,uuid,uuid,uuid)',
  'app.playoff_series_games_digest_v1(uuid)','app.playoff_series_completed_result_valid_v1(uuid)',
  'app.require_playoff_series_completed_result_v1()',
  'app.finish_playoff_series_game_operation_v1(uuid,uuid,uuid,uuid,jsonb)',
  'app.submit_playoff_series_game_action_v1(uuid,uuid,uuid,integer,jsonb)',
  'app.get_playoff_series_game_action_reconciliation_v1(uuid,uuid)'
 ]loop
  execute format('alter function %s owner to postgres',n);
  execute format('revoke all on function %s from public,anon,authenticated,service_role',n);
 end loop;
end$$;


-- Frozen source native-playoff-finance-recipient-source-v1.sql


create function app.native_playoff_finance_recipient_source_enabled_v1()
returns boolean language sql stable set search_path='' as $$select false$$;

create function app.get_native_playoff_finance_recipient_source_v1(
 p_tournament_id uuid,p_event_id uuid
)returns jsonb language plpgsql security definer set search_path='' as $$
declare
 actor uuid:=auth.uid();finance jsonb;gate_source jsonb;capture_value jsonb;
 proposal app.operational_event_finance_revisions_v1%rowtype;
 qualification app.qualification_result_versions%rowtype;
 generation app.playoff_series_generations_v1%rowtype;
 result_row app.playoff_series_results_v1%rowtype;
 match_source jsonb;current_result jsonb;players jsonb;matches jsonb:='[]'::jsonb;
 games jsonb;actions jsonb;match_value jsonb;action_history_digest text;source_digest text;
 native_playoff_start_id uuid;slot_no integer;slot_count integer;qualified_count integer;valid_result boolean;
begin
 if actor is null then return jsonb_build_object('status','blocked','code','authentication_required');end if;
 if current_setting('transaction_isolation')<>'read committed'then
  return jsonb_build_object('status','retry_exact','code','isolation_not_supported');
 end if;
 if p_tournament_id is null or p_event_id is null then
  return jsonb_build_object('status','blocked','code','invalid_request');
 end if;
 if not pg_try_advisory_xact_lock(hashtextextended('event-lifecycle:'||p_event_id::text,0))then
  return jsonb_build_object('status','retry_exact','code','event_busy');
 end if;
 perform 1 from app.tournaments where id=p_tournament_id for update nowait;
 if not found then return jsonb_build_object('status','blocked','code','tournament_unavailable');end if;
 perform 1 from app.tournament_roles where tournament_id=p_tournament_id
  and profile_id=actor and role in('director','co_director')order by role for key share nowait;
 if not found then return jsonb_build_object('status','blocked','code','not_director');end if;
 if app.native_playoff_finance_recipient_source_enabled_v1()is distinct from true then
  return jsonb_build_object('status','blocked','code','feature_unavailable',
   'proposalOnly',true,'moneyMoved',false,'payoutAuthorized',false,'finalizationAuthorized',false);
 end if;

 perform app.lock_operational_event_finance_sources_v1();
 lock table app.operational_event_finance_operations_v1,
  app.operational_event_finance_revisions_v1,
  app.operational_event_finance_outcomes_v1,
  app.initial_seating_publications,app.initial_seating_assignments,
  app.roster_account_links,
  app.event_settings_playoff_reviews_v1,app.event_settings_playoff_starts_v1,
  app.playoff_series_match_operations_v1,app.playoff_series_matches_v1,
  app.playoff_series_generations_v1,app.playoff_series_results_v1,
  app.playoff_series_game_operations_v1,app.playoff_series_game_operation_outcomes_v1,
  app.playoff_series_game_operation_conflicts_v1,app.playoff_series_games_v1,
  app.playoff_series_game_actions_v1,app.playoff_series_game_submissions_v1,
  app.playoff_series_game_confirmations_v1,app.playoff_series_verified_games_v1
 in share mode nowait;

 finance:=app.operational_event_finance_source_v1(p_tournament_id,p_event_id,actor);
 if finance->>'status'='retry_exact'then return finance;end if;
 if finance->>'status'is distinct from'source_available'then
  return jsonb_build_object('status','blocked','code',coalesce(finance->>'code','finance_source_unavailable'));
 end if;
 select*into proposal from app.operational_event_finance_revisions_v1
  where tournament_id=p_tournament_id and event_id=p_event_id order by version desc limit 1;
 if proposal.id is null then return jsonb_build_object('status','blocked','code','finance_proposal_required');end if;
 if proposal.source_digest is distinct from finance->>'sourceDigest'
  or proposal.basis_digest is distinct from finance->>'basisDigest'
  or proposal.source_capture is distinct from finance->'raw'
  or proposal.basis is distinct from finance->'basis'
  or proposal.proposal_only is distinct from true or proposal.money_moved
  or proposal.payout_authorized or proposal.finalization_authorized then
  return jsonb_build_object('status','blocked','code','finance_proposal_source_changed');
 end if;

 select*into qualification from app.qualification_result_versions
  where id=proposal.qualification_result_version_id and tournament_id=p_tournament_id
   and event_id=p_event_id;
 if qualification.id is null
  or qualification.id::text is distinct from finance#>>'{raw,qualification,resultVersionId}'
  or qualification.version::text is distinct from finance#>>'{raw,qualification,version}'
  or qualification.participant_count::text is distinct from finance#>>'{raw,qualification,participantCount}'
  or qualification.qualifier_count::text is distinct from finance#>>'{raw,qualification,qualifierCount}'
  or qualification.qualifier_count not in(4,5)
  or app.qualification_resolution_snapshot_current_v1(qualification.id)is distinct from true then
  return jsonb_build_object('status','blocked','code','qualification_source_changed');
 end if;
 slot_count:=case qualification.qualifier_count when 4 then 3 else 4 end;

 gate_source:=app.event_settings_playoff_source_v1(p_tournament_id,p_event_id);
 if gate_source->>'status'='retry_exact'then return gate_source;end if;
 if gate_source->>'status'is distinct from'source_available'
  or gate_source->>'qualificationId'is distinct from qualification.id::text
  or gate_source->>'settingsBindingId'is distinct from finance#>>'{raw,binding,bindingId}'
  or gate_source->>'reviewId'is distinct from finance#>>'{raw,binding,reviewId}'then
  return jsonb_build_object('status','blocked','code','playoff_gate_source_changed');
 end if;

 select count(*)::integer,coalesce(jsonb_agg(jsonb_build_object(
  'participantId',row.participant_id,'profileId',participant.profile_id,
  'displayName',row.display_name_snapshot,'tournamentPlayerId',seating.verification_id,
  'seed',row.ranking_ordinal
 )order by row.ranking_ordinal),'[]'::jsonb)
 into qualified_count,players
 from app.qualification_result_rows row
 join app.event_participants participant on participant.id=row.participant_id
  and participant.tournament_id=row.tournament_id and participant.event_id=row.event_id
 join app.initial_seating_assignments seating on seating.tournament_id=participant.tournament_id
  and seating.roster_entry_id=participant.roster_entry_id
 where row.result_version_id=qualification.id and row.qualification_status='qualified'
  and participant.profile_id is not null and participant.status='checked_in';
 if qualified_count<>qualification.qualifier_count
  or jsonb_array_length(players)<>qualification.qualifier_count
  or(select count(distinct value->>'participantId')from jsonb_array_elements(players))<>qualification.qualifier_count
  or(select count(distinct value->>'profileId')from jsonb_array_elements(players))<>qualification.qualifier_count
  or(select count(distinct value->>'tournamentPlayerId')from jsonb_array_elements(players))<>qualification.qualifier_count
 then return jsonb_build_object('status','blocked','code','qualified_player_identity_unavailable');end if;

 for slot_no in 1..slot_count loop
  match_source:=app.playoff_series_match_source_v1(
   p_tournament_id,p_event_id,qualification.id,slot_no
  );
  if match_source->>'status'='retry_exact'then return match_source;end if;
  if match_source->>'status'is distinct from'source_available'
   or match_source->'currentGenerationId'='null'::jsonb then
   return jsonb_build_object('status','blocked','code','playoff_series_incomplete','slot',slot_no);
  end if;
  current_result:=app.playoff_series_current_result_v1(
   p_tournament_id,p_event_id,qualification.id,slot_no
  );
  if current_result is null then
   return jsonb_build_object('status','blocked','code','playoff_series_incomplete','slot',slot_no);
  end if;
  select*into generation from app.playoff_series_generations_v1
   where id=(match_source->>'currentGenerationId')::uuid
    and tournament_id=p_tournament_id and event_id=p_event_id
    and qualification_id=qualification.id and slot=slot_no;
  select*into result_row from app.playoff_series_results_v1
   where id=(current_result->>'resultId')::uuid and generation_id=generation.id
    and tournament_id=p_tournament_id and event_id=p_event_id;
  if generation.id is null or result_row.id is null
   or generation.version<>(match_source->>'currentGenerationVersion')::integer
   or generation.source_digest is distinct from match_source->>'sourceDigest'
   or generation.source_capture is distinct from match_source->'source'
   or generation.settings_binding_id::text is distinct from match_source->>'settingsBindingId'
   or generation.context_review_id::text is distinct from match_source->>'reviewId'
   or generation.playoff_start_id::text is distinct from match_source->>'playoffStartId'
   or result_row.match_id is distinct from generation.match_id
   or result_row.source_digest is distinct from generation.source_digest
   or current_result->>'matchId'is distinct from generation.match_id::text
   or current_result->>'winnerId'is distinct from result_row.winner_participant_id::text
   or current_result->>'loserId'is distinct from result_row.loser_participant_id::text then
   return jsonb_build_object('status','blocked','code','playoff_series_source_changed','slot',slot_no);
  end if;
  if native_playoff_start_id is null then native_playoff_start_id:=generation.playoff_start_id;
  elsif native_playoff_start_id is distinct from generation.playoff_start_id then
   return jsonb_build_object('status','blocked','code','playoff_series_source_changed','slot',slot_no);
  end if;
  valid_result:=app.playoff_series_completed_result_valid_v1(result_row.id);
  if valid_result is distinct from true then
   return jsonb_build_object('status','blocked','code','playoff_game_evidence_changed','slot',slot_no);
  end if;

  select encode(extensions.digest(convert_to(coalesce(jsonb_agg(jsonb_build_object(
   'operation',to_jsonb(operation_row),'action',to_jsonb(action_row),'submission',to_jsonb(submission_row),
   'confirmation',to_jsonb(confirmation_row)
  )order by game_row.game_number,action_row.game_version,action_row.id),'[]'::jsonb)::text,'utf8'),'sha256'),'hex')
  into action_history_digest
  from app.playoff_series_game_actions_v1 action_row
  join app.playoff_series_games_v1 game_row on game_row.id=action_row.game_id
   and game_row.generation_id=action_row.generation_id
  join app.playoff_series_game_operations_v1 operation_row on operation_row.actor_id=action_row.actor_id
   and operation_row.operation_id=action_row.operation_id
  left join app.playoff_series_game_submissions_v1 submission_row on submission_row.action_id=action_row.id
  left join app.playoff_series_game_confirmations_v1 confirmation_row on confirmation_row.action_id=action_row.id
  where action_row.generation_id=generation.id;

  select coalesce(jsonb_agg(jsonb_build_object(
   'actionId',action_row.id,'operationId',action_row.operation_id,'actorId',action_row.actor_id,
   'gameId',action_row.game_id,'gameVersion',action_row.game_version,'actionType',action_row.action_type,
   'priorSubmissionId',case when action_row.action_type in('submit','amend')
    then coalesce(operation_row.request_payload->'priorSubmissionId','null'::jsonb)else'null'::jsonb end,
   'submission',case when submission_row.id is null then null else jsonb_build_object(
    'submissionId',submission_row.id,'participantId',submission_row.participant_id,
    'winnerParticipantId',submission_row.winner_participant_id)end,
   'confirmation',case when confirmation_row.id is null then null else jsonb_build_object(
    'confirmationId',confirmation_row.id,'submissionId',confirmation_row.submission_id)end
  )order by game_row.game_number,action_row.game_version,action_row.id),'[]'::jsonb)into actions
  from app.playoff_series_game_actions_v1 action_row
  join app.playoff_series_games_v1 game_row on game_row.id=action_row.game_id
   and game_row.generation_id=action_row.generation_id
  join app.playoff_series_game_operations_v1 operation_row on operation_row.actor_id=action_row.actor_id
   and operation_row.operation_id=action_row.operation_id
  left join app.playoff_series_game_submissions_v1 submission_row on submission_row.action_id=action_row.id
  left join app.playoff_series_game_confirmations_v1 confirmation_row on confirmation_row.action_id=action_row.id
  where action_row.generation_id=generation.id;

  select coalesce(jsonb_agg(jsonb_build_object(
   'gameId',verified.game_id,'gameNumber',verified.game_number,
   'gameVersion',verified_action.game_version,'verifiedGameId',verified.id,
   'verifiedByActionId',verified.verified_by_action_id,
   'winnerParticipantId',verified.winner_participant_id,
   'loserParticipantId',verified.loser_participant_id,'sourceDigest',verified.source_digest,
   'submissions',jsonb_build_array(
    jsonb_build_object('submissionId',side_a_submission.id,'actionId',side_a_action.id,
     'actorId',side_a_submission.actor_profile_id,'winnerParticipantId',side_a_submission.winner_participant_id,
     'gameVersion',side_a_action.game_version),
    jsonb_build_object('submissionId',side_b_submission.id,'actionId',side_b_action.id,
     'actorId',side_b_submission.actor_profile_id,'winnerParticipantId',side_b_submission.winner_participant_id,
     'gameVersion',side_b_action.game_version)
   ),
   'confirmations',jsonb_build_array(
    jsonb_build_object('confirmationId',side_a_confirmation.id,'actionId',side_a_confirmation_action.id,
     'actorId',side_a_confirmation.actor_profile_id,'submissionId',side_a_confirmation.submission_id,
     'gameVersion',side_a_confirmation_action.game_version),
    jsonb_build_object('confirmationId',side_b_confirmation.id,'actionId',side_b_confirmation_action.id,
     'actorId',side_b_confirmation.actor_profile_id,'submissionId',side_b_confirmation.submission_id,
     'gameVersion',side_b_confirmation_action.game_version)
   )
  )order by verified.game_number),'[]'::jsonb)into games
  from app.playoff_series_verified_games_v1 verified
  join app.playoff_series_game_actions_v1 verified_action on verified_action.id=verified.verified_by_action_id
  join app.playoff_series_game_submissions_v1 side_a_submission on side_a_submission.id=verified.side_a_submission_id
  join app.playoff_series_game_actions_v1 side_a_action on side_a_action.id=side_a_submission.action_id
  join app.playoff_series_game_submissions_v1 side_b_submission on side_b_submission.id=verified.side_b_submission_id
  join app.playoff_series_game_actions_v1 side_b_action on side_b_action.id=side_b_submission.action_id
  join app.playoff_series_game_confirmations_v1 side_a_confirmation on side_a_confirmation.id=verified.side_a_confirmation_id
  join app.playoff_series_game_actions_v1 side_a_confirmation_action on side_a_confirmation_action.id=side_a_confirmation.action_id
  join app.playoff_series_game_confirmations_v1 side_b_confirmation on side_b_confirmation.id=verified.side_b_confirmation_id
  join app.playoff_series_game_actions_v1 side_b_confirmation_action on side_b_confirmation_action.id=side_b_confirmation.action_id
  where verified.generation_id=generation.id;
  if jsonb_array_length(games)<>result_row.game_count or jsonb_array_length(actions)>10000
   or action_history_digest is null or action_history_digest!~'^[a-f0-9]{64}$'then
   return jsonb_build_object('status','blocked','code','playoff_game_evidence_changed','slot',slot_no);
  end if;

  match_value:=jsonb_build_object(
   'slot',slot_no,'round',generation.round_name,'matchId',generation.match_id,
   'generationId',generation.id,'generationVersion',generation.version,
   'sourceDigest',generation.source_digest,'sourceCapture',generation.source_capture,
   'actionHistoryDigest',action_history_digest,'actions',actions,
   'participants',match_source->'participants','profiles',match_source->'profiles',
   'parentResultPins',match_source->'parentResultPins',
   'winsRequired',generation.wins_required,'maximumGames',generation.maximum_games,
   'result',jsonb_build_object(
    'resultId',result_row.id,'version',result_row.version,
    'winnerId',result_row.winner_participant_id,'loserId',result_row.loser_participant_id,
    'winsA',result_row.wins_a,'winsB',result_row.wins_b,
    'gameCount',result_row.game_count,'sourceDigest',result_row.source_digest,
    'gamesDigest',result_row.games_digest,
    'completedByProfileId',result_row.completed_by_profile_id,'operationId',result_row.operation_id
   ),'games',games
  );
  matches:=matches||jsonb_build_array(match_value);
 end loop;

 if jsonb_array_length(matches)<>slot_count
  or(select count(*)from app.playoff_series_matches_v1
     where tournament_id=p_tournament_id and event_id=p_event_id
      and qualification_id=qualification.id)<>slot_count
  or(select count(*)from app.playoff_series_results_v1 result
     join app.playoff_series_generations_v1 generation_row on generation_row.id=result.generation_id
     where generation_row.tournament_id=p_tournament_id and generation_row.event_id=p_event_id
      and generation_row.qualification_id=qualification.id)<>slot_count then
  return jsonb_build_object('status','blocked','code','playoff_series_set_changed');
 end if;

 capture_value:=jsonb_build_object(
  'kind','native-finance-recipient-source-v1','actorId',actor,
  'tournamentId',p_tournament_id,'eventId',p_event_id,
  'nativeFinanceSource',finance,
  'proposal',jsonb_build_object(
   'revisionId',proposal.id,'version',proposal.version,
   'sourceDigest',proposal.source_digest,'basisDigest',proposal.basis_digest,
   'qualificationResultVersionId',proposal.qualification_result_version_id,
   'editor',proposal.editor
  ),
  'expectedHead',jsonb_build_object('revisionId',proposal.id,'version',proposal.version),
  'playoff',jsonb_build_object(
   'qualificationResultVersionId',qualification.id,'qualificationVersion',qualification.version,
   'entrantCount',qualification.participant_count,'qualifierCount',qualification.qualifier_count,
   'eventKind',finance#>'{raw,event,eventKind}',
   'settingsSnapshotId',finance#>'{raw,binding,settingsSnapshotId}',
   'settingsBindingId',gate_source->'settingsBindingId',
   'playoffStartId',native_playoff_start_id,'gateDigest',gate_source->'sourceDigest',
   'players',players,'matches',matches
  ),
  'proposalOnly',true,'moneyMoved',false,
  'payoutAuthorized',false,'finalizationAuthorized',false
 );
 source_digest:=encode(extensions.digest(convert_to(jsonb_build_array(
  'native-finance-recipient-source-v1',capture_value
 )::text,'utf8'),'sha256'),'hex');
 return capture_value||jsonb_build_object('status','source_available','sourceDigest',source_digest);
exception when lock_not_available then
 return jsonb_build_object('status','retry_exact','code','source_busy');
 when invalid_text_representation or numeric_value_out_of_range then
 return jsonb_build_object('status','blocked','code','source_shape_invalid');
end$$;

alter function app.native_playoff_finance_recipient_source_enabled_v1()owner to postgres;
alter function app.get_native_playoff_finance_recipient_source_v1(uuid,uuid)owner to postgres;
revoke all on function app.native_playoff_finance_recipient_source_enabled_v1()
 from public,anon,authenticated,service_role;
revoke all on function app.get_native_playoff_finance_recipient_source_v1(uuid,uuid)
 from public,anon,authenticated,service_role;


-- Frozen source native-playoff-final-awards-v1.sql


create function app.native_playoff_final_awards_enabled_v1() returns boolean
language sql immutable set search_path='' as $$select false$$;

create table app.native_playoff_finance_write_operations_v1(
 actor_id uuid not null references app.profiles(id),
 operation_id uuid not null,
 tournament_id uuid not null,
 event_id uuid not null,
 request_payload jsonb not null,
 request_hash text not null check(request_hash~'^[a-f0-9]{64}$'),
 created_at timestamptz not null default clock_timestamp(),
 primary key(actor_id,operation_id),
 unique(actor_id,operation_id,tournament_id,event_id),
 foreign key(event_id,tournament_id) references app.events(id,tournament_id),
 check(request_hash=encode(extensions.digest(convert_to(jsonb_build_array(
  'native-playoff-finance-write-v1',actor_id,tournament_id,event_id,
  operation_id,request_payload
 )::text,'utf8'),'sha256'),'hex'))
);

create table app.native_playoff_finance_write_outcomes_v1(
 actor_id uuid not null,operation_id uuid not null,
 tournament_id uuid not null,event_id uuid not null,
 result jsonb not null,created_at timestamptz not null default clock_timestamp(),
 primary key(actor_id,operation_id),
 foreign key(actor_id,operation_id,tournament_id,event_id)
  references app.native_playoff_finance_write_operations_v1(actor_id,operation_id,tournament_id,event_id)
);

create table app.native_unrestricted_income_sources_v1(
 tournament_id uuid not null,event_id uuid not null,income_id uuid not null,
 physical_evidence_id uuid not null,evidence_reference text not null,
 created_by uuid not null,created_at timestamptz not null default clock_timestamp(),
 primary key(tournament_id,income_id),
 unique(tournament_id,physical_evidence_id),
 foreign key(event_id,tournament_id) references app.events(id,tournament_id),
 foreign key(created_by) references app.profiles(id),
 check(evidence_reference=app.custom_payout_classification_text_v2(evidence_reference)
  and app.event_settings_js_text_length_v3(evidence_reference) between 1 and 2000)
);
create unique index native_unrestricted_income_evidence_owner_v1
 on app.native_unrestricted_income_sources_v1(tournament_id,lower(evidence_reference));

create table app.native_unrestricted_income_records_v1(
 id uuid primary key default extensions.gen_random_uuid(),
 tournament_id uuid not null,event_id uuid not null,
 version integer not null check(version between 1 and 2147483647),
 income_id uuid not null,record_id uuid not null,prior_record_id uuid,
 physical_evidence_id uuid not null,evidence_reference text not null,
 proposal_revision_id uuid not null,
 amount_minor bigint not null check(amount_minor between 0 and 9007199254740991),
 voided boolean not null,label text not null,reason text not null,
 recorded_by uuid not null,actor_id uuid not null,operation_id uuid not null,
 source_capture jsonb not null,source_digest text not null check(source_digest~'^[a-f0-9]{64}$'),
 recorded_at timestamptz not null default clock_timestamp(),
 unique(tournament_id,event_id,version),
 unique(tournament_id,income_id,record_id),
 unique(id,tournament_id,event_id),
 unique(actor_id,operation_id),
 foreign key(event_id,tournament_id) references app.events(id,tournament_id),
 foreign key(proposal_revision_id,tournament_id,event_id)
  references app.operational_event_finance_revisions_v1(id,tournament_id,event_id),
 foreign key(tournament_id,income_id)
  references app.native_unrestricted_income_sources_v1(tournament_id,income_id),
 foreign key(tournament_id,income_id,prior_record_id)
  references app.native_unrestricted_income_records_v1(tournament_id,income_id,record_id),
 foreign key(actor_id,operation_id,tournament_id,event_id)
  references app.native_playoff_finance_write_operations_v1(actor_id,operation_id,tournament_id,event_id),
 foreign key(recorded_by) references app.profiles(id),
 check(evidence_reference=app.custom_payout_classification_text_v2(evidence_reference)
  and app.event_settings_js_text_length_v3(evidence_reference) between 1 and 2000),
 check(label=app.custom_payout_classification_text_v2(label)
  and app.event_settings_js_text_length_v3(label) between 1 and 200),
 check(reason=app.custom_payout_classification_text_v2(reason)
  and app.event_settings_js_text_length_v3(reason) between 1 and 2000)
);

create index native_unrestricted_income_head_v1
 on app.native_unrestricted_income_records_v1(tournament_id,event_id,version desc);

create table app.native_recorded_fund_reviews_v1(
 id uuid primary key default extensions.gen_random_uuid(),
 tournament_id uuid not null,event_id uuid not null,
 version integer not null check(version between 1 and 2147483647),
 prior_review_id uuid,proposal_revision_id uuid not null,
 native_allocation_revision_id uuid not null,
 sanctioning_fee_snapshot_id uuid not null,
 sanctioning_expense_event_id uuid,
 sanctioning_allocated_minor bigint not null check(sanctioning_allocated_minor between 0 and 9007199254740991),
 income_head_version integer not null check(income_head_version between 0 and 2147483647),
 income_head_digest text not null check(income_head_digest~'^[a-f0-9]{64}$'),
 review_status text not null check(review_status in('reviewed_zero','recorded_complete')),
 source_capture jsonb not null,source_digest text not null check(source_digest~'^[a-f0-9]{64}$'),
 reason text not null,reviewed_by uuid not null,actor_id uuid not null,operation_id uuid not null,
 reviewed_at timestamptz not null default clock_timestamp(),
 unique(tournament_id,event_id,version),
 unique(id,tournament_id,event_id),unique(actor_id,operation_id),
 foreign key(event_id,tournament_id) references app.events(id,tournament_id),
 foreign key(prior_review_id,tournament_id,event_id)
  references app.native_recorded_fund_reviews_v1(id,tournament_id,event_id),
 foreign key(proposal_revision_id,tournament_id,event_id)
  references app.operational_event_finance_revisions_v1(id,tournament_id,event_id),
 foreign key(native_allocation_revision_id,tournament_id)
  references app.native_ledger_allocation_revisions_v1(id,tournament_id),
 foreign key(sanctioning_fee_snapshot_id,tournament_id,event_id)
  references app.event_sanctioning_fee_snapshots(id,tournament_id,event_id),
 foreign key(sanctioning_expense_event_id)
  references app.tournament_expense_events(id),
 foreign key(actor_id,operation_id,tournament_id,event_id)
  references app.native_playoff_finance_write_operations_v1(actor_id,operation_id,tournament_id,event_id),
 foreign key(reviewed_by) references app.profiles(id),
 check(reason=app.custom_payout_classification_text_v2(reason)
  and app.event_settings_js_text_length_v3(reason) between 1 and 2000),
 check((sanctioning_expense_event_id is null and sanctioning_allocated_minor=0)
  or(sanctioning_expense_event_id is not null and sanctioning_allocated_minor>0))
);

create table app.native_playoff_final_award_sets_v1(
 id uuid primary key default extensions.gen_random_uuid(),
 tournament_id uuid not null,event_id uuid not null,version integer not null check(version=1),
 proposal_revision_id uuid not null,fund_review_id uuid not null,
 qualification_result_version_id uuid not null,
 recipient_source_digest text not null check(recipient_source_digest~'^[a-f0-9]{64}$'),
 fund_source_digest text not null check(fund_source_digest~'^[a-f0-9]{64}$'),
 source_digest text not null check(source_digest~'^[a-f0-9]{64}$'),source_capture jsonb not null,
 total_minor bigint not null check(total_minor between 0 and 9007199254740991),
 recipient_count integer not null check(recipient_count between 1 and 256),
 reason text not null,recorded_by uuid not null,actor_id uuid not null,operation_id uuid not null,
 award_status text not null default'recorded_unpaid' check(award_status='recorded_unpaid'),
 money_moved boolean not null default false check(not money_moved),
 payout_authorized boolean not null default false check(not payout_authorized),
 disbursement_authorized boolean not null default false check(not disbursement_authorized),
 finalization_authorized boolean not null default false check(not finalization_authorized),
 recorded_at timestamptz not null default clock_timestamp(),
 unique(tournament_id,event_id),unique(id,tournament_id,event_id),unique(actor_id,operation_id),
 foreign key(event_id,tournament_id) references app.events(id,tournament_id),
 foreign key(proposal_revision_id,tournament_id,event_id)
  references app.operational_event_finance_revisions_v1(id,tournament_id,event_id),
 foreign key(fund_review_id,tournament_id,event_id)
  references app.native_recorded_fund_reviews_v1(id,tournament_id,event_id),
 foreign key(qualification_result_version_id,tournament_id,event_id)
  references app.qualification_result_versions(id,tournament_id,event_id),
 foreign key(actor_id,operation_id,tournament_id,event_id)
  references app.native_playoff_finance_write_operations_v1(actor_id,operation_id,tournament_id,event_id),
 foreign key(recorded_by) references app.profiles(id),
 check(reason=app.custom_payout_classification_text_v2(reason)
  and app.event_settings_js_text_length_v3(reason) between 1 and 2000)
);

create table app.native_playoff_final_award_groups_v1(
 award_set_id uuid not null,tournament_id uuid not null,event_id uuid not null,
 first_place integer not null,last_place integer not null,people integer not null,
 included boolean not null,per_person_minor bigint not null,group_total_minor bigint not null,
 primary key(award_set_id,first_place,last_place),
 foreign key(award_set_id,tournament_id,event_id)
  references app.native_playoff_final_award_sets_v1(id,tournament_id,event_id),
 check(first_place>=1 and last_place>=first_place and people=last_place-first_place+1),
 check((included and per_person_minor>0 and per_person_minor%500=0
   and group_total_minor=people::bigint*per_person_minor)
  or(not included and per_person_minor=0 and group_total_minor=0))
);

create table app.native_playoff_final_award_recipients_v1(
 award_set_id uuid not null,tournament_id uuid not null,event_id uuid not null,
 participant_id uuid not null,profile_id uuid not null,tournament_player_id text not null,
 display_name text not null,first_place integer not null,last_place integer not null,
 included boolean not null,amount_minor bigint not null,
 primary key(award_set_id,participant_id),
 foreign key(award_set_id,tournament_id,event_id)
  references app.native_playoff_final_award_sets_v1(id,tournament_id,event_id),
 foreign key(participant_id,profile_id,event_id,tournament_id)
  references app.event_participants(id,profile_id,event_id,tournament_id),
 check(first_place>=1 and last_place>=first_place),
 check((included and amount_minor>0 and amount_minor%500=0)or(not included and amount_minor=0))
);

do $$declare n text;begin foreach n in array array[
 'native_playoff_finance_write_operations_v1','native_playoff_finance_write_outcomes_v1',
 'native_unrestricted_income_sources_v1',
 'native_unrestricted_income_records_v1','native_recorded_fund_reviews_v1',
 'native_playoff_final_award_sets_v1','native_playoff_final_award_groups_v1',
 'native_playoff_final_award_recipients_v1'
]loop
 execute format('alter table app.%I owner to postgres',n);
 execute format('alter table app.%I enable row level security',n);
 execute format('alter table app.%I force row level security',n);
 execute format('revoke all on table app.%I from public,anon,authenticated,service_role',n);
 execute format('create trigger %I before update or delete on app.%I for each row execute function app.reject_immutable_history()',n||'_immutable',n);
end loop;end$$;

create function app.finish_native_playoff_finance_write_v1(
 actor uuid,tid uuid,eid uuid,op uuid,result_value jsonb
)returns jsonb
language plpgsql security definer set search_path=''as $$
declare operation app.native_playoff_finance_write_operations_v1%rowtype;result jsonb;begin
 select*into strict operation from app.native_playoff_finance_write_operations_v1
  where actor_id=actor and operation_id=op and tournament_id=tid and event_id=eid;
 if result_value->>'status'not in('accepted','rejected')then raise exception'invalid_native_playoff_finance_outcome';end if;
 result:=result_value||jsonb_build_object(
  'actorId',actor,'tournamentId',tid,'eventId',eid,'operationId',op,
  'request',operation.request_payload,'fullRequestHash',operation.request_hash,
  'historicalReceipt',false,'currentSourceVerified',result_value->>'status'='accepted',
  'moneyMoved',false,'payoutAuthorized',false,'disbursementAuthorized',false,
  'finalizationAuthorized',false
 );
 insert into app.native_playoff_finance_write_outcomes_v1(
  actor_id,operation_id,tournament_id,event_id,result
 )values(actor,op,tid,eid,result);
 return result;
end$$;

create function app.legacy_financial_liability_exists_v1(tid uuid,eid uuid)returns boolean
language plpgsql security definer set search_path=''as $$
declare n text;r regclass;hit boolean;begin
 foreach n in array array['standard_singles_settlement_final_versions','event_settlement_finals_v2',
  'q_accounting_finals_v6','no_q_accounting_finals_v7','prize_accounting_finals_v8','prize_accounting_finals_v9',
  'multi_event_unpaid_finals_v1']loop
  r:=to_regclass('app.'||n);if r is null then return null;end if;
  execute format('select exists(select 1 from %s where tournament_id=$1 and event_id=$2)',r)into hit using tid,eid;
  if hit then return true;end if;
 end loop;
 r:=to_regclass('app.multi_event_joint_finals_v1');if r is null then return null;end if;
 execute format('select exists(select 1 from %s where tournament_id=$1)',r)into hit using tid;
 return hit;
end$$;

create function app.require_no_native_final_award_liability_v1()returns trigger
language plpgsql security definer set search_path=''as $$
begin
 if current_setting('transaction_isolation')<>'read committed'then raise exception'native_final_award_isolation_not_supported';end if;
 perform 1 from app.tournaments where id=new.tournament_id for update nowait;
 if tg_table_name='multi_event_joint_finals_v1'then
  if exists(select 1 from app.native_playoff_final_award_sets_v1 where tournament_id=new.tournament_id)then
   raise exception'native_final_award_liability_exists';end if;
 elsif exists(select 1 from app.native_playoff_final_award_sets_v1 where tournament_id=new.tournament_id and event_id=new.event_id)then
  raise exception'native_final_award_liability_exists';
 end if;
 return new;
end$$;

do $$declare n text;begin foreach n in array array['standard_singles_settlement_final_versions','event_settlement_finals_v2',
 'q_accounting_finals_v6','no_q_accounting_finals_v7','prize_accounting_finals_v8','prize_accounting_finals_v9',
 'multi_event_unpaid_finals_v1','multi_event_joint_finals_v1']loop
 execute format('create trigger aa_native_final_award_liability_v1 before insert on app.%I for each row execute function app.require_no_native_final_award_liability_v1()',n);
end loop;end$$;

create function app.record_native_playoff_final_awards_v1(
 tid uuid,eid uuid,request_value jsonb
)returns jsonb
language plpgsql security definer set search_path=''as $$
declare a uuid:=auth.uid();op uuid;request_hash text;prior_op app.native_playoff_finance_write_operations_v1%rowtype;
 prior_result jsonb;source_value jsonb;award_id uuid;group_value jsonb;recipient_value jsonb;reason_value text;
 response jsonb;legacy_exists boolean;
begin
 if a is null then return jsonb_build_object('status','rejected','code','authentication_required');end if;
 if current_setting('transaction_isolation')<>'read committed'then return jsonb_build_object('status','retry_exact','code','isolation_not_supported');end if;
 if jsonb_typeof(request_value)is distinct from'object'or(select count(*)from jsonb_object_keys(request_value))<>9
  or not(request_value?&array['kind','operationId','expectedVersion','expectedSourceDigest','expectedRecipientSourceDigest',
   'expectedFundSourceDigest','expectedProposalRevisionId','expectedFundReviewId','reason'])
  or request_value->>'kind'is distinct from'native-playoff-final-awards-v1'
  or coalesce(request_value->>'operationId','')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
  or request_value->'expectedVersion'is distinct from'0'::jsonb
  or coalesce(request_value->>'expectedSourceDigest','')!~'^[a-f0-9]{64}$'
  or coalesce(request_value->>'expectedRecipientSourceDigest','')!~'^[a-f0-9]{64}$'
  or coalesce(request_value->>'expectedFundSourceDigest','')!~'^[a-f0-9]{64}$'
  or coalesce(request_value->>'expectedProposalRevisionId','')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
  or coalesce(request_value->>'expectedFundReviewId','')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
  or jsonb_typeof(request_value->'reason')is distinct from'string'
  or request_value->>'reason'<>app.custom_payout_classification_text_v2(request_value->>'reason')
  or app.event_settings_js_text_length_v3(request_value->>'reason')not between 1 and 2000 then
  return jsonb_build_object('status','rejected','code','invalid_request');end if;
 op:=(request_value->>'operationId')::uuid;reason_value:=request_value->>'reason';
 if not pg_try_advisory_xact_lock(hashtextextended(a::text||':'||op::text,0))then return jsonb_build_object('status','retry_exact','code','operation_busy');end if;
 if not pg_try_advisory_xact_lock(hashtextextended('event-lifecycle:'||eid::text,0))then return jsonb_build_object('status','retry_exact','code','event_busy');end if;
 perform 1 from app.tournaments where id=tid for update nowait;if not found then return jsonb_build_object('status','rejected','code','tournament_unavailable');end if;
 perform 1 from app.tournament_roles where tournament_id=tid and profile_id=a and role in('director','co_director')order by role for key share nowait;
 if not found then return jsonb_build_object('status','rejected','code','not_director');end if;
 request_hash:=encode(extensions.digest(convert_to(jsonb_build_array('native-playoff-finance-write-v1',a,tid,eid,op,request_value)::text,'utf8'),'sha256'),'hex');
 select*into prior_op from app.native_playoff_finance_write_operations_v1 where actor_id=a and operation_id=op;
 if found then
  if prior_op.tournament_id<>tid or prior_op.event_id<>eid or prior_op.request_hash<>request_hash or prior_op.request_payload<>request_value then return jsonb_build_object('status','rejected','code','idempotency_conflict');end if;
  select result into prior_result from app.native_playoff_finance_write_outcomes_v1 where actor_id=a and operation_id=op;
  if prior_result is null then return jsonb_build_object('status','retry_exact','code','operation_incomplete');end if;
  return prior_result||jsonb_build_object('historicalReceipt',true,'currentSourceVerified',false);
 end if;
 if app.native_playoff_final_awards_enabled_v1()is distinct from true then return jsonb_build_object('status','rejected','code','feature_unavailable');end if;
 if exists(select 1 from app.native_playoff_final_award_sets_v1 where tournament_id=tid and event_id=eid)then
  return jsonb_build_object('status','rejected','code','final_awards_already_recorded');end if;
 legacy_exists:=app.legacy_financial_liability_exists_v1(tid,eid);
 if legacy_exists is distinct from false then return jsonb_build_object('status','rejected','code','legacy_financial_liability_exists');end if;
 source_value:=app.native_playoff_final_award_source_v1(tid,eid,a);
 if source_value->>'status'='retry_exact'then return source_value;end if;
 if source_value->>'status'<>'source_available'then return jsonb_build_object('status','rejected','code',coalesce(source_value->>'code','source_unavailable'));end if;
 if request_value->>'expectedSourceDigest'is distinct from source_value->>'sourceDigest'
  or request_value->>'expectedRecipientSourceDigest'is distinct from source_value->>'recipientSourceDigest'
  or request_value->>'expectedFundSourceDigest'is distinct from source_value->>'fundSourceDigest'
  or request_value->>'expectedProposalRevisionId'is distinct from source_value#>>'{proposal,revisionId}'
  or request_value->>'expectedFundReviewId'is distinct from source_value#>>'{income,reviewId}'then
  return jsonb_build_object('status','rejected','code','source_changed');end if;
 insert into app.native_playoff_finance_write_operations_v1(actor_id,operation_id,tournament_id,event_id,request_payload,request_hash)
  values(a,op,tid,eid,request_value,request_hash);
 insert into app.native_playoff_final_award_sets_v1(tournament_id,event_id,version,proposal_revision_id,fund_review_id,
  qualification_result_version_id,recipient_source_digest,fund_source_digest,source_digest,source_capture,total_minor,
  recipient_count,reason,recorded_by,actor_id,operation_id)
 values(tid,eid,1,(source_value#>>'{proposal,revisionId}')::uuid,(source_value#>>'{income,reviewId}')::uuid,
  (source_value#>>'{proposal,qualificationResultVersionId}')::uuid,source_value->>'recipientSourceDigest',source_value->>'fundSourceDigest',
  source_value->>'sourceDigest',source_value,(source_value#>>'{projection,totalMinor}')::bigint,
  jsonb_array_length(source_value#>'{projection,recipients}'),reason_value,a,a,op)returning id into award_id;
 for group_value in select value from jsonb_array_elements(source_value#>'{projection,groups}')loop
  insert into app.native_playoff_final_award_groups_v1(award_set_id,tournament_id,event_id,first_place,last_place,people,included,per_person_minor,group_total_minor)
  values(award_id,tid,eid,(group_value->>'firstPlace')::integer,(group_value->>'lastPlace')::integer,(group_value->>'people')::integer,
   (group_value->>'included')::boolean,(group_value->>'perPersonMinor')::bigint,(group_value->>'groupTotalMinor')::bigint);
 end loop;
 for recipient_value in select value from jsonb_array_elements(source_value#>'{projection,recipients}')loop
  insert into app.native_playoff_final_award_recipients_v1(award_set_id,tournament_id,event_id,participant_id,profile_id,
   tournament_player_id,display_name,first_place,last_place,included,amount_minor)
  values(award_id,tid,eid,(recipient_value->>'participantId')::uuid,(recipient_value->>'profileId')::uuid,
   recipient_value->>'tournamentPlayerId',recipient_value->>'displayName',(recipient_value->>'firstPlace')::integer,
   (recipient_value->>'lastPlace')::integer,(recipient_value->>'included')::boolean,(recipient_value->>'amountMinor')::bigint);
 end loop;
 response:=jsonb_build_object('status','accepted','code','native_playoff_final_awards_recorded_v1','awardSetId',award_id,
  'version',1,'sourceDigest',source_value->>'sourceDigest','totalMinor',(source_value#>>'{projection,totalMinor}')::bigint,
  'recipientCount',jsonb_array_length(source_value#>'{projection,recipients}'),'awardStatus','recorded_unpaid');
 return app.finish_native_playoff_finance_write_v1(a,tid,eid,op,response);
exception when lock_not_available then return jsonb_build_object('status','retry_exact','code','source_busy');
 when invalid_text_representation or numeric_value_out_of_range then return jsonb_build_object('status','rejected','code','invalid_request');
end$$;

create function app.get_native_playoff_final_award_record_v1(tid uuid,eid uuid)returns jsonb
language plpgsql security definer set search_path=''as $$
declare a uuid:=auth.uid();award app.native_playoff_final_award_sets_v1%rowtype;groups jsonb;recipients jsonb;begin
 if a is null then return null;end if;
 if current_setting('transaction_isolation')<>'read committed'then return null;end if;
 perform 1 from app.tournaments where id=tid for share nowait;if not found then return null;end if;
 perform 1 from app.tournament_roles where tournament_id=tid and profile_id=a and role in('director','co_director')order by role for key share nowait;
 if not found then return null;end if;
 select*into award from app.native_playoff_final_award_sets_v1 where tournament_id=tid and event_id=eid;
 if not found then return null;end if;
 select coalesce(jsonb_agg(jsonb_build_object('firstPlace',first_place,'lastPlace',last_place,'people',people,'included',included,
  'perPersonMinor',per_person_minor,'groupTotalMinor',group_total_minor)order by first_place),'[]')into groups
 from app.native_playoff_final_award_groups_v1 where award_set_id=award.id;
 select coalesce(jsonb_agg(jsonb_build_object('participantId',participant_id,'profileId',profile_id,'displayName',display_name,
  'tournamentPlayerId',tournament_player_id,'firstPlace',first_place,'lastPlace',last_place,'included',included,
  'amountMinor',amount_minor)order by first_place,participant_id),'[]')into recipients
 from app.native_playoff_final_award_recipients_v1 where award_set_id=award.id;
 return jsonb_build_object('status','recorded','kind','native-playoff-final-award-record-v1','tournamentId',tid,'eventId',eid,
  'awardSetId',award.id,'version',award.version,'proposalRevisionId',award.proposal_revision_id,'fundReviewId',award.fund_review_id,
  'qualificationResultVersionId',award.qualification_result_version_id,'recipientSourceDigest',award.recipient_source_digest,
  'fundSourceDigest',award.fund_source_digest,'sourceDigest',award.source_digest,'sourceCapture',award.source_capture,
  'groups',groups,'recipients',recipients,'totalMinor',award.total_minor,'recipientCount',award.recipient_count,
  'reason',award.reason,'recordedBy',award.recorded_by,'recordedAt',award.recorded_at,'awardStatus',award.award_status,
  'historicalReceipt',true,'currentSourceVerified',false,'moneyMoved',false,'payoutAuthorized',false,
  'disbursementAuthorized',false,'finalizationAuthorized',false);
exception when lock_not_available then return null;end$$;

create function app.get_native_playoff_finance_write_reconciliation_v1(tid uuid,eid uuid,op uuid)returns jsonb
language plpgsql security definer set search_path=''as $$
declare a uuid:=auth.uid();result jsonb;begin
 if a is null then return null;end if;
 if current_setting('transaction_isolation')<>'read committed'then return null;end if;
 perform 1 from app.tournaments where id=tid for share nowait;if not found then return null;end if;
 perform 1 from app.tournament_roles where tournament_id=tid and profile_id=a and role in('director','co_director')order by role for key share nowait;
 if not found then return null;end if;
 if not pg_try_advisory_xact_lock(hashtextextended(a::text||':'||op::text,0))then return jsonb_build_object('authorized',true,'result',jsonb_build_object('status','retry_exact','code','operation_busy'));end if;
 select o.result into result from app.native_playoff_finance_write_outcomes_v1 o
  where o.actor_id=a and o.operation_id=op and o.tournament_id=tid and o.event_id=eid;
 return jsonb_build_object('authorized',true,'result',case when result is null then null else result||jsonb_build_object('historicalReceipt',true,'currentSourceVerified',false)end);
exception when lock_not_available then return null;end$$;

-- Bind the immutable Start-time assessment to one current recorded expense
-- event and to the exact same-event, reviewed native allocation parts. The
-- expense remains part of the ordinary native expense total; callers must not
-- subtract this assessment a second time.
create function app.native_sanctioning_coverage_v1(
 tid uuid,eid uuid,recipient jsonb,expense_event_id uuid
)returns jsonb
language plpgsql security definer set search_path=''as $$
declare snapshot app.event_sanctioning_fee_snapshots%rowtype;
 start_row app.event_play_starts%rowtype;expense_row app.tournament_expense_events%rowtype;
 source_row jsonb;part jsonb;allocated numeric:=0;found_source boolean:=false;
begin
 lock table app.event_play_starts,app.event_sanctioning_fee_snapshots,
  app.tournament_expense_events in share mode nowait;
 select*into start_row from app.event_play_starts where tournament_id=tid and event_id=eid;
 select*into snapshot from app.event_sanctioning_fee_snapshots where tournament_id=tid and event_id=eid;
 if start_row.id is null or snapshot.id is null
  or snapshot.event_play_start_id<>start_row.id
  or snapshot.eligible_participant_count<>start_row.participant_count
  or not exists(select 1 from app.events current_event where current_event.id=eid
   and current_event.tournament_id=tid and current_event.event_type=snapshot.event_kind)
  or snapshot.rate_cents::numeric*snapshot.eligible_participant_count::numeric<>snapshot.total_cents::numeric then
  return jsonb_build_object('status','blocked','code','sanctioning_coverage_unverified');
 end if;
 if snapshot.total_cents=0 then
  if expense_event_id is not null then
   return jsonb_build_object('status','blocked','code','sanctioning_expense_unexpected');
  end if;
  return jsonb_build_object('status','available','snapshotId',snapshot.id,
   'eventPlayStartId',start_row.id,'rateMinor',snapshot.rate_cents,
   'eligibleParticipantCount',snapshot.eligible_participant_count,'totalMinor',snapshot.total_cents,
   'expenseSourceId',null,'allocatedExpenseMinor',0);
 end if;
 if expense_event_id is null then
  return jsonb_build_object('status','blocked','code','sanctioning_coverage_unverified');
 end if;
 select*into expense_row from app.tournament_expense_events current_expense
  where current_expense.id=expense_event_id and current_expense.tournament_id=tid
   and current_expense.event_type='recorded'
   and not exists(select 1 from app.tournament_expense_events newer
    where newer.expense_id=current_expense.expense_id and newer.version>current_expense.version);
 if expense_row.id is null then
  return jsonb_build_object('status','blocked','code','sanctioning_coverage_unverified');
 end if;
 for source_row in select value from jsonb_array_elements(recipient#>'{nativeFinanceSource,raw,allocation,eventSources}')loop
  if source_row->>'sourceId'=expense_event_id::text then
   if found_source or source_row->>'kind'<>'expense'or source_row->>'state'<>'active'
    or source_row->>'physicalEvidenceId'is distinct from expense_event_id::text then
    return jsonb_build_object('status','blocked','code','sanctioning_coverage_unverified');
   end if;
   found_source:=true;
   for part in select value from jsonb_array_elements(source_row->'allocations')loop
    if part->>'eventId'=eid::text and part->>'bucket'in('player_benefit','operating_expense')then
     if part->>'classificationReviewed'is distinct from'true'
      or part->'poolId'is distinct from'null'::jsonb then
      return jsonb_build_object('status','blocked','code','sanctioning_coverage_unverified');
     end if;
     allocated:=allocated+(part->>'amountMinor')::numeric;
    end if;
   end loop;
  end if;
 end loop;
 if not found_source or allocated<snapshot.total_cents or allocated>9007199254740991 then
  return jsonb_build_object('status','blocked','code','sanctioning_coverage_unverified');
 end if;
 if exists(select 1 from app.native_recorded_fund_reviews_v1 prior_review
   where prior_review.tournament_id=tid and prior_review.event_id<>eid
    and prior_review.sanctioning_expense_event_id=expense_event_id)
  or exists(select 1 from app.event_settlement_finals_v2 legacy_final
   join app.event_settlement_drafts_v5 legacy_draft on legacy_draft.id=legacy_final.draft_id
   where legacy_final.tournament_id=tid
    and legacy_draft.sanctioning_expense_event_id=expense_event_id)then
  return jsonb_build_object('status','blocked','code','sanctioning_expense_reused');
 end if;
 return jsonb_build_object('status','available','snapshotId',snapshot.id,
  'eventPlayStartId',start_row.id,'rateMinor',snapshot.rate_cents,
  'eligibleParticipantCount',snapshot.eligible_participant_count,'totalMinor',snapshot.total_cents,
  'expenseSourceId',expense_event_id,'allocatedExpenseMinor',allocated::bigint);
exception when lock_not_available then return jsonb_build_object('status','retry_exact','code','source_busy');
 when invalid_text_representation or numeric_value_out_of_range then
  return jsonb_build_object('status','blocked','code','sanctioning_coverage_unverified');
end$$;


create function app.review_native_recorded_fund_v1(
 tid uuid,eid uuid,request_value jsonb
)returns jsonb
language plpgsql security definer set search_path=''as $$
declare a uuid:=auth.uid();op uuid;expected integer;request_hash text;prior_op app.native_playoff_finance_write_operations_v1%rowtype;
 prior_result jsonb;recipient jsonb;proposal app.operational_event_finance_revisions_v1%rowtype;
 prior_review app.native_recorded_fund_reviews_v1%rowtype;record_row app.native_unrestricted_income_records_v1%rowtype;
 income_records jsonb:='[]';income_lines jsonb:='[]';income_latest jsonb:='{}';income_item jsonb;line_item jsonb;
 income_digest text;income_head integer:=0;active_income numeric:=0;
 review_id uuid;review_version integer;review_status text;reason_value text;source_capture jsonb;source_digest text;response jsonb;i integer;
 sanctioning_expense uuid;sanctioning jsonb;
begin
 if a is null then return jsonb_build_object('status','rejected','code','authentication_required');end if;
 if current_setting('transaction_isolation')<>'read committed'then return jsonb_build_object('status','retry_exact','code','isolation_not_supported');end if;
 if jsonb_typeof(request_value)is distinct from'object'or(select count(*)from jsonb_object_keys(request_value))<>10
  or not(request_value?&array['kind','operationId','expectedVersion','proposalRevisionId','nativeAllocationRevisionId','incomeHeadVersion','incomeHeadDigest','status','sanctioningExpenseEventId','reason'])
  or request_value->>'kind'is distinct from'native-recorded-fund-review-v1'
  or coalesce(request_value->>'operationId','')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
  or coalesce(request_value->>'proposalRevisionId','')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
  or coalesce(request_value->>'nativeAllocationRevisionId','')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
  or jsonb_typeof(request_value->'expectedVersion')is distinct from'number'or(request_value->>'expectedVersion')!~'^(0|[1-9][0-9]*)$'
  or(request_value->>'expectedVersion')::numeric>2147483646
  or jsonb_typeof(request_value->'incomeHeadVersion')is distinct from'number'or(request_value->>'incomeHeadVersion')!~'^(0|[1-9][0-9]*)$'
  or(request_value->>'incomeHeadVersion')::numeric>2147483647
  or coalesce(request_value->>'incomeHeadDigest','')!~'^[a-f0-9]{64}$'
  or jsonb_typeof(request_value->'status')is distinct from'string'
  or request_value->>'status'not in('reviewed_zero','recorded_complete')
  or(request_value->'sanctioningExpenseEventId'is distinct from'null'::jsonb
   and(jsonb_typeof(request_value->'sanctioningExpenseEventId')is distinct from'string'
    or coalesce(request_value->>'sanctioningExpenseEventId','')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'))
  or jsonb_typeof(request_value->'reason')is distinct from'string'
  or request_value->>'reason'<>app.custom_payout_classification_text_v2(request_value->>'reason')
  or app.event_settings_js_text_length_v3(request_value->>'reason')not between 1 and 2000 then
  return jsonb_build_object('status','rejected','code','invalid_request');end if;
 op:=(request_value->>'operationId')::uuid;expected:=(request_value->>'expectedVersion')::integer;
 sanctioning_expense:=case when request_value->'sanctioningExpenseEventId'='null'::jsonb then null
  else(request_value->>'sanctioningExpenseEventId')::uuid end;
 review_status:=request_value->>'status';reason_value:=request_value->>'reason';
 if not pg_try_advisory_xact_lock(hashtextextended(a::text||':'||op::text,0))then return jsonb_build_object('status','retry_exact','code','operation_busy');end if;
 if not pg_try_advisory_xact_lock(hashtextextended('event-lifecycle:'||eid::text,0))then return jsonb_build_object('status','retry_exact','code','event_busy');end if;
 perform 1 from app.tournaments where id=tid for update nowait;if not found then return jsonb_build_object('status','rejected','code','tournament_unavailable');end if;
 perform 1 from app.tournament_roles where tournament_id=tid and profile_id=a and role in('director','co_director')order by role for key share nowait;
 if not found then return jsonb_build_object('status','rejected','code','not_director');end if;
 request_hash:=encode(extensions.digest(convert_to(jsonb_build_array('native-playoff-finance-write-v1',a,tid,eid,op,request_value)::text,'utf8'),'sha256'),'hex');
 select*into prior_op from app.native_playoff_finance_write_operations_v1 where actor_id=a and operation_id=op;
 if found then
  if prior_op.tournament_id<>tid or prior_op.event_id<>eid or prior_op.request_hash<>request_hash or prior_op.request_payload<>request_value then return jsonb_build_object('status','rejected','code','idempotency_conflict');end if;
  select result into prior_result from app.native_playoff_finance_write_outcomes_v1 where actor_id=a and operation_id=op;
  if prior_result is null then return jsonb_build_object('status','retry_exact','code','operation_incomplete');end if;
  return prior_result||jsonb_build_object('historicalReceipt',true,'currentSourceVerified',false);
 end if;
 if app.native_playoff_final_awards_enabled_v1()is distinct from true then return jsonb_build_object('status','rejected','code','feature_unavailable');end if;
 if exists(select 1 from app.native_playoff_final_award_sets_v1 where tournament_id=tid and event_id=eid)then return jsonb_build_object('status','rejected','code','final_awards_already_recorded');end if;
 recipient:=app.get_native_playoff_finance_recipient_source_v1(tid,eid);
 if recipient->>'status'='retry_exact'then return recipient;end if;
 if recipient->>'status'<>'source_available'then return jsonb_build_object('status','rejected','code',coalesce(recipient->>'code','source_unavailable'));end if;
 select*into proposal from app.operational_event_finance_revisions_v1 where tournament_id=tid and event_id=eid order by version desc limit 1;
 if not found or proposal.id::text is distinct from request_value->>'proposalRevisionId'
  or proposal.id::text is distinct from recipient#>>'{proposal,revisionId}'
  or request_value->>'nativeAllocationRevisionId'is distinct from recipient#>>'{nativeFinanceSource,raw,allocation,revisionId}'then
  return jsonb_build_object('status','rejected','code','source_changed');end if;
 sanctioning:=app.native_sanctioning_coverage_v1(tid,eid,recipient,sanctioning_expense);
 if sanctioning->>'status'='retry_exact'then return sanctioning;end if;
 if sanctioning->>'status'<>'available'then
  return jsonb_build_object('status','rejected','code',coalesce(sanctioning->>'code','sanctioning_coverage_unverified'));end if;
 for i in jsonb_array_length(proposal.editor#>'{basis,history}')..jsonb_array_length(proposal.editor->'history')-1 loop
  line_item:=proposal.editor->'history'->i;
  if line_item#>>'{line,category}'is distinct from'unrestricted_income'then return jsonb_build_object('status','rejected','code','unrecorded_finance_edit');end if;
  income_lines:=income_lines||jsonb_build_array(line_item);
 end loop;
 select coalesce(max(version),0)into income_head from app.native_unrestricted_income_records_v1 where tournament_id=tid and event_id=eid;
 if income_head<>jsonb_array_length(income_lines)then return jsonb_build_object('status','rejected','code','income_history_incomplete');end if;
 for record_row in select*from app.native_unrestricted_income_records_v1 where tournament_id=tid and event_id=eid order by version loop
  line_item:=income_lines->(record_row.version-1);
  if line_item#>>'{line,lineId}'is distinct from record_row.income_id::text
   or line_item#>>'{line,recordId}'is distinct from record_row.record_id::text
   or line_item#>'{line,priorRecordId}'is distinct from coalesce(to_jsonb(record_row.prior_record_id),'null'::jsonb)
   or(line_item#>>'{line,amountMinor}')::numeric is distinct from record_row.amount_minor::numeric
   or(line_item#>>'{line,voided}')::boolean is distinct from record_row.voided
   or line_item->>'label'is distinct from record_row.label or line_item#>>'{line,reason}'is distinct from record_row.reason then
   return jsonb_build_object('status','rejected','code','income_history_changed');end if;
  income_records:=income_records||jsonb_build_array(jsonb_build_object('incomeId',record_row.income_id,'recordId',record_row.record_id,
   'priorRecordId',record_row.prior_record_id,'physicalEvidenceId',record_row.physical_evidence_id,'amountMinor',record_row.amount_minor,
   'voided',record_row.voided,'label',record_row.label,'evidenceReference',record_row.evidence_reference,'reason',record_row.reason,
   'recordedBy',record_row.recorded_by,'recordedAt',record_row.recorded_at));
  income_latest:=jsonb_set(income_latest,array[record_row.income_id::text],jsonb_build_object(
   'voided',record_row.voided,'amountMinor',record_row.amount_minor),true);
 end loop;
 for income_item in select value from jsonb_each(income_latest)loop
  if not(income_item->>'voided')::boolean then active_income:=active_income+(income_item->>'amountMinor')::numeric;end if;
 end loop;
 lock table app.roster_payment_events,app.tournament_expense_events in share mode nowait;
 if exists(select 1 from app.native_unrestricted_income_records_v1 ir
   join app.roster_payment_events p on p.tournament_id=ir.tournament_id and p.id=ir.physical_evidence_id
   where ir.tournament_id=tid)
  or exists(select 1 from app.native_unrestricted_income_records_v1 ir
   join app.tournament_expense_events x on x.tournament_id=ir.tournament_id and x.id=ir.physical_evidence_id
   where ir.tournament_id=tid)then
  return jsonb_build_object('status','rejected','code','physical_evidence_conflict');
 end if;
 income_digest:=encode(extensions.digest(convert_to(jsonb_build_array('native-unrestricted-income-head-v1',tid,eid,income_records)::text,'utf8'),'sha256'),'hex');
 if(request_value->>'incomeHeadVersion')::integer<>income_head or request_value->>'incomeHeadDigest'<>income_digest
  or(review_status='reviewed_zero'and active_income<>0)or(review_status='recorded_complete'and active_income=0)then
  return jsonb_build_object('status','rejected','code','income_head_changed');end if;
 select*into prior_review from app.native_recorded_fund_reviews_v1 where tournament_id=tid and event_id=eid order by version desc limit 1;
 if coalesce(prior_review.version,0)<>expected then return jsonb_build_object('status','rejected','code','stale_version');end if;
 insert into app.native_playoff_finance_write_operations_v1(actor_id,operation_id,tournament_id,event_id,request_payload,request_hash)
  values(a,op,tid,eid,request_value,request_hash);
 source_capture:=jsonb_build_object('recipientSourceDigest',recipient->>'sourceDigest','proposalRevisionId',proposal.id,
  'nativeAllocationRevisionId',(request_value->>'nativeAllocationRevisionId')::uuid,'incomeHeadVersion',income_head,
   'incomeHeadDigest',income_digest,'incomeRecords',income_records,'reviewStatus',review_status,
   'sanctioning',sanctioning-'status','reviewReason',reason_value);
 source_digest:=encode(extensions.digest(convert_to(jsonb_build_array('native-recorded-fund-review-v1',source_capture)::text,'utf8'),'sha256'),'hex');
  insert into app.native_recorded_fund_reviews_v1(tournament_id,event_id,version,prior_review_id,proposal_revision_id,
   native_allocation_revision_id,sanctioning_fee_snapshot_id,sanctioning_expense_event_id,sanctioning_allocated_minor,
   income_head_version,income_head_digest,review_status,source_capture,source_digest,reason,
  reviewed_by,actor_id,operation_id)
  values(tid,eid,expected+1,prior_review.id,proposal.id,(request_value->>'nativeAllocationRevisionId')::uuid,
   (sanctioning->>'snapshotId')::uuid,sanctioning_expense,(sanctioning->>'allocatedExpenseMinor')::bigint,income_head,income_digest,
  review_status,source_capture,source_digest,reason_value,a,a,op)returning id,version into review_id,review_version;
 response:=jsonb_build_object('status','accepted','code','native_recorded_fund_reviewed_v1','reviewId',review_id,
  'version',review_version,'reviewStatus',review_status,'sourceDigest',source_digest,'recordedFundAvailable',true,
  'bankReceiptVerified',false,'reviewedBy',a,'reviewedAt',(select reviewed_at from app.native_recorded_fund_reviews_v1 where id=review_id));
 return app.finish_native_playoff_finance_write_v1(a,tid,eid,op,response);
exception when lock_not_available then return jsonb_build_object('status','retry_exact','code','source_busy');
 when invalid_text_representation or numeric_value_out_of_range then return jsonb_build_object('status','rejected','code','invalid_request');
end$$;


create function app.record_native_unrestricted_income_v1(
 tid uuid,eid uuid,request_value jsonb
)returns jsonb
language plpgsql security definer set search_path=''as $$
declare a uuid:=auth.uid();op uuid;expected integer;request_hash text;prior_op app.native_playoff_finance_write_operations_v1%rowtype;
 prior_result jsonb;proposal app.operational_event_finance_revisions_v1%rowtype;recipient jsonb;
 target jsonb;line_value jsonb;requested_record_id uuid;requested_income_id uuid;requested_prior_record uuid;requested_physical_id uuid;
 source_owner app.native_unrestricted_income_sources_v1%rowtype;head app.native_unrestricted_income_records_v1%rowtype;
 record_version integer;record_pk uuid;source_digest text;response jsonb;
begin
 if a is null then return jsonb_build_object('status','rejected','code','authentication_required');end if;
 if current_setting('transaction_isolation')<>'read committed'then return jsonb_build_object('status','retry_exact','code','isolation_not_supported');end if;
 if jsonb_typeof(request_value)is distinct from'object'or(select count(*)from jsonb_object_keys(request_value))<>7
  or not(request_value?&array['kind','operationId','expectedVersion','proposalRevisionId','recordId','physicalEvidenceId','evidenceReference'])
  or request_value->>'kind'is distinct from'native-unrestricted-income-record-v1'
  or coalesce(request_value->>'operationId','')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
  or coalesce(request_value->>'proposalRevisionId','')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
  or coalesce(request_value->>'recordId','')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
  or coalesce(request_value->>'physicalEvidenceId','')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
  or jsonb_typeof(request_value->'expectedVersion')is distinct from'number'
  or(request_value->>'expectedVersion')!~'^(0|[1-9][0-9]*)$'
  or(request_value->>'expectedVersion')::numeric>2147483646
  or jsonb_typeof(request_value->'evidenceReference')is distinct from'string'
  or request_value->>'evidenceReference'<>app.custom_payout_classification_text_v2(request_value->>'evidenceReference')
  or app.event_settings_js_text_length_v3(request_value->>'evidenceReference')not between 1 and 2000 then
  return jsonb_build_object('status','rejected','code','invalid_request');end if;
 op:=(request_value->>'operationId')::uuid;expected:=(request_value->>'expectedVersion')::integer;
 requested_record_id:=(request_value->>'recordId')::uuid;requested_physical_id:=(request_value->>'physicalEvidenceId')::uuid;
 if not pg_try_advisory_xact_lock(hashtextextended(a::text||':'||op::text,0))then return jsonb_build_object('status','retry_exact','code','operation_busy');end if;
 if not pg_try_advisory_xact_lock(hashtextextended('event-lifecycle:'||eid::text,0))then return jsonb_build_object('status','retry_exact','code','event_busy');end if;
 perform 1 from app.tournaments where id=tid for update nowait;if not found then return jsonb_build_object('status','rejected','code','tournament_unavailable');end if;
 perform 1 from app.tournament_roles where tournament_id=tid and profile_id=a and role in('director','co_director')order by role for key share nowait;
 if not found then return jsonb_build_object('status','rejected','code','not_director');end if;
 request_hash:=encode(extensions.digest(convert_to(jsonb_build_array('native-playoff-finance-write-v1',a,tid,eid,op,request_value)::text,'utf8'),'sha256'),'hex');
 select*into prior_op from app.native_playoff_finance_write_operations_v1 where actor_id=a and operation_id=op;
 if found then
  if prior_op.tournament_id<>tid or prior_op.event_id<>eid or prior_op.request_hash<>request_hash or prior_op.request_payload<>request_value then
   return jsonb_build_object('status','rejected','code','idempotency_conflict');end if;
  select result into prior_result from app.native_playoff_finance_write_outcomes_v1 where actor_id=a and operation_id=op;
  if prior_result is null then return jsonb_build_object('status','retry_exact','code','operation_incomplete');end if;
  return prior_result||jsonb_build_object('historicalReceipt',true,'currentSourceVerified',false);
 end if;
 if app.native_playoff_final_awards_enabled_v1()is distinct from true then return jsonb_build_object('status','rejected','code','feature_unavailable');end if;
 if exists(select 1 from app.native_playoff_final_award_sets_v1 where tournament_id=tid and event_id=eid)then
  return jsonb_build_object('status','rejected','code','final_awards_already_recorded');end if;
 recipient:=app.get_native_playoff_finance_recipient_source_v1(tid,eid);
 if recipient->>'status'='retry_exact'then return recipient;end if;
 if recipient->>'status'<>'source_available'then return jsonb_build_object('status','rejected','code',coalesce(recipient->>'code','source_unavailable'));end if;
 select*into proposal from app.operational_event_finance_revisions_v1 where tournament_id=tid and event_id=eid order by version desc limit 1;
 if not found or proposal.id::text is distinct from request_value->>'proposalRevisionId'
  or proposal.id::text is distinct from recipient#>>'{proposal,revisionId}'then return jsonb_build_object('status','rejected','code','proposal_source_changed');end if;
 select value into target from jsonb_array_elements(proposal.editor->'history')where value#>>'{line,recordId}'=requested_record_id::text;
 if target is null or target#>>'{line,category}'is distinct from'unrestricted_income'
  or target#>>'{line,mode}'is distinct from'estimate'or target#>'{line,source}'is distinct from proposal.editor#>'{basis,source}'then
  return jsonb_build_object('status','rejected','code','income_record_unavailable');end if;
 line_value:=target->'line';requested_income_id:=(line_value->>'lineId')::uuid;
 requested_prior_record:=case when line_value->'priorRecordId'='null'::jsonb then null else(line_value->>'priorRecordId')::uuid end;
 -- Reserve all native source histories before collision checks. This includes
 -- voided/corrected receipt and expense rows across every event in tournament.
 lock table app.roster_payment_events,app.tournament_expense_events in share mode nowait;
 if exists(select 1 from app.roster_payment_events p where p.tournament_id=tid and p.id=requested_physical_id)
  or exists(select 1 from app.tournament_expense_events x where x.tournament_id=tid and x.id=requested_physical_id)then
  return jsonb_build_object('status','rejected','code','physical_evidence_conflict');end if;
 select*into source_owner from app.native_unrestricted_income_sources_v1 s where s.tournament_id=tid and s.income_id=requested_income_id for update;
 if not found then
  if requested_prior_record is not null then return jsonb_build_object('status','rejected','code','income_lineage_invalid');end if;
  if exists(select 1 from app.native_unrestricted_income_sources_v1 s where s.tournament_id=tid
    and(s.physical_evidence_id=requested_physical_id or lower(s.evidence_reference)=lower(request_value->>'evidenceReference')))then
   return jsonb_build_object('status','rejected','code','physical_evidence_conflict');end if;
  -- Insert is delayed until every remaining rejectable preflight below passes.
 else
  if source_owner.event_id<>eid or source_owner.physical_evidence_id<>requested_physical_id
   or lower(source_owner.evidence_reference)<>lower(request_value->>'evidenceReference')then
   return jsonb_build_object('status','rejected','code','physical_evidence_conflict');end if;
 end if;
 select*into head from app.native_unrestricted_income_records_v1 where tournament_id=tid and event_id=eid order by version desc limit 1;
 if coalesce(head.version,0)<>expected then return jsonb_build_object('status','rejected','code','stale_version');end if;
 if exists(select 1 from app.native_unrestricted_income_records_v1 r where r.tournament_id=tid and r.event_id=eid and r.record_id=requested_record_id)then
  return jsonb_build_object('status','rejected','code','income_record_conflict');end if;
 if requested_prior_record is null then
  if exists(select 1 from app.native_unrestricted_income_records_v1 r where r.tournament_id=tid and r.income_id=requested_income_id)then
   return jsonb_build_object('status','rejected','code','income_lineage_invalid');end if;
 else
  perform 1 from app.native_unrestricted_income_records_v1 own where own.tournament_id=tid and own.income_id=requested_income_id
   and own.record_id=requested_prior_record and own.record_id=(select r.record_id from app.native_unrestricted_income_records_v1 r
    where r.tournament_id=tid and r.income_id=requested_income_id order by r.version desc limit 1);
  if not found then return jsonb_build_object('status','rejected','code','income_lineage_invalid');end if;
 end if;
 if source_owner.income_id is null then
  insert into app.native_unrestricted_income_sources_v1(tournament_id,event_id,income_id,physical_evidence_id,evidence_reference,created_by)
   values(tid,eid,requested_income_id,requested_physical_id,request_value->>'evidenceReference',a);
 end if;
 insert into app.native_playoff_finance_write_operations_v1(actor_id,operation_id,tournament_id,event_id,request_payload,request_hash)
  values(a,op,tid,eid,request_value,request_hash);
 source_digest:=encode(extensions.digest(convert_to(jsonb_build_array('native-unrestricted-income-record-v1',recipient->>'sourceDigest',proposal.id,
  target,requested_physical_id,request_value->>'evidenceReference')::text,'utf8'),'sha256'),'hex');
 insert into app.native_unrestricted_income_records_v1(tournament_id,event_id,version,income_id,record_id,prior_record_id,
  physical_evidence_id,evidence_reference,proposal_revision_id,amount_minor,voided,label,reason,recorded_by,actor_id,operation_id,source_capture,source_digest)
 values(tid,eid,expected+1,requested_income_id,requested_record_id,requested_prior_record,requested_physical_id,request_value->>'evidenceReference',proposal.id,
  (line_value->>'amountMinor')::bigint,(line_value->>'voided')::boolean,target->>'label',line_value->>'reason',a,a,op,
  jsonb_build_object('recipientSourceDigest',recipient->>'sourceDigest','proposalRevisionId',proposal.id,'proposalLine',target),source_digest)
 returning id,version into record_pk,record_version;
 response:=jsonb_build_object('status','accepted','code','native_unrestricted_income_recorded_v1','incomeRecordId',record_pk,
  'incomeId',requested_income_id,'version',record_version,'proposalRevisionId',proposal.id,'recordedBookkeepingOnly',true,
  'bankReceiptVerified',false,'coverageGuarantee','all_native_receipt_expense_history_reserved');
 return app.finish_native_playoff_finance_write_v1(a,tid,eid,op,response);
exception when lock_not_available then return jsonb_build_object('status','retry_exact','code','source_busy');
 when invalid_text_representation or numeric_value_out_of_range then return jsonb_build_object('status','rejected','code','invalid_request');
end$$;


-- Rebuild the current immutable source. All amounts are derived from current
-- native allocation rows, recorded bookkeeping rows and the current proposal;
-- no posted amount or recipient is trusted.
create function app.native_playoff_final_award_source_v1(
 tid uuid,eid uuid,actor uuid
)returns jsonb
language plpgsql security definer set search_path=''as $$
declare
 recipient jsonb;proposal app.operational_event_finance_revisions_v1%rowtype;
 review app.native_recorded_fund_reviews_v1%rowtype;final_row app.native_playoff_final_award_sets_v1%rowtype;
 editor jsonb;basis_history jsonb;history jsonb;line_item jsonb;record_row app.native_unrestricted_income_records_v1%rowtype;
 income_records jsonb:='[]';income_lines jsonb:='[]';income_latest jsonb:='{}';income_item jsonb;
 income_head integer:=0;income_total numeric:=0;income_head_digest text;
 regular_total numeric:=0;benefit_total numeric:=0;operating_total numeric:=0;fund_total numeric;
 source_row jsonb;part jsonb;allocation_id uuid;recipient_digest text;fund_source_digest text;
 settings jsonb;method text;factor_text text;factor_num numeric;factor_den numeric;dot_at integer;
 qualifier_count integer;requested integer;included_places integer;first_place integer;last_place integer;
 band_count integer:=0;all_band_count integer:=0;i integer;people integer;weight numeric;denominator numeric:=0;raw numeric;amount numeric;previous_amount numeric:=null;
 bands jsonb:='[]';groups jsonb:='[]';recipients jsonb:='[]';override_latest jsonb:='{}';ov jsonb;
 player jsonb;match_row jsonb;participant uuid;place_first integer;place_last integer;included boolean;
 final_winner uuid;final_loser uuid;loser uuid;total_awards numeric:=0;positive_places integer:=0;
 capture jsonb;source_digest text;existing_final jsonb;sanctioning jsonb;
begin
 if current_setting('transaction_isolation')<>'read committed'then
  return jsonb_build_object('status','retry_exact','code','isolation_not_supported');
 end if;
 if app.native_playoff_final_awards_enabled_v1()is distinct from true then
  return jsonb_build_object('status','blocked','code','feature_unavailable');
 end if;
 recipient:=app.get_native_playoff_finance_recipient_source_v1(tid,eid);
 if recipient->>'status'='retry_exact'then return recipient;end if;
 if recipient->>'status'<>'source_available'then
  return jsonb_build_object('status','blocked','code',coalesce(recipient->>'code','recipient_source_unavailable'));
 end if;
 if recipient->>'actorId'is distinct from actor::text then
  return jsonb_build_object('status','blocked','code','actor_source_mismatch');
 end if;
 recipient_digest:=recipient->>'sourceDigest';
 select*into proposal from app.operational_event_finance_revisions_v1
  where tournament_id=tid and event_id=eid order by version desc limit 1;
 if not found or proposal.id::text is distinct from recipient#>>'{proposal,revisionId}'then
  return jsonb_build_object('status','blocked','code','proposal_source_changed');
 end if;
 editor:=proposal.editor;basis_history:=editor#>'{basis,history}';history:=editor->'history';
 if editor->'lineForm'<>'null'::jsonb or editor->'bandForm'<>'null'::jsonb then
  return jsonb_build_object('status','blocked','code','unfinished_proposal_form');
 end if;
 if jsonb_typeof(basis_history)is distinct from'array'or jsonb_typeof(history)is distinct from'array'
  or jsonb_array_length(history)<jsonb_array_length(basis_history)then
  return jsonb_build_object('status','blocked','code','proposal_history_invalid');
 end if;
 for i in 0..jsonb_array_length(basis_history)-1 loop
  if history->i is distinct from basis_history->i then
   return jsonb_build_object('status','blocked','code','native_history_changed');
  end if;
 end loop;
 for i in jsonb_array_length(basis_history)..jsonb_array_length(history)-1 loop
  line_item:=history->i;
  if line_item#>>'{line,category}'is distinct from'unrestricted_income'
   or line_item#>>'{line,mode}'is distinct from'estimate'
   or line_item#>'{line,source}'is distinct from editor#>'{basis,source}'then
   return jsonb_build_object('status','blocked','code','unrecorded_finance_edit');
  end if;
  income_lines:=income_lines||jsonb_build_array(line_item);
 end loop;
 select coalesce(max(version),0)into income_head from app.native_unrestricted_income_records_v1
  where tournament_id=tid and event_id=eid;
 if income_head<>jsonb_array_length(income_lines)then
  return jsonb_build_object('status','blocked','code','income_history_incomplete');
 end if;
 for record_row in select*from app.native_unrestricted_income_records_v1
  where tournament_id=tid and event_id=eid order by version loop
  line_item:=income_lines->(record_row.version-1);
  if line_item#>>'{line,lineId}'is distinct from record_row.income_id::text
   or line_item#>>'{line,recordId}'is distinct from record_row.record_id::text
   or line_item#>'{line,priorRecordId}'is distinct from coalesce(to_jsonb(record_row.prior_record_id),'null'::jsonb)
   or(line_item#>>'{line,amountMinor}')::numeric is distinct from record_row.amount_minor::numeric
   or(line_item#>>'{line,voided}')::boolean is distinct from record_row.voided
   or line_item->>'label'is distinct from record_row.label
   or line_item#>>'{line,reason}'is distinct from record_row.reason then
   return jsonb_build_object('status','blocked','code','income_history_changed');
  end if;
  income_item:=jsonb_build_object(
   'incomeId',record_row.income_id,'recordId',record_row.record_id,
   'priorRecordId',record_row.prior_record_id,'physicalEvidenceId',record_row.physical_evidence_id,
   'amountMinor',record_row.amount_minor,'voided',record_row.voided,'label',record_row.label,
   'evidenceReference',record_row.evidence_reference,'reason',record_row.reason,
   'recordedBy',record_row.recorded_by,'recordedAt',record_row.recorded_at
  );
  income_records:=income_records||jsonb_build_array(income_item);
  income_latest:=jsonb_set(income_latest,array[record_row.income_id::text],income_item,true);
 end loop;
 for income_item in select value from jsonb_each(income_latest)loop
  if not(income_item->>'voided')::boolean then income_total:=income_total+(income_item->>'amountMinor')::numeric;end if;
 end loop;
 if exists(select 1 from app.native_unrestricted_income_records_v1 ir
   join app.roster_payment_events p on p.tournament_id=ir.tournament_id and p.id=ir.physical_evidence_id
   where ir.tournament_id=tid)
  or exists(select 1 from app.native_unrestricted_income_records_v1 ir
   join app.tournament_expense_events x on x.tournament_id=ir.tournament_id and x.id=ir.physical_evidence_id
   where ir.tournament_id=tid)then
  return jsonb_build_object('status','blocked','code','physical_evidence_conflict');
 end if;
 income_head_digest:=encode(extensions.digest(convert_to(jsonb_build_array(
  'native-unrestricted-income-head-v1',tid,eid,income_records
 )::text,'utf8'),'sha256'),'hex');
 select*into review from app.native_recorded_fund_reviews_v1
  where tournament_id=tid and event_id=eid order by version desc limit 1;
 if not found then return jsonb_build_object('status','blocked','code','recorded_fund_review_required');end if;
 allocation_id:=(recipient#>>'{nativeFinanceSource,raw,allocation,revisionId}')::uuid;
 if review.proposal_revision_id<>proposal.id or review.native_allocation_revision_id<>allocation_id
  or review.income_head_version<>income_head or review.income_head_digest<>income_head_digest then
  return jsonb_build_object('status','blocked','code','recorded_fund_review_stale');
 end if;
  if review.source_capture->>'recipientSourceDigest'is distinct from recipient_digest
   or(review.review_status='reviewed_zero'and income_total<>0)
   or(review.review_status='recorded_complete'and income_total=0)then
  return jsonb_build_object('status','blocked','code','recorded_fund_review_invalid');
 end if;
 sanctioning:=app.native_sanctioning_coverage_v1(tid,eid,recipient,review.sanctioning_expense_event_id);
 if sanctioning->>'status'='retry_exact'then return sanctioning;end if;
 if sanctioning->>'status'<>'available'
  or sanctioning->>'snapshotId'is distinct from review.sanctioning_fee_snapshot_id::text
  or(sanctioning->>'allocatedExpenseMinor')::numeric is distinct from review.sanctioning_allocated_minor::numeric
  or review.source_capture->'sanctioning'is distinct from sanctioning-'status'then
  return jsonb_build_object('status','blocked','code','sanctioning_coverage_unverified');
 end if;
 for source_row in select value from jsonb_array_elements(recipient#>'{nativeFinanceSource,raw,allocation,eventSources}')loop
  if source_row->>'state'<>'active'or source_row->>'physicalEvidenceId'is distinct from source_row->>'sourceId'then
   return jsonb_build_object('status','blocked','code','native_finance_source_changed');
  end if;
  for part in select value from jsonb_array_elements(source_row->'allocations')loop
   if(part->>'classificationReviewed')::boolean is distinct from true or part->'poolId'<>'null'::jsonb
    or part->>'eventId'is distinct from eid::text then
    return jsonb_build_object('status','blocked','code','native_finance_source_changed');
   end if;
   if part->>'bucket'='regular_entry'then regular_total:=regular_total+(part->>'amountMinor')::numeric;
   elsif part->>'bucket'='player_benefit'then benefit_total:=benefit_total+(part->>'amountMinor')::numeric;
   elsif part->>'bucket'='operating_expense'then operating_total:=operating_total+(part->>'amountMinor')::numeric;
   else return jsonb_build_object('status','blocked','code','optional_pool_or_income_source_unsupported');end if;
  end loop;
 end loop;
 fund_total:=regular_total-benefit_total-operating_total+income_total;
 if regular_total<0 or benefit_total<0 or operating_total<0 or income_total<0 or fund_total<0
  or greatest(regular_total,benefit_total,operating_total,income_total,fund_total)>9007199254740991 then
  return jsonb_build_object('status','blocked','code','recorded_fund_invalid');
 end if;
 if jsonb_array_length(editor->'overrideHistory')>0 then
  if jsonb_typeof(editor->'overrideInput')is distinct from'object'
   or editor#>>'{overrideInput,fundMinor}'is distinct from fund_total::bigint::text
   or editor#>'{overrideInput,settings}'is distinct from editor#>'{basis,settings}'
   or editor#>'{overrideInput,qualifierCount}'is distinct from editor#>'{basis,qualifierCount}'
   or jsonb_typeof(editor->'overridePlan')is distinct from'string'
   or(editor->>'overridePlan')::jsonb is distinct from jsonb_build_object('basis',editor->'basis','history',editor->'history')then
   return jsonb_build_object('status','blocked','code','stale_override_plan');
  end if;
 end if;
 qualifier_count:=(recipient#>>'{playoff,qualifierCount}')::integer;
 if qualifier_count not in(4,5)then return jsonb_build_object('status','blocked','code','unsupported_qualifier_count');end if;
 settings:=editor#>'{basis,settings}';method:=settings->>'method';factor_text:=settings->>'factor';
 if factor_text!~'^(0|[1-9][0-9]*)(\.[0-9]{1,6})?$'then return jsonb_build_object('status','blocked','code','invalid_factor');end if;
 dot_at:=strpos(factor_text,'.');factor_den:=case when dot_at=0 then 1 else power(10,length(factor_text)-dot_at)end;
 factor_num:=replace(factor_text,'.','')::numeric;
 if factor_num<factor_den or factor_num>1000*factor_den then return jsonb_build_object('status','blocked','code','factor_outside_technical_domain');end if;
 if method='graduated_all_qualifiers'then requested:=qualifier_count;
 elsif method='custom_top_paid'then requested:=(settings->>'paidPlaces')::integer;
 elsif method='custom_paid_ratio'then return jsonb_build_object('status','blocked','code','custom_ratio_paid_count_policy_unresolved');
 else return jsonb_build_object('status','blocked','code','invalid_settings');end if;
 if requested<1 or requested>qualifier_count then return jsonb_build_object('status','blocked','code','invalid_paid_places');end if;
 first_place:=1;
 while first_place<=qualifier_count loop
  last_place:=least(qualifier_count,case when first_place=1 then 1 else(first_place-1)*2 end);
  if requested between first_place and last_place then included_places:=last_place;end if;
  bands:=bands||jsonb_build_array(jsonb_build_object('firstPlace',first_place,'lastPlace',last_place,'people',last_place-first_place+1));
  first_place:=case when first_place=1 then 2 else first_place*2-1 end;
 end loop;
 all_band_count:=jsonb_array_length(bands);band_count:=0;
 for i in 0..all_band_count-1 loop
  if(bands->i->>'lastPlace')::integer<=included_places then band_count:=band_count+1;end if;
 end loop;
 for i in 0..band_count-1 loop
  weight:=power(factor_num,band_count-1-i)*power(factor_den,i);
  denominator:=denominator+weight*((bands->i->>'people')::integer);
 end loop;
 for ov in select value from jsonb_array_elements(editor->'overrideHistory')loop
  override_latest:=jsonb_set(override_latest,array[(ov->>'firstPlace')||':'||(ov->>'lastPlace')],ov,true);
 end loop;
 for i in 0..all_band_count-1 loop
  first_place:=(bands->i->>'firstPlace')::integer;last_place:=(bands->i->>'lastPlace')::integer;people:=last_place-first_place+1;
  included:=last_place<=included_places;
  if included then
   weight:=power(factor_num,band_count-1-i)*power(factor_den,i);raw:=fund_total*weight;
   amount:=div(raw*2+denominator*500,denominator*1000)*500;
   ov:=override_latest->(first_place||':'||last_place);
   if ov is not null and not(ov->>'voided')::boolean then amount:=(ov->>'perPersonMinor')::numeric;end if;
   if amount<=0 or amount%500<>0 then return jsonb_build_object('status','blocked','code','award_amount_invalid');end if;
   if previous_amount is not null and amount>previous_amount then return jsonb_build_object('status','blocked','code','award_rank_order_invalid');end if;
   previous_amount:=amount;
   total_awards:=total_awards+amount*people;positive_places:=positive_places+people;
  else amount:=0;end if;
  groups:=groups||jsonb_build_array(jsonb_build_object('firstPlace',first_place,'lastPlace',last_place,'people',people,
   'included',included,'perPersonMinor',amount::bigint,'groupTotalMinor',(amount*people)::bigint));
 end loop;
 if total_awards<>fund_total then return jsonb_build_object('status','blocked','code','recorded_fund_imbalance');end if;
 -- Placement is reconstructed only from the verified native series results.
 for match_row in select value from jsonb_array_elements(recipient#>'{playoff,matches}')loop
  if(match_row->>'slot')::integer=qualifier_count-1 then
   final_winner:=(match_row#>>'{result,winnerId}')::uuid;final_loser:=(match_row#>>'{result,loserId}')::uuid;
  end if;
 end loop;
 for player in select value from jsonb_array_elements(recipient#>'{playoff,players}')loop
  participant:=(player->>'participantId')::uuid;
  if participant=final_winner then place_first:=1;place_last:=1;
  elsif participant=final_loser then place_first:=2;place_last:=2;
  else
   place_first:=null;place_last:=null;
   for match_row in select value from jsonb_array_elements(recipient#>'{playoff,matches}')loop
    loser:=(match_row#>>'{result,loserId}')::uuid;
    if loser=participant then
     if(match_row->>'round')='semifinal'then place_first:=3;place_last:=4;
     elsif qualifier_count=5 and(match_row->>'slot')::integer=1 then place_first:=5;place_last:=5;end if;
    end if;
   end loop;
  end if;
  if place_first is null then return jsonb_build_object('status','blocked','code','recipient_mapping_incomplete');end if;
  ov:=null;
  for income_item in select value from jsonb_array_elements(groups)loop
   if(income_item->>'firstPlace')::integer=place_first and(income_item->>'lastPlace')::integer=place_last then ov:=income_item;exit;end if;
  end loop;
  if ov is null then return jsonb_build_object('status','blocked','code','recipient_band_missing');end if;
  recipients:=recipients||jsonb_build_array(jsonb_build_object(
   'participantId',participant,'profileId',(player->>'profileId')::uuid,
   'displayName',player->>'displayName','tournamentPlayerId',player->>'tournamentPlayerId',
   'firstPlace',place_first,'lastPlace',place_last,'included',(ov->>'included')::boolean,
   'amountMinor',(ov->>'perPersonMinor')::bigint
  ));
 end loop;
 if jsonb_array_length(recipients)<>qualifier_count then return jsonb_build_object('status','blocked','code','recipient_mapping_incomplete');end if;
 fund_source_digest:=encode(extensions.digest(convert_to(jsonb_build_array(
  'native-recorded-fund-source-v1',recipient_digest,proposal.id,proposal.source_digest,
   proposal.basis_digest,allocation_id,income_head,income_head_digest,review.id,review.source_digest,sanctioning-'status',
  regular_total,benefit_total,operating_total,income_total,fund_total
 )::text,'utf8'),'sha256'),'hex');
 capture:=jsonb_build_object(
  'kind','native-playoff-final-award-source-v1','actorId',actor,'tournamentId',tid,'eventId',eid,
  'nativeRecipientSource',recipient,'recipientSourceDigest',recipient_digest,
  'proposal',jsonb_build_object('revisionId',proposal.id,'version',proposal.version,'sourceDigest',proposal.source_digest,
   'basisDigest',proposal.basis_digest,'qualificationResultVersionId',proposal.qualification_result_version_id),
  'allocation',jsonb_build_object('revisionId',allocation_id,'version',recipient#>'{nativeFinanceSource,raw,allocation,version}',
   'sourceDigest',recipient#>'{nativeFinanceSource,raw,allocation,sourceDigest}'),
  'income',jsonb_build_object('headVersion',income_head,'headDigest',income_head_digest,
   'reviewId',review.id,'reviewVersion',review.version,'reviewStatus',review.review_status,
   'reviewedBy',review.reviewed_by,'reviewedAt',review.reviewed_at,'incomeTotalMinor',income_total::bigint,
   'records',income_records,'sourceDigest',fund_source_digest),
   'sanctioning',sanctioning-'status',
  'fund',jsonb_build_object('currency','USD','regularEntryIncomeMinor',regular_total::bigint,
   'benefitExpenseMinor',benefit_total::bigint,'operatingExpenseMinor',operating_total::bigint,
   'unrestrictedIncomeMinor',income_total::bigint,'awardFundMinor',fund_total::bigint,
   'recordedFundAvailable',true,'bankReceiptVerified',false),
  'projection',jsonb_build_object('kind','native-unpaid-final-award-projection-v1',
   'requestedPaidPlaces',requested,'includedPaidPlaces',included_places,'positiveAwardPlaces',positive_places,
   'groups',groups,'recipients',recipients,'totalMinor',total_awards::bigint),
  'fundSourceDigest',fund_source_digest,'awardStatus','recordable_unpaid',
  'moneyMoved',false,'payoutAuthorized',false,'disbursementAuthorized',false,'finalizationAuthorized',false
 );
 source_digest:=encode(extensions.digest(convert_to(jsonb_build_array('native-playoff-final-award-source-v1',capture)::text,'utf8'),'sha256'),'hex');
 return capture||jsonb_build_object('status','source_available','sourceDigest',source_digest);
exception when lock_not_available then return jsonb_build_object('status','retry_exact','code','source_busy');
 when invalid_text_representation or numeric_value_out_of_range or division_by_zero then
 return jsonb_build_object('status','blocked','code','source_shape_invalid');
end$$;

do $$declare f text;begin foreach f in array array[
 'app.native_playoff_final_awards_enabled_v1()',
 'app.finish_native_playoff_finance_write_v1(uuid,uuid,uuid,uuid,jsonb)',
 'app.native_sanctioning_coverage_v1(uuid,uuid,jsonb,uuid)',
 'app.native_playoff_final_award_source_v1(uuid,uuid,uuid)',
 'app.record_native_unrestricted_income_v1(uuid,uuid,jsonb)',
 'app.review_native_recorded_fund_v1(uuid,uuid,jsonb)',
 'app.legacy_financial_liability_exists_v1(uuid,uuid)',
 'app.require_no_native_final_award_liability_v1()',
 'app.record_native_playoff_final_awards_v1(uuid,uuid,jsonb)',
 'app.get_native_playoff_final_award_record_v1(uuid,uuid)',
 'app.get_native_playoff_finance_write_reconciliation_v1(uuid,uuid,uuid)'
]loop
 execute format('alter function %s owner to postgres',f);
 execute format('revoke all on function %s from public,anon,authenticated,service_role',f);
end loop;end$$;




-- Frozen source custom-pool-setup-save-v3.sql

alter table app.tournament_setup_side_pool_versions add column custom_ratio_denominator_v3 integer
 check(custom_ratio_denominator_v3 is null or custom_ratio_denominator_v3>0);

-- Protected full-request reservation, not a session-setting claim, is the
-- authority for a Side row's new numeric intent inside this exact transaction.
create function app.reserved_custom_side_ratio_v3(tid uuid,rid uuid,row_id uuid,slot_no integer)returns integer
language plpgsql security definer set search_path=''as $$
declare request_value jsonb;intent jsonb;ratio integer;n integer;pool jsonb;
begin
 select r.request_payload into request_value from app.tournament_setup_revisions rev
 join app.operation_receipts receipt on receipt.id=rev.operation_receipt_id
 join app.setup_custom_q_save_reservations_v2 r on r.actor_id=rev.actor_profile_id and r.operation_id=receipt.client_operation_id
 where rev.tournament_id=tid and rev.id=rid and r.tournament_id=tid and receipt.tournament_id=tid
 and receipt.actor_profile_id=rev.actor_profile_id and receipt.outcome='accepted'and receipt.operation_type='save_tournament_setup_version'
 and r.request_payload#>>'{request,expectedVersion}'=(rev.version-1)::text;
 if request_value is null then return null;end if;
 select count(*),min(value::text)::jsonb into n,intent from jsonb_array_elements(request_value->'customPayouts')
 where value->>'scope'='side'and value#>>'{source,eventClientRowId}'=row_id::text and value#>>'{source,poolSlot}'=slot_no::text;
 if n=0 then return null;end if;
 if n<>1 then raise exception'duplicate_custom_side_intent';end if;
 ratio:=(intent->>'ratioDenominator')::integer;
 select value#>array['sidePools',(slot_no-1)::text] into pool from jsonb_array_elements(request_value#>'{request,payload,events}')
 where value->>'clientRowId'=row_id::text and value->>'formatCode'='standard_singles'and value->>'eventKind'in('main','consolation','satellite');
 if ratio<=0 or pool is null or(pool?'payoutType'and pool->>'payoutType'is distinct from'graduated-1-in-'||ratio::text)
 then raise exception'invalid_custom_side_intent';end if;
 return ratio;
end$$;
revoke all on function app.reserved_custom_side_ratio_v3(uuid,uuid,uuid,integer)from public,anon,authenticated,service_role;

create function app.set_custom_side_ratio_v3()returns trigger
language plpgsql security definer set search_path=''as $$
declare row_id uuid;ratio integer;
begin
 select client_row_id into row_id from app.tournament_setup_event_versions
 where id=new.setup_event_version_id and tournament_id=new.tournament_id and setup_revision_id=new.setup_revision_id;
 ratio:=app.reserved_custom_side_ratio_v3(new.tournament_id,new.setup_revision_id,row_id,new.slot);
 if ratio is not null then
  -- No surrogate preset. The new field and immutable intent are explicit.
  new.payout_type:=null;new.custom_ratio_denominator_v3:=ratio;
 elsif new.custom_ratio_denominator_v3 is not null then raise exception'custom_side_requires_full_reservation';end if;
 return new;
end$$;
revoke all on function app.set_custom_side_ratio_v3()from public,anon,authenticated,service_role;
-- PostgreSQL fires same-kind triggers alphabetically; run after original type
-- copy-forward so an old preset cannot override this explicit new intent.
create trigger zz_custom_side_ratio_v3 before insert on app.tournament_setup_side_pool_versions
 for each row execute function app.set_custom_side_ratio_v3();

-- Preserve the original configurator and linked writer. The private new clones
-- differ only at the guarded missing-type branch and Side stage call.
do $$declare d text;patched text;anchor text;
begin
 d:=replace(pg_get_functiondef('app.linked_setup_configure_sides_v1(uuid,uuid,uuid,jsonb)'::regprocedure),E'\r\n',E'\n');
 anchor:='elsif not coalesce(pre_rollout,false) and existing_count=0 then';
 if strpos(d,anchor)=0 then raise exception'custom_side_configurator_anchor_changed';end if;
 patched:=replace(d,'FUNCTION app.linked_setup_configure_sides_v1(','FUNCTION app.configure_custom_pool_sides_v3(');
 if patched=d then raise exception'custom_side_configurator_name_changed';end if;
 patched:=replace(patched,anchor,'elsif not coalesce(pre_rollout,false) and existing_count=0 and app.reserved_custom_side_ratio_v3(tid,rid,(ev->>''clientRowId'')::uuid,s) is null then');
 execute patched;
 d:=replace(pg_get_functiondef('public.save_linked_tournament_setup_v1(uuid,jsonb)'::regprocedure),E'\r\n',E'\n');
 anchor:='app.linked_setup_configure_sides_v1(';
 if strpos(d,anchor)=0 then raise exception'custom_side_linked_stage_anchor_changed';end if;
 patched:=replace(d,'FUNCTION public.save_linked_tournament_setup_v1(','FUNCTION app.save_linked_custom_pool_setup_v3(');
 if patched=d then raise exception'custom_side_linked_name_changed';end if;
 patched:=replace(patched,anchor,'app.configure_custom_pool_sides_v3(');
 execute patched;
end$$;
revoke all on function app.configure_custom_pool_sides_v3(uuid,uuid,uuid,jsonb),app.save_linked_custom_pool_setup_v3(uuid,jsonb)from public,anon,authenticated,service_role;

-- Until a separately reviewed operational policy is published, legacy fixed
-- Side policy must not interpret an explicit custom row as an untyped pool.
create function app.guard_custom_side_policy_v3()returns trigger
language plpgsql security definer set search_path=''as $$
declare ratio integer;
begin
 select s.custom_ratio_denominator_v3 into ratio from app.tournament_setup_side_pool_materializations m
 join app.tournament_setup_side_pool_versions s on s.id=m.setup_side_pool_version_id and s.tournament_id=m.tournament_id
 where m.pool_id=new.pool_id and m.tournament_id=new.tournament_id and m.event_id=new.event_id;
 if ratio is not null then
  if tg_table_name<>'side_pool_graduated_policies_v2'then raise exception'custom_side_requires_graduated_policy_v3';end if;
  if new.ratio is distinct from ratio then raise exception'custom_side_ratio_mismatch_v3';end if;
 end if;
 return new;
end$$;
revoke all on function app.guard_custom_side_policy_v3()from public,anon,authenticated,service_role;
create trigger custom_side_policy_v3 before insert on app.side_pool_graduated_policies_v2
 for each row execute function app.guard_custom_side_policy_v3();
create trigger custom_side_legacy_policy_v3 before insert on app.event_side_pool_policy_versions
 for each row execute function app.guard_custom_side_policy_v3();

-- A fresh editor must recover explicit numeric intent from durable rows, not
-- infer it from the display name or reuse a previous source/operation pin.
create function app.get_custom_pool_setup_workspace_v3(tid uuid)returns jsonb
language plpgsql security definer set search_path=''as $$
declare b jsonb;rid uuid;retained jsonb;intents jsonb;sides jsonb;
begin
 b:=app.get_custom_q_setup_base_v2(tid);
 if b->'base'is null then return b;end if;
 rid:=(b#>>'{base,setupRevisionId}')::uuid;
 select request_payload into retained from app.setup_custom_payout_batches_v2 where tournament_id=tid and setup_revision_id=rid;
 select coalesce(jsonb_agg(i.original_intent order by e.ordinal,i.scope,i.pool_slot),'[]'::jsonb)into intents
 from app.setup_custom_payout_intents_v2 i join app.tournament_setup_event_versions e
 on e.id=i.setup_event_version_id and e.tournament_id=i.tournament_id and e.setup_revision_id=i.setup_revision_id
 where i.tournament_id=tid and i.setup_revision_id=rid;
 if jsonb_array_length(intents)>0 and retained is null then return jsonb_build_object('status','blocked','code','custom_side_source_mismatch');end if;
 if exists(select 1 from app.tournament_setup_side_pool_versions s where s.tournament_id=tid and s.setup_revision_id=rid and s.custom_ratio_denominator_v3 is not null
 and not exists(select 1 from app.setup_custom_payout_intents_v2 i where i.tournament_id=tid and i.setup_revision_id=rid and i.setup_event_version_id=s.setup_event_version_id and i.scope='side'and i.pool_slot=s.slot and i.ratio_denominator=s.custom_ratio_denominator_v3))
 or exists(select 1 from app.setup_custom_payout_intents_v2 i where i.tournament_id=tid and i.setup_revision_id=rid and i.scope='side'
 and not exists(select 1 from app.tournament_setup_side_pool_versions s where s.tournament_id=tid and s.setup_revision_id=rid and s.setup_event_version_id=i.setup_event_version_id and s.slot=i.pool_slot and s.custom_ratio_denominator_v3=i.ratio_denominator and s.payout_type is null))
 then return jsonb_build_object('status','blocked','code','custom_side_source_mismatch');end if;
 select coalesce(jsonb_agg(jsonb_build_object('setupSidePoolVersionId',s.id,'eventClientRowId',e.client_row_id,'slot',s.slot,'payoutType',s.payout_type,'customRatio',s.custom_ratio_denominator_v3)order by e.ordinal,s.slot),'[]'::jsonb)into sides
 from app.tournament_setup_side_pool_versions s join app.tournament_setup_event_versions e
 on e.id=s.setup_event_version_id and e.tournament_id=s.tournament_id and e.setup_revision_id=s.setup_revision_id
 where s.tournament_id=tid and s.setup_revision_id=rid;
 return jsonb_build_object('status','available','capability',false,'scope','draft-q-side-only','base',b->'base',
 'currentSetup',public.get_tournament_setup_workspace(tid)->'current','retainedEnvelope',retained,'customPayouts',intents,'sidePayouts',sides,
 'newEditRequiresFreshBaseAndOperation',true,'policyPublished',false,'moneyMoved',false);
end$$;
revoke all on function app.get_custom_pool_setup_workspace_v3(uuid)from public,anon,authenticated,service_role;

create function app.save_custom_pool_setup_draft_v3(p_tournament_id uuid,p_envelope jsonb)returns jsonb
language plpgsql security definer set search_path=''as $$
declare a uuid:=auth.uid();op uuid;h text;prior app.setup_custom_q_save_reservations_v2%rowtype;
 req jsonb;payload jsonb;intents jsonb;i jsonb;s jsonb;e jsonb;p jsonb;base jsonb;base_reply jsonb;
 expected integer;ratio integer;slot integer;n integer;event_id uuid;seen text[]:=array[]::text[];k text;
 linked jsonb;response jsonb;rev app.tournament_setup_revisions%rowtype;rec app.operation_receipts%rowtype;batch_id uuid;code text;
begin
 if a is null then return jsonb_build_object('status','rejected','code','authentication_required');end if;
 if current_setting('transaction_isolation')<>'read committed'then return jsonb_build_object('status','retry_exact','code','isolation_not_supported');end if;
 -- Only identify the exact operation before reserving; all substantive
 -- rejections after this point are bound to this complete original envelope.
 begin
  if jsonb_typeof(p_envelope)is distinct from'object'or jsonb_typeof(p_envelope->'request')is distinct from'object'or coalesce(p_envelope#>>'{request,idempotencyKey}','')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'then raise exception'invalid operation';end if;
  op:=(p_envelope#>>'{request,idempotencyKey}')::uuid;
 exception when others then return jsonb_build_object('status','rejected','code','invalid_request');end;
 if not pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtextextended(a::text||':'||op::text,0))then return jsonb_build_object('status','retry_exact','code','operation_busy');end if;
 perform 1 from app.tournaments where id=p_tournament_id for update nowait;
 if not found then return jsonb_build_object('status','rejected','code','tournament_unavailable');end if;
 perform 1 from app.tournament_roles where tournament_id=p_tournament_id and profile_id=a and role in('director','co_director')order by role for key share nowait;
 if not found then return jsonb_build_object('status','rejected','code','not_director');end if;
 h:=encode(extensions.digest(convert_to(jsonb_build_array('setup-custom-payouts-v2',a,p_tournament_id,op,p_envelope)::text,'utf8'),'sha256'),'hex');
 select*into prior from app.setup_custom_q_save_reservations_v2 where actor_id=a and operation_id=op;
 if found then
  if prior.tournament_id is distinct from p_tournament_id or prior.request_hash is distinct from h or prior.request_payload is distinct from p_envelope then return jsonb_build_object('status','rejected','code','idempotency_conflict');end if;
  select response_payload into response from app.setup_custom_q_save_outcomes_v2 where actor_id=a and operation_id=op;
  if response is null then raise exception'custom Q reservation missing atomic outcome';end if;
  return response;
 end if;
 if exists(select 1 from app.operation_receipts where actor_profile_id=a and client_operation_id=op)
 or exists(select 1 from app.setup_event_link_save_reservations_v1 where actor_id=a and operation_id=op)
 or exists(select 1 from app.setup_custom_payout_batches_v2 where actor_id=a and operation_id=op)then return jsonb_build_object('status','rejected','code','idempotency_conflict');end if;
 insert into app.setup_custom_q_save_reservations_v2(actor_id,operation_id,tournament_id,request_payload,request_hash)values(a,op,p_tournament_id,p_envelope,h);
 begin
  if not(p_envelope?&array['kind','base','request','choices','customPayouts'])or exists(select 1 from jsonb_object_keys(p_envelope)x where x<>all(array['kind','base','request','choices','customPayouts']))or p_envelope->>'kind'is distinct from'setup-custom-payouts-v2'then raise exception'custom_q_rejected:invalid_request';end if;
  req:=p_envelope->'request';payload:=req->'payload';intents:=p_envelope->'customPayouts';
  if not(req?&array['expectedVersion','payload','idempotencyKey'])or exists(select 1 from jsonb_object_keys(req)x where x<>all(array['expectedVersion','payload','idempotencyKey']))or jsonb_typeof(req->'expectedVersion')is distinct from'number'or coalesce(req->>'expectedVersion','')!~'^(0|[1-9][0-9]*)$'or jsonb_typeof(payload)is distinct from'object'or jsonb_typeof(payload->'events')is distinct from'array'or not app.valid_setup_event_links_v1(payload->'events',p_envelope->'choices')or jsonb_typeof(intents)is distinct from'array'then raise exception'custom_q_rejected:invalid_request';end if;
  expected:=(req->>'expectedVersion')::integer;
  if jsonb_array_length(intents)not between 0 and 288 then raise exception'custom_q_rejected:invalid_request';end if;
  base_reply:=app.get_custom_q_setup_base_v2(p_tournament_id);
  if base_reply->>'status'='retry_exact'then raise exception using errcode='55P03',message='custom source busy';end if;
  base:=base_reply->'base';
  if base is null or expected is distinct from(base->>'setupVersion')::integer then raise exception'custom_q_rejected:stale_version';end if;
  if p_envelope->'base'is distinct from base then raise exception'custom_q_rejected:source_changed';end if;
  -- Q and explicit Side intents. Typed presets remain unchanged. A Satellite
  -- custom-looking ratio is explicitly unsupported, not treated as Q policy.
  for e in select value from jsonb_array_elements(payload->'events')loop
   if coalesce(e->>'clientRowId','')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'then raise exception'custom_q_rejected:invalid_event';end if;
   if jsonb_typeof(e->'sidePools')is distinct from'array'or jsonb_typeof(e->'qPools')is distinct from'array'then raise exception'custom_q_rejected:invalid_event';end if;
   for p in select value from jsonb_array_elements(e->'sidePools')loop
    if p?'payoutType'and p->>'payoutType'not in('graduated-1-in-4','graduated-1-in-6','graduated-1-in-8','graduated-1-in-10')then raise exception'custom_q_rejected:invalid_side_type';end if;
   end loop;
   if e->>'eventKind'='satellite'and app.custom_payout_classification_text_v2(e->>'payoutNote')~*'^1\s+in\s'and app.custom_payout_classification_text_v2(e->>'payoutNote')not in('1 in 4','1 in 5','1 in 6')then raise exception'custom_q_rejected:satellite_custom_unsupported';end if;
  end loop;
  for i in select value from jsonb_array_elements(intents)loop
   if jsonb_typeof(i)is distinct from'object'or not(i?&array['kind','scope','ratioDenominator','source'])or exists(select 1 from jsonb_object_keys(i)x where x<>all(array['kind','scope','ratioDenominator','source']))or i->>'kind'is distinct from'custom-payout-intent-v1'or coalesce(i->>'scope','')not in('q','side')then raise exception'custom_q_rejected:non_q_intent_unsupported';end if;
   s:=i->'source';
   if jsonb_typeof(s)is distinct from'object'or not(s?&array['tournamentId','eventClientRowId','setupRevisionId','setupVersion','poolSlot','sourceDigest'])or exists(select 1 from jsonb_object_keys(s)x where x<>all(array['tournamentId','eventClientRowId','setupRevisionId','setupVersion','poolSlot','sourceDigest']))
    or s->'tournamentId'is distinct from base->'tournamentId'or s->'setupRevisionId'is distinct from base->'setupRevisionId'or s->'setupVersion'is distinct from base->'setupVersion'or s->'sourceDigest'is distinct from base->'sourceDigest'
    or jsonb_typeof(s->'poolSlot')is distinct from'number'or coalesce(s->>'poolSlot','')!~'^[1-6]$'or(i->>'scope'='q'and coalesce(s->>'poolSlot','')!~'^[12]$')or coalesce(s->>'eventClientRowId','')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
    or jsonb_typeof(i->'ratioDenominator')is distinct from'number'or coalesce(i->>'ratioDenominator','')!~'^[1-9][0-9]*$'then raise exception'custom_q_rejected:invalid_intent';end if;
   ratio:=(i->>'ratioDenominator')::integer;slot:=(s->>'poolSlot')::integer;k:=(s->>'eventClientRowId')||':'||(i->>'scope')||':'||slot::text;
   if k=any(seen)then raise exception'custom_q_rejected:duplicate_intent';end if;seen:=array_append(seen,k);
   select count(*),min(value::text)::jsonb into n,e from jsonb_array_elements(payload->'events')where value->>'clientRowId'=s->>'eventClientRowId';
   if n<>1 then raise exception'custom_q_rejected:invalid_intent';end if;
   if i->>'scope'='q'then
    if e->>'eventKind'not in('main','consolation')or e#>>array['qPools',(slot-1)::text,'poolTypeCode']is distinct from'Graduated (1-in-'||ratio::text||')'then raise exception'custom_q_rejected:invalid_intent';end if;
   else
    p:=e#>array['sidePools',(slot-1)::text];
    if e->>'eventKind'not in('main','consolation','satellite')or e->>'formatCode'is distinct from'standard_singles'or p is null or (p?'payoutType'and p->>'payoutType'is distinct from'graduated-1-in-'||ratio::text)then raise exception'custom_q_rejected:invalid_side_intent';end if;
   end if;
  end loop;
  for e in select value from jsonb_array_elements(payload->'events')loop
   for p,slot in select value,ordinality::integer from jsonb_array_elements(e->'qPools')with ordinality loop
    if app.custom_payout_classification_text_v2(p->>'poolTypeCode')~*'^Graduated\s*\(1-in-'and app.custom_payout_classification_text_v2(p->>'poolTypeCode')not in('Graduated (1-in-4)','Graduated (1-in-6)','Graduated (1-in-8)','Graduated (1-in-10)')and not((e->>'clientRowId')||':q:'||slot::text=any(seen))then raise exception'custom_q_rejected:missing_intent';end if;
   end loop;
   for p,slot in select value,ordinality::integer from jsonb_array_elements(e->'sidePools')with ordinality loop
    if not(p?'payoutType')and not((e->>'clientRowId')||':side:'||slot::text=any(seen))then raise exception'custom_q_rejected:missing_side_intent';end if;
   end loop;
  end loop;
  linked:=app.save_linked_custom_pool_setup_v3(p_tournament_id,jsonb_build_object('kind','setup-event-links-v1','request',req,'choices',p_envelope->'choices'));
  if linked->>'status'is distinct from'linked_setup_saved'then raise exception'custom_q_rejected:%',coalesce(linked->>'code','core_unavailable');end if;
  select*into rev from app.tournament_setup_revisions where tournament_id=p_tournament_id and id=(linked#>>'{result,revisionId}')::uuid;
  select*into rec from app.operation_receipts where id=rev.operation_receipt_id;
  if rev.id is null or rev.version<>expected+1 or rev.actor_profile_id is distinct from a or rec.actor_profile_id is distinct from a or rec.client_operation_id is distinct from op or rec.tournament_id is distinct from p_tournament_id or rec.outcome is distinct from'accepted'or rec.operation_type is distinct from'save_tournament_setup_version'then raise exception'custom_q_rejected:core_unavailable';end if;
  insert into app.setup_custom_payout_batches_v2(tournament_id,setup_revision_id,base_setup_revision_id,base_setup_version,base_source_digest,actor_id,operation_id,core_receipt_id,request_payload,request_hash)
   values(p_tournament_id,rev.id,(base->>'setupRevisionId')::uuid,expected,base->>'sourceDigest',a,op,rec.id,p_envelope,h)returning id into batch_id;
  for i in select value from jsonb_array_elements(intents)loop
   s:=i->'source';select id into event_id from app.tournament_setup_event_versions where tournament_id=p_tournament_id and setup_revision_id=rev.id and client_row_id=(s->>'eventClientRowId')::uuid and event_kind in('main','consolation','satellite');
   if event_id is null then raise exception'custom_q_rejected:core_unavailable';end if;
   if i->>'scope'='q'and not exists(select 1 from app.tournament_setup_q_pool_versions q where q.tournament_id=p_tournament_id and q.setup_revision_id=rev.id and q.setup_event_version_id=event_id and q.slot=(s->>'poolSlot')::smallint and q.pool_type_code='Graduated (1-in-'||(i->>'ratioDenominator')||')')then raise exception'custom_q_rejected:core_unavailable';end if;
   if i->>'scope'='side'and not exists(select 1 from app.tournament_setup_side_pool_versions q where q.tournament_id=p_tournament_id and q.setup_revision_id=rev.id and q.setup_event_version_id=event_id and q.slot=(s->>'poolSlot')::smallint and q.custom_ratio_denominator_v3=(i->>'ratioDenominator')::integer)then raise exception'custom_q_rejected:core_unavailable';end if;
   insert into app.setup_custom_payout_intents_v2(batch_id,tournament_id,setup_revision_id,setup_event_version_id,scope,pool_slot,ratio_denominator,amount_method,original_intent)
   values(batch_id,p_tournament_id,rev.id,event_id,i->>'scope',(s->>'poolSlot')::smallint,(i->>'ratioDenominator')::integer,'graduated-custom-ratio-largest-remainder-5usd-v3',i);
  end loop;
  response:=jsonb_build_object('status','custom_pool_setup_draft_saved_v3','scope','draft-q-side-only','batchId',batch_id,'fullRequestHash',h,'envelope',p_envelope,'linked',linked,'operatingPolicyPublished',false,'moneyMoved',false);
 exception
  when raise_exception then
   if sqlerrm not like'custom_q_rejected:%'then raise;end if;
   response:=jsonb_build_object('status','rejected','code',split_part(sqlerrm,':',2));
  when invalid_text_representation or numeric_value_out_of_range then response:=jsonb_build_object('status','rejected','code','invalid_request');
 end;
 -- Both accepted core/journal and rejection outcome commit with the original
 -- full-envelope reservation; any unhandled error rolls back everything.
 if response->>'status'='rejected' then
  -- The rolled-back core subtransaction must not leave this actor/op reusable
  -- through an older save endpoint that knows only the global receipt table.
  insert into app.operation_receipts(actor_profile_id,tournament_id,operation_type,target_id,request_hash,client_operation_id,outcome,response_payload,applied_at)
   values(a,p_tournament_id,'save_custom_q_setup_draft_v2',p_tournament_id,h,op,'rejected',response,clock_timestamp());
 end if;
 insert into app.setup_custom_q_save_outcomes_v2(actor_id,operation_id,response_payload)values(a,op,response);
 return response;
exception when lock_not_available then
 -- Outer subtransaction rolls back reservation/core/journal/receipt/outcome.
 -- Busy is nonterminal: keep the original operation and retry it exactly.
 return jsonb_build_object('status','retry_exact','code','source_busy');
end$$;

revoke all on function app.save_custom_pool_setup_draft_v3(uuid,jsonb)from public,anon,authenticated,service_role;
create function app.reconcile_custom_pool_setup_draft_v3(tid uuid,envelope jsonb)returns jsonb
language sql security definer set search_path=''as $$select app.reconcile_custom_q_setup_draft_v2(tid,envelope)$$;
revoke all on function app.reconcile_custom_pool_setup_draft_v3(uuid,jsonb)from public,anon,authenticated,service_role;
do $$declare signature text;begin
 foreach signature in array array[
 'app.reserved_custom_side_ratio_v3(uuid,uuid,uuid,integer)',
 'app.set_custom_side_ratio_v3()',
 'app.configure_custom_pool_sides_v3(uuid,uuid,uuid,jsonb)',
 'app.save_linked_custom_pool_setup_v3(uuid,jsonb)',
 'app.guard_custom_side_policy_v3()',
 'app.get_custom_pool_setup_workspace_v3(uuid)',
 'app.save_custom_pool_setup_draft_v3(uuid,jsonb)',
 'app.reconcile_custom_pool_setup_draft_v3(uuid,jsonb)'
 ]loop execute format('alter function %s owner to postgres',signature);end loop;
end$$;


-- Frozen source custom-side-accounting-bridge-v1.sql


-- Preserve the historical V2 method and its 2..100 domain. Only the new,
-- explicitly named method admits the technical PostgreSQL positive-int range.
alter table app.side_pool_graduated_policies_v2 drop constraint side_pool_graduated_policies_v2_method_check;
alter table app.side_pool_graduated_policies_v2 drop constraint side_pool_graduated_policies_v2_ratio_check;
alter table app.side_pool_graduated_policies_v2 add constraint side_pool_graduated_method_v4_check check(method in(
 'graduated-acc-weighted-largest-remainder-5usd-v2','side-custom-graduated-policy-v4'));
alter table app.side_pool_graduated_policies_v2 add constraint side_pool_graduated_ratio_v4_check check(
 (method='graduated-acc-weighted-largest-remainder-5usd-v2'and ratio between 2 and 100)or
 (method='side-custom-graduated-policy-v4'and ratio between 1 and 2147483647));

-- Strengthen the trigger installed by custom-pool-setup-save-v3. A matching
-- number alone must never let the legacy V2 writer reinterpret a custom row.
create or replace function app.guard_custom_side_policy_v3()returns trigger
language plpgsql security definer set search_path=''as $$
declare ratio integer;begin
 select s.custom_ratio_denominator_v3 into ratio from app.tournament_setup_side_pool_materializations m
 join app.tournament_setup_side_pool_versions s on s.id=m.setup_side_pool_version_id and s.tournament_id=m.tournament_id
 where m.pool_id=new.pool_id and m.tournament_id=new.tournament_id and m.event_id=new.event_id;
 if ratio is not null then
  if tg_table_name<>'side_pool_graduated_policies_v2'then raise exception'custom_side_requires_graduated_policy_v4';end if;
  if new.method is distinct from'side-custom-graduated-policy-v4'then raise exception'custom_side_requires_graduated_policy_v4';end if;
  if new.ratio is distinct from ratio then raise exception'custom_side_ratio_mismatch_v3';end if;
  if not exists(select 1 from app.operation_receipts o where o.id=new.operation_receipt_id and o.tournament_id=new.tournament_id
   and o.actor_profile_id=new.actor_id and o.operation_type='side_pool_custom_operating_v4'and o.outcome='accepted')then raise exception'custom_side_policy_receipt_required_v4';end if;
 end if;
 return new;
end$$;
revoke all on function app.guard_custom_side_policy_v3()from public,anon,authenticated,service_role;

-- Reconstruct authority from the materialized pool, setup Side row, exact
-- setup intent, definition and accepted policy receipt.
create function app.custom_side_policy_binding_v4(tid uuid,eid uuid,pool uuid)
returns jsonb language sql stable security definer set search_path=''as $$
select jsonb_build_object(
 'kind','custom-side-policy-binding-v4','policyId',p.id,'operationReceiptId',p.operation_receipt_id,
 'poolId',p.pool_id,'method',p.method,'ratio',p.ratio,
 'amountMethod','graduated-custom-ratio-largest-remainder-5usd-v3',
 'definitionVersionId',p.definition_version_id,'definition',to_jsonb(d),
 'disclosureReference',p.disclosure_reference,'policyActorId',p.actor_id,
 'policyOperationId',o.client_operation_id,'policyRequestHash',o.request_hash,
 'materializationId',m.id,'materializationReceiptId',m.operation_receipt_id,
 'setupSidePoolVersionId',s.id,'setupRevisionId',s.setup_revision_id,
 'setupEventVersionId',s.setup_event_version_id,'eventClientRowId',e.client_row_id,
 'poolSlot',s.slot,'customRatio',s.custom_ratio_denominator_v3,'payoutType',s.payout_type,
 'setupBatchId',i.batch_id,'setupActorId',b.actor_id,'setupOperationId',b.operation_id,
 'setupRequestHash',b.request_hash,'originalIntent',i.original_intent,
 'baseSetupRevisionId',b.base_setup_revision_id,'baseSetupVersion',b.base_setup_version,
 'baseSourceDigest',b.base_source_digest)
from app.side_pool_graduated_policies_v2 p
join app.operation_receipts o on o.id=p.operation_receipt_id and o.tournament_id=p.tournament_id
 and o.operation_type='side_pool_custom_operating_v4'and o.outcome='accepted'
join app.event_side_pool_definition_versions d on d.id=p.definition_version_id and d.pool_id=p.pool_id
 and d.tournament_id=p.tournament_id and d.event_id=p.event_id
join app.tournament_setup_side_pool_materializations m on m.pool_id=p.pool_id and m.tournament_id=p.tournament_id and m.event_id=p.event_id
join app.tournament_setup_side_pool_versions s on s.id=m.setup_side_pool_version_id and s.tournament_id=m.tournament_id
join app.tournament_setup_event_versions e on e.id=s.setup_event_version_id and e.tournament_id=s.tournament_id and e.setup_revision_id=s.setup_revision_id
join app.setup_custom_payout_intents_v2 i on i.tournament_id=s.tournament_id and i.setup_revision_id=s.setup_revision_id
 and i.setup_event_version_id=s.setup_event_version_id and i.scope='side'and i.pool_slot=s.slot
 and i.ratio_denominator=p.ratio and i.amount_method='graduated-custom-ratio-largest-remainder-5usd-v3'
join app.setup_custom_payout_batches_v2 b on b.id=i.batch_id and b.tournament_id=i.tournament_id and b.setup_revision_id=i.setup_revision_id
where p.tournament_id=tid and p.event_id=eid and p.pool_id=pool
 and p.method='side-custom-graduated-policy-v4'and s.custom_ratio_denominator_v3=p.ratio and s.payout_type is null;
$$;
revoke all on function app.custom_side_policy_binding_v4(uuid,uuid,uuid)from public,anon,authenticated,service_role;

create function app.save_side_custom_policy_v4_impl(p_actor_id uuid,p_tournament_id uuid,p_event_id uuid,p_pool_id uuid,p_request jsonb,p_operation_id uuid)
returns jsonb language plpgsql security definer set search_path=''as $$
declare prior app.operation_receipts%rowtype;s app.tournament_setup_side_pool_versions%rowtype;
 e app.tournament_setup_event_versions%rowtype;d app.event_side_pool_definition_versions%rowtype;
 intent jsonb;source_value jsonb;h text;response jsonb;code text;
 ratio_value integer;setup_side_id uuid;definition_id uuid;
 rid uuid:=extensions.gen_random_uuid();oid uuid:=extensions.gen_random_uuid();
begin
 if coalesce(nullif(current_setting('request.jwt.claim.role',true),''),(nullif(current_setting('request.jwt.claims',true),'')::jsonb)->>'role','')<>'service_role'then return null;end if;
 if current_setting('transaction_isolation')<>'read committed'or p_actor_id is null or p_tournament_id is null or p_event_id is null or p_pool_id is null or p_operation_id is null then return null;end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor_id::text||':'||p_operation_id::text,0));
 perform 1 from app.tournaments where id=p_tournament_id and status in('draft','open')for no key update;if not found then return null;end if;
 perform 1 from app.tournament_roles where tournament_id=p_tournament_id and profile_id=p_actor_id and role in('director','co_director')for update;if not found then return null;end if;
 perform pg_advisory_xact_lock(hashtextextended('event-start:'||p_event_id::text,0));
 perform 1 from app.event_side_pools where id=p_pool_id and tournament_id=p_tournament_id and event_id=p_event_id for update;if not found then return null;end if;
 h:=encode(extensions.digest(convert_to(jsonb_build_array('side_pool_custom_operating_v4',p_actor_id,p_tournament_id,p_event_id,p_pool_id,p_request)::text,'utf8'),'sha256'),'hex');
 select*into prior from app.operation_receipts where actor_profile_id=p_actor_id and client_operation_id=p_operation_id;
 if found then
  if prior.tournament_id=p_tournament_id and prior.target_id=p_pool_id and prior.operation_type='side_pool_custom_operating_v4'and prior.request_hash=h then return prior.response_payload;end if;
  return jsonb_build_object('status','rejected','code','idempotency_conflict');
 end if;
 begin
  if jsonb_typeof(p_request)is distinct from'object'or(select count(*)from jsonb_object_keys(p_request))<>9
   or not(p_request?&array['action','setupSidePoolVersionId','definitionVersionId','method','ratio','amountMethod','disclosureReference','disclosed','intent'])
   or p_request->>'action'is distinct from'publish'or p_request->>'method'is distinct from'side-custom-graduated-policy-v4'
   or p_request->>'amountMethod'is distinct from'graduated-custom-ratio-largest-remainder-5usd-v3'or p_request->'disclosed'is distinct from'true'::jsonb
   or jsonb_typeof(p_request->'setupSidePoolVersionId')is distinct from'string'or coalesce(p_request->>'setupSidePoolVersionId','')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
   or jsonb_typeof(p_request->'definitionVersionId')is distinct from'string'or coalesce(p_request->>'definitionVersionId','')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
   or jsonb_typeof(p_request->'ratio')is distinct from'number'or coalesce(p_request->>'ratio','')!~'^[1-9][0-9]*$'or(p_request->>'ratio')::numeric>2147483647
   or jsonb_typeof(p_request->'disclosureReference')is distinct from'string'or length(trim(p_request->>'disclosureReference'))not between 1 and 500
   or p_request->>'disclosureReference'<>trim(p_request->>'disclosureReference')or p_request->>'disclosureReference'~'[[:cntrl:]]'
   or jsonb_typeof(p_request->'intent')is distinct from'object'then raise exception'invalid_request';end if;
  ratio_value:=(p_request->>'ratio')::integer;setup_side_id:=(p_request->>'setupSidePoolVersionId')::uuid;definition_id:=(p_request->>'definitionVersionId')::uuid;
  intent:=p_request->'intent';source_value:=intent->'source';
  if(select count(*)from jsonb_object_keys(intent))<>4 or not(intent?&array['kind','scope','ratioDenominator','source'])
   or intent->>'kind'is distinct from'custom-payout-intent-v1'or intent->>'scope'is distinct from'side'
   or intent->'ratioDenominator'is distinct from p_request->'ratio'or jsonb_typeof(source_value)is distinct from'object'
   or(select count(*)from jsonb_object_keys(source_value))<>6
   or not(source_value?&array['tournamentId','eventClientRowId','setupRevisionId','setupVersion','poolSlot','sourceDigest'])
   or source_value->>'tournamentId'is distinct from p_tournament_id::text
   or coalesce(source_value->>'eventClientRowId','')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
   or jsonb_typeof(source_value->'setupVersion')is distinct from'number'or coalesce(source_value->>'setupVersion','')!~'^(0|[1-9][0-9]*)$'
   or(source_value->>'setupVersion')::numeric>2147483647
   or((source_value->>'setupVersion')='0'and source_value->'setupRevisionId'is distinct from'null'::jsonb)
   or((source_value->>'setupVersion')<>'0'and coalesce(source_value->>'setupRevisionId','')!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$')
   or jsonb_typeof(source_value->'poolSlot')is distinct from'number'or coalesce(source_value->>'poolSlot','')!~'^[1-6]$'
   or coalesce(source_value->>'sourceDigest','')!~'^[a-f0-9]{64}$'then raise exception'invalid_request';end if;
  select side.*into s from app.tournament_setup_side_pool_materializations m
   join app.tournament_setup_side_pool_versions side on side.id=m.setup_side_pool_version_id and side.tournament_id=m.tournament_id
   where m.pool_id=p_pool_id and m.tournament_id=p_tournament_id and m.event_id=p_event_id and side.id=setup_side_id;
  if s.id is null then raise exception'setup_pool_mismatch';end if;
  select*into e from app.tournament_setup_event_versions where id=s.setup_event_version_id and tournament_id=s.tournament_id and setup_revision_id=s.setup_revision_id;
  if e.id is null or e.event_kind not in('main','consolation')then raise exception'unsupported_scope';end if;
  select*into d from app.event_side_pool_definition_versions where pool_id=p_pool_id and tournament_id=p_tournament_id and event_id=p_event_id order by version desc limit 1;
  if d.id is null or d.id<>definition_id or not d.active then raise exception'definition_changed';end if;
  if s.custom_ratio_denominator_v3 is distinct from ratio_value or s.payout_type is not null then raise exception'setup_method_conflict';end if;
  if d.entry_fee_minor not between 500 and 100000000 or mod(d.entry_fee_minor,500)<>0 then raise exception'unsupported_payout_domain';end if;
  if source_value->>'eventClientRowId'is distinct from e.client_row_id::text or(source_value->>'poolSlot')::smallint is distinct from s.slot then raise exception'custom_intent_required';end if;
  if not exists(select 1 from app.setup_custom_payout_intents_v2 i join app.setup_custom_payout_batches_v2 b
    on b.id=i.batch_id and b.tournament_id=i.tournament_id and b.setup_revision_id=i.setup_revision_id
   where i.tournament_id=p_tournament_id and i.setup_revision_id=s.setup_revision_id and i.setup_event_version_id=s.setup_event_version_id
    and i.scope='side'and i.pool_slot=s.slot and i.ratio_denominator=ratio_value
    and i.amount_method='graduated-custom-ratio-largest-remainder-5usd-v3'and i.original_intent=p_request->'intent')then raise exception'custom_intent_required';end if;
  if exists(select 1 from app.side_pool_graduated_policies_v2 where pool_id=p_pool_id)then raise exception'policy_frozen';end if;
  if app.event_play_state_v1(p_event_id)in('in_progress','completed','finalized')or exists(select 1 from app.event_side_pool_election_versions where pool_id=p_pool_id)then raise exception'collection_or_play_started';end if;
  response:=jsonb_build_object('status','side_custom_policy_published_v4','policyId',rid,'poolId',p_pool_id,'setupSidePoolVersionId',s.id,'definitionVersionId',d.id,'ratio',ratio_value,'amountMethod','graduated-custom-ratio-largest-remainder-5usd-v3','moneyMoved',false);
 exception when raise_exception or invalid_text_representation or numeric_value_out_of_range then
  code:=case when sqlerrm in('invalid_request','setup_pool_mismatch','unsupported_scope','definition_changed','setup_method_conflict','unsupported_payout_domain','custom_intent_required','policy_frozen','collection_or_play_started')then sqlerrm else'invalid_request'end;
  response:=jsonb_build_object('status','rejected','code',code);
 end;
 insert into app.operation_receipts(id,tournament_id,actor_profile_id,operation_type,target_id,request_hash,client_operation_id,outcome,response_payload,applied_at)
 values(oid,p_tournament_id,p_actor_id,'side_pool_custom_operating_v4',p_pool_id,h,p_operation_id,case when code is null then'accepted'else'rejected'end,response,case when code is null then clock_timestamp()else null end);
 if code is null then
  insert into app.side_pool_graduated_policies_v2(id,pool_id,tournament_id,event_id,definition_version_id,method,ratio,disclosure_reference,actor_id,operation_receipt_id)
  values(rid,p_pool_id,p_tournament_id,p_event_id,d.id,'side-custom-graduated-policy-v4',ratio_value,p_request->>'disclosureReference',p_actor_id,oid);
 end if;
 insert into app.audit_events(tournament_id,actor_profile_id,operation_receipt_id,entity_type,entity_id,action,after_state)
 values(p_tournament_id,p_actor_id,oid,'side_pool_custom_operating_v4',case when code is null then rid else p_pool_id end,case when code is null then'side_custom_policy_frozen_v4'else'side_custom_policy_rejected_v4'end,response);
 return response;
end$$;

create function app.get_side_custom_policy_reconciliation_v4_impl(p_actor_id uuid,p_tournament_id uuid,p_event_id uuid,p_pool_id uuid,p_operation_id uuid,p_request jsonb)
returns jsonb language plpgsql stable security definer set search_path=''as $$
declare r app.operation_receipts%rowtype;h text;begin
 if coalesce(nullif(current_setting('request.jwt.claim.role',true),''),(nullif(current_setting('request.jwt.claims',true),'')::jsonb)->>'role','')<>'service_role'or current_setting('transaction_isolation')<>'read committed'then return null;end if;
 if not exists(select 1 from app.tournament_roles where tournament_id=p_tournament_id and profile_id=p_actor_id and role in('director','co_director'))or not exists(select 1 from app.event_side_pools where id=p_pool_id and tournament_id=p_tournament_id and event_id=p_event_id)then return null;end if;
 h:=encode(extensions.digest(convert_to(jsonb_build_array('side_pool_custom_operating_v4',p_actor_id,p_tournament_id,p_event_id,p_pool_id,p_request)::text,'utf8'),'sha256'),'hex');
 select*into r from app.operation_receipts where actor_profile_id=p_actor_id and client_operation_id=p_operation_id;
 if not found then return jsonb_build_object('authorized',true,'result',null);end if;
 if r.tournament_id=p_tournament_id and r.target_id=p_pool_id and r.operation_type='side_pool_custom_operating_v4'and r.request_hash=h then return jsonb_build_object('authorized',true,'result',r.response_payload);end if;
 return jsonb_build_object('authorized',true,'result',jsonb_build_object('status','rejected','code','idempotency_conflict'));
end$$;
